	[1300] = {
		{ f="1300-3142c9a2", h="3142c9a2", t="Very well, let your journey of tailoring begin.", d=3.577, v="human-male-standard" },
		{ f="1300-d1216699", h="d1216699", t="Life is like a carefully woven tapestry.", d=3.306, v="human-male-standard" },
		{ f="1300-e17121fb", h="e17121fb", t="Hmm... the things you need to learn are a little above my head. Have a talk with Sellandus over at Larson's Clothiers just up the path to the right. He taught me everything I know!", d=11.984, v="human-male-standard" },
