	[1304] = {
		{ f="1304-0624ab70", h="0624ab70", t="Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise.", d=13.909, v="human-male-standard" },
		{ f="1304-23d8b931", h="23d8b931", t="I sell only the finest arcane gear, made by the crafters and mages here in the city of Stormwind.", d=6.421, v="human-male-standard" },
	},
	[1305] = {
