	[1317] = {
		{ f="1317-29729a1b", h="29729a1b", t="If you have what it takes, I will be happy to show you the way.", d=3.872, v="human-male-standard" },
		{ f="1317-c22f48e7", h="c22f48e7", t="Your confidence is well-founded, traveler. Now your true education may begin!", d=6.130, v="human-male-standard" },
		{ f="1317-c3ea1f53", h="c3ea1f53", t="You seem confident. Surely you wouldn't mind a test of your skills?", d=4.969, v="human-male-standard" },
		{ f="1317-f472d1d3", h="f472d1d3", t="A true professional know his limitations, and I'm not ashamed to admit that your skills exceed mine. I want you to pay a visit to Kitta Firewind at the Tower of Azora. She is well-renowned, and with good reason.", d=13.911, v="human-male-standard" },
		{ f="1317-fcbd9346", h="fcbd9346", t="You are not ready. Speak to Betty Quinn, she's standing by the stairs over there. Return to me when you have achieved a higher enlightenment.", d=10.608, v="human-male-standard" },
	},
	[1318] = {
		{ f="1318-0624ab70", h="0624ab70", t="Since the fall of Dalaran and the destruction of Quel'Thalas, wares of this sort have been hard to come by. But Lucan Cordell and some of our other Tradesman have been doing a fine job of filling our orders with quality merchandise.", d=13.320, v="human-female-standard" },
