	[1327] = {
		{ f="1327-a381f669", h="a381f669", t="Welcome to the Pig and Whistle! Grab a drink my friend and pull up a seat, the more the merrier!", d=5.718, v="human-male-official" },
	},
	[1333] = {
		{ f="1333-877c4b1d", h="877c4b1d", t="I sell only the best gear, tested and true. And the prices are set, so if you want to haggle then go find a Goblin.", d=6.443, v="human-male-official" },
