	[3033] = {
		{ f="3033-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=28.750, v="tauren-male-elder" },
		{ f="3033-8fca8484", h="8fca8484", t="If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes.", d=22.840, v="tauren-male-elder" },
		{ f="3033-a07c2cc0", h="a07c2cc0", t="Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to teach you.$B$BIt never hurts to reaffirm one's place within what I like to call the Great Balance.  As preservers of this balance, we must strive to continually keep our minds clear and our hearts strong.  Training helps us in this regard.", d=28.230, v="tauren-male-elder", g=true },
		{ f="3033-b554cff6", h="b554cff6", t="Welcome, my brother.  If you are here to train, then I would be delighted to teach you.  It never hurts to reaffirm one's place within what I like to call the Great Balance.  As preservers of this balance, we must strive to continually keep our minds clear and our hearts strong.  Training helps us in this regard.", d=24.310, v="tauren-male-elder" },
		{ f="3033-e18a6288", h="e18a6288", t="Strive to keep the balance in all things, $c.  This is where true harmony lies.", d=7.800, v="tauren-male-elder" },
		{ f="3033-febb65fa", h="febb65fa", t="Welcome, my sister.  If you are here to train, then I would be delighted to teach you.  It never hurts to reaffirm one's place within what I like to call the Great Balance.  As preservers of this balance, we must strive to continually keep our minds clear and our hearts strong.  Training helps us in this regard.", d=26.470, v="tauren-male-elder" },
	},
	[3034] = {
		{ f="3034-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=25.270, v="tauren-female-shaman" },
		{ f="3034-7b785024", h="7b785024", t="Many are the paths of the Earth Mother.  May your ancestors watch over you $c.", d=6.680, v="tauren-female-shaman" },
		{ f="3034-d1e27715", h="d1e27715", t="$n, how may I further your training in the eyes of the Earth Mother?", d=6.120, v="tauren-female-shaman" },
	},
