	[3044] = {
		{ f="3044-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=25.350, v="scourge-male-standard" },
		{ f="3044-0b88c316", h="0b88c316", t="Yes, $c?", d=3.280, v="scourge-male-standard" },
		{ f="3044-39920e92", h="39920e92", t="What can this insignificant servant do for you, $n? Training perhaps?", d=6.680, v="scourge-male-standard" },
		{ f="3044-66969eea", h="66969eea", t="Ah, you're the one who found the letter. Thank you for the... news, I suppose, about my family. You're welcome to what food and drink I can offer.", d=11.800, v="scourge-male-standard" },
	},
	[3045] = {
		{ f="3045-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=22.430, v="scourge-male-warrior" },
