	[4138] = {
		{ f="4138-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.640, v="nightelf-female-sentinel" },
		{ f="4138-c8a70fb5", h="c8a70fb5", t="What can I do for you my child?", d=2.914, v="nightelf-female-sentinel" },
		{ f="4138-f9b860f0", h="f9b860f0", t="I cannot train a $c such as yourself.", d=4.518, v="nightelf-female-sentinel" },
	},
	[4146] = {
		{ f="4146-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.884, v="nightelf-female-sentinel" },
		{ f="4146-b86d1736", h="b86d1736", t="Welcome to the Cenarion Circle, $c.", d=3.932, v="nightelf-female-sentinel" },
		{ f="4146-f9b860f0", h="f9b860f0", t="I cannot train a $c such as yourself.", d=3.998, v="nightelf-female-sentinel" },
	},
	[4155] = {
		{ f="4155-a8682cd0", h="a8682cd0", t="Welcome to the Bank of Darnassus. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us $g sir : ma'am;?", d=11.440, v="nightelf-female-priestess", g=true },
		{ f="4155-c78f83ac", h="c78f83ac", t="Welcome to the Bank of Darnassus. We offer financial accounts and safety deposit boxes for valuable items. Do you already have an account with us ma'am?", d=10.920, v="nightelf-female-priestess" },
	},
	[4156] = {
		{ f="4156-279d82d3", h="279d82d3", t="Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of \"The Bass and You\".  That is sure to help you increase your skill.", d=10.950, v="nightelf-female-standard" },
		{ f="4156-837eac47", h="837eac47", t="You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently.", d=7.273, v="nightelf-female-standard" },
		{ f="4156-c2467ddc", h="c2467ddc", t="I can teach you fishing skills.", d=2.343, v="nightelf-female-standard" },
	},
	[4159] = {
		{ f="4159-21d3a052", h="21d3a052", t="What a fine day! It inspires me to create a new design.", d=5.960, v="nightelf-female-priestess" },
		{ f="4159-328fd557", h="328fd557", t="There are basics that must be learned. Trianna is standing nearby, speak with her and return to me later.", d=7.080, v="nightelf-female-priestess" },
		{ f="4159-8afd918f", h="8afd918f", t="You have done well, traveler. I am proud to call you my student!", d=5.280, v="nightelf-female-priestess" },
		{ f="4159-ea239844", h="ea239844", t="Your talents excel! You are truly inspired. To continue your pursuit of knowledge, speak with Georgio Bolero in Stormwind. He is held in high regard, and will be able to further your instruction.", d=15.680, v="nightelf-female-priestess" },
	},
	[4160] = {
		{ f="4160-126c2b9a", h="126c2b9a", t="This potion seems to heal less damage every time I brew it, though I use the same ingredients. There can be only one conclusion: the plants are changing. I cannot say why or into what.", d=14.200, v="nightelf-female-priestess" },
		{ f="4160-4aeeff74", h="4aeeff74", t="Your skill at brewing potions needs to be greater before you can become one of my students. In the meantime, perhaps Sylvanna Forestmoon or Milla Fairancora can help you, just over there.", d=12.720, v="nightelf-female-priestess" },
		{ f="4160-a52edd3e", h="a52edd3e", t="Your education is progressing well. You should be proud of your accomplishments.", d=6.520, v="nightelf-female-priestess" },
		{ f="4160-fe17a639", h="fe17a639", t="It is time you moved on to a more advanced teacher. In the Feathermoon Stronghold of Feralas dwells the night elf Kylanna Windwhisper. She has a brilliant mind; doubtless she can train you further.", d=16.200, v="nightelf-female-priestess" },
	},
	[4163] = {
		{ f="4163-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=24.289, v="nightelf-female-sentinel" },
		{ f="4163-2ae1d72b", h="2ae1d72b", t="Greetings young rogue. What do you seek?", d=3.783, v="nightelf-female-sentinel" },
		{ f="4163-88dc2d97", h="88dc2d97", t="Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $n.", d=6.733, v="nightelf-female-sentinel" },
		{ f="4163-d3ecaafb", h="d3ecaafb", t="We are but darkness and shadows. Eternal. Invisible.", d=5.786, v="nightelf-female-sentinel" },
		{ f="4163-f69cc6ed", h="f69cc6ed", t="Greetings young rogue. What do you seek?", d=3.232, v="nightelf-female-sentinel" },
	},
	[4165] = {
		{ f="4165-1c7cd7a4", h="1c7cd7a4", t="I do not believe you possess the mental acuity to grasp the nature of portal magic.", d=6.400, v="human-female-official" },
		{ f="4165-6e89a35a", h="6e89a35a", t="As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready.", d=10.520, v="human-female-official" },
		{ f="4165-aa6f2374", h="aa6f2374", t="As a mage, you are one of a select group that can conjure a portal to transport you back to this very place.  I can teach you if you are ready.", d=10.400, v="human-female-official" },
	},
	[4184] = {
		{ f="4184-dd12f193", h="dd12f193", t="Ishnu-alah, traveler, and welcome to Nighthaven.    Would you like to browse my selection of fine dresses?", d=8.000, v="nightelf-female-standard" },
	},
	[4193] = {
		{ f="4193-32d2c576", h="32d2c576", t="Needlework requires a steady hand. And patience... above all, patience.", d=6.520, v="nightelf-male-standard" },
		{ f="4193-47d82412", h="47d82412", t="I would be happy to take you under my wing. Let us begin.", d=4.680, v="nightelf-male-standard" },
		{ f="4193-c4750f7c", h="c4750f7c", t="It is time for you to journey to Darnassus and speak to Me'lynn. She will guide you from now on.", d=6.880, v="nightelf-male-standard" },
	},
	[4200] = {
		{ f="4200-c2e88775", h="c2e88775", t="Although the coast of Darkshore is more dangerous than that of Teldrassil, many fishers find profit here.", d=7.280, v="nightelf-male-standard" },
	},
	[4205] = {
		{ f="4205-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=25.444, v="nightelf-male-warrior" },
		{ f="4205-ab633da8", h="ab633da8", t="Welcome to the Cenarion Circle, $c.  How may I assist you?", d=6.586, v="nightelf-male-warrior" },
		{ f="4205-f9b860f0", h="f9b860f0", t="I cannot train a $c such as yourself.", d=4.444, v="nightelf-male-warrior" },
	},
	[4210] = {
		{ f="4210-0c543544", h="0c543544", t="Cooking is a life long pursuit and I see we share the same passion!", d=5.280, v="nightelf-male-standard" },
		{ f="4210-3b48d638", h="3b48d638", t="Dirge Quikcleave of Gadgetzan is a master of the culinary arts.  To better yourself you will need to seek him out.", d=7.400, v="nightelf-male-standard" },
		{ f="4210-52392408", h="52392408", t="Seek out Shandrina in Silverwind Refuge.  She can sell you the \"Expert Cookbook\".", d=6.040, v="nightelf-male-standard" },
		{ f="4210-b48f927f", h="b48f927f", t="I can teach you how to cook!", d=2.200, v="nightelf-male-standard" },
	},
	[4211] = {
		{ f="4211-33af2c00", h="33af2c00", t="I've heard it said that Deneb Walker, holed up in Stromgarde, has a book that is sure to help improve your First Aid techniques.", d=8.440, v="nightelf-male-official" },
		{ f="4211-a28d29e1", h="a28d29e1", t="I can train you in First Aid techniques.", d=3.080, v="nightelf-male-official" },
		{ f="4211-c2e96a28", h="c2e96a28", t="The esteemed Doctor Gustaf VanHowzen can train you further.  He can be found in Theramore treating the wounded at the barracks.", d=10.320, v="nightelf-male-official" },
	},
	[4212] = {
		{ f="4212-6355ce9d", h="6355ce9d", t="I regret to say that I cannot aid you, $gnoble sir:gentle lady;, until you learn more of working with leather. Speak with Faldron or Darianna here instead. They can teach you the skill you require.", d=14.020, v="nightelf-male-warrior", g=true },
		{ f="4212-7f0dbc1a", h="7f0dbc1a", t="You have advanced beyond my skill to teach you. Journey now to Aerie Peak in the Hinterlands and speak with the dwarf Drakk Stonehand. His work is magnificent, far better than my own.", d=15.273, v="nightelf-male-warrior" },
		{ f="4212-ae0eba67", h="ae0eba67", t="The grass is soft and lush. The air is fresh, full of light and song. Everything I've seen suggests that Teldrassil is a dream come true. Why, then, is my heart full of foreboding?", d=14.545, v="nightelf-male-warrior" },
		{ f="4212-f099e750", h="f099e750", t="Do not try to force your will upon the leather. Rather, let its natural tendencies dictate what form and function it will take. This is not a battle to be won. Work with the leather, not against it.", d=14.020, v="nightelf-male-warrior" },
	},
	[4213] = {
		{ f="4213-42ae86de", h="42ae86de", t="It is true I have skills to teach to those who are worthy. Would that be you?", d=6.040, v="nightelf-male-official" },
		{ f="4213-bbaf25e8", h="bbaf25e8", t="You have not yet learned the basics, wanderer. Have you spoken to my assistant, Lalina Summermoon? Perhaps you should.", d=14.320, v="nightelf-male-official" },
		{ f="4213-deb690c8", h="deb690c8", t="You are an exceptional enchanter. Beyond my talents as a teacher, I fear. Seek out Kitta Firewind at the Tower of Azora. Only she can qualify as your instructor now.", d=12.200, v="nightelf-male-official" },
		{ f="4213-ec07c4ac", h="ec07c4ac", t="Fine work! You are truly deserving of the knowledge I shall bestow upon you!", d=8.000, v="nightelf-male-official" },
	},
	[4214] = {
		{ f="4214-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=26.737, v="nightelf-male-warrior" },
		{ f="4214-2ae1d72b", h="2ae1d72b", t="Greetings young rogue. What do you seek?", d=3.515, v="nightelf-male-warrior" },
		{ f="4214-88dc2d97", h="88dc2d97", t="Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $n.", d=7.354, v="nightelf-male-warrior" },
		{ f="4214-d5e1dfb6", h="d5e1dfb6", t="I don't train your kind $c.", d=3.515, v="nightelf-male-warrior" },
		{ f="4214-f69cc6ed", h="f69cc6ed", t="Greetings young rogue. What do you seek?", d=4.283, v="nightelf-male-warrior" },
	},
	[4215] = {
		{ f="4215-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=34.293, v="nightelf-male-warrior" },
		{ f="4215-88dc2d97", h="88dc2d97", t="Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $n.", d=7.313, v="nightelf-male-warrior" },
		{ f="4215-d5e1dfb6", h="d5e1dfb6", t="I don't train your kind $c.", d=3.232, v="nightelf-male-warrior" },
		{ f="4215-f69cc6ed", h="f69cc6ed", t="Greetings young rogue. What do you seek?", d=3.677, v="nightelf-male-warrior" },
	},
	[4217] = {
		{ f="4217-0acc4508", h="0acc4508", t="Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=19.920, v="nightelf-male-standard", g=true },
		{ f="4217-34f0a84a", h="34f0a84a", t="Welcome, my sister.  If you are here to train, then I would be delighted to train you.  There are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=23.120, v="nightelf-male-standard" },
		{ f="4217-54c391c0", h="54c391c0", t="What brings you to the Cenarion Circle, $N?", d=4.000, v="nightelf-male-standard" },
		{ f="4217-8fca8484", h="8fca8484", t="If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes.", d=16.280, v="nightelf-male-standard" },
	},
	[4218] = {
		{ f="4218-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=26.630, v="nightelf-male-official" },
		{ f="4218-0acc4508", h="0acc4508", t="Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=23.840, v="nightelf-male-official", g=true },
		{ f="4218-34f0a84a", h="34f0a84a", t="Welcome, my sister.  If you are here to train, then I would be delighted to train you.  There are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=22.280, v="nightelf-male-official" },
		{ f="4218-8fca8484", h="8fca8484", t="If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes.", d=18.920, v="nightelf-male-official" },
		{ f="4218-cb3f3465", h="cb3f3465", t="The blessings of Cenarius be yours, $c.  Our leader, Arch Druid Staghelm, guides us and all of Teldrassil to a renewed life!", d=11.040, v="nightelf-male-official" },
	},
	[4219] = {
		{ f="4219-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.788, v="nightelf-male-warrior" },
		{ f="4219-0acc4508", h="0acc4508", t="Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BThere are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=23.434, v="nightelf-male-warrior", g=true },
		{ f="4219-34f0a84a", h="34f0a84a", t="Welcome, my sister.  If you are here to train, then I would be delighted to train you.  There are rumors of strife within the Cenarion Circle, but you should pay such loose talk no heed.  Our Arch Druid, Fandral Staghelm, leads us and all of Teldrassil to glory!", d=21.091, v="nightelf-male-warrior" },
		{ f="4219-cb3f3465", h="cb3f3465", t="The blessings of Cenarius be yours, $c.  Our leader, Arch Druid Staghelm, guides us and all of Teldrassil to a renewed life!", d=11.273, v="nightelf-male-warrior" },
	},
	[4241] = {
		{ f="4241-b0e0696e", h="b0e0696e", t="It is my honor to provide for adventurers, for they are heroes in the making.", d=6.000, v="nightelf-male-official" },
	},
	[4256] = {
		{ f="4256-ec4d19c0", h="ec4d19c0", t="If you ask me, there's no greater profession than a miner.  And if you ask me, there's no greater miner than a dwarf!", d=9.240, v="dwarf-male-guard" },
	},
	[4258] = {
		{ f="4258-34391ad9", h="34391ad9", t="I'm sorry $g lad : lass; but ye just don't have the foundation to learn what I have to teach. But don't fret, go speak with my student Rotgath, he'll help ye out.", d=10.360, v="dwarf-male-guard", g=true },
		{ f="4258-5a9d833c", h="5a9d833c", t="Ye have the look of a Blacksmith to ye. Soot under the nails, steel in yer bones. Aye, very much the blood of a Blacksmith in yer veins. Which means ye've come to me looking to learn a thing or two, well $g lad : lass; grab a hammer. Let's see what I can teach ye.", d=19.760, v="dwarf-male-guard", g=true },
		{ f="4258-72bdd3d6", h="72bdd3d6", t="I can't say enough about yer work, truly amazing things that ye can do with a hammer and an anvil. Now, don't be tellin anyone that I suggested ye go find a goblin to teach ye but that's exactly what I'm gonna do. Brikk Keencraft is his name, and last I heard he was operating a shop down in Booty Bay.", d=21.870, v="dwarf-male-guard" },
		{ f="4258-92cfadea", h="92cfadea", t="I'm sorry lad but ye just don't have the foundation to learn what I have to teach. But don't fret, go speak with my student Rotgath, he'll help ye out.", d=11.120, v="dwarf-male-guard" },
		{ f="4258-965533ff", h="965533ff", t="Welcome to the Great Forge lad. It may be cold outside but we keep it nice and hot down 'ere. Grab a hammer, strike that anvil and show me ye've got what it takes to be a Blacksmith of the Great Forge!", d=14.600, v="dwarf-male-guard" },
		{ f="4258-bb4782c1", h="bb4782c1", t="I hope ye didn't come all the way to the Great Forge just to stay warm. Speak up $g lad : lass;, tell me what it is I can do for ye?", d=7.920, v="dwarf-male-guard", g=true },
	},
	[4262] = {
		{ f="4262-04ae0525", h="04ae0525", t="If that is your wish $c, then you will need to speak to Keras Wolfheart on the Warrior's Terrace.  He is a representative of The League of Arathor and can help you to get to Arathi Basin.", d=14.980, v="nightelf-female-sentinel" },
		{ f="4262-0b538a46", h="0b538a46", t="It is Vesprystus that you seek.  He watches over the hippogryphs that come and go from the base of Teldrassil.  You will find him through the portal in western Darnassus that will take you to Rut'theran Village.", d=11.341, v="nightelf-female-sentinel" },
		{ f="4262-0d45051f", h="0d45051f", t="I know just the one that you speak of $c. You must seek out Brogun Stoneshield on the Warrior's Terrace.", d=7.822, v="nightelf-female-sentinel" },
		{ f="4262-0d8932e3", h="0d8932e3", t="You can trust any pets you have to be well taken care of by Alassin.  He resides in the Cenarion Enclave where the hunters gather.", d=8.875, v="nightelf-female-sentinel" },
		{ f="4262-0eea32d4", h="0eea32d4", t="You would certainly be looking for Me'Lynn if you have any hope of learning to be a tailor.  She resides at the Craftsmen's Terrace in northeastern Darnassus.", d=9.790, v="nightelf-female-sentinel" },
		{ f="4262-0ff252d7", h="0ff252d7", t="You may find storage for your worldly goods at the bank of Darnassus, which lies in the center of our wondrous city.", d=8.256, v="nightelf-female-sentinel" },
		{ f="4262-11e7f1ea", h="11e7f1ea", t="Ever vigilant in their protection of the natural world, the druids are guided by Arch Druid Fandral Staghelm who resides in the Cenarion Enclave.  You will find him and the other Druid trainers in the northern section of Darnassus.", d=16.800, v="nightelf-female-sentinel" },
		{ f="4262-12086219", h="12086219", t="A time consuming, yet rewarding skill.  Speak with Astaia in the Tradesman's Terrace and maybe you'll learn something useful.", d=9.056, v="nightelf-female-sentinel" },
		{ f="4262-12b4d0ae", h="12b4d0ae", t="Lysheana can offer you the proper documents, she resides in the Craftsmen's Terrace in northeasten Darnassus.  May your fellowship bring glory to the Night Elves!", d=12.048, v="nightelf-female-sentinel" },
		{ f="4262-1a4941ed", h="1a4941ed", t="I'm flattered, but really I'm not interested... What?  You want to know where to learn enchanting?  Oh, how embarrassing!  Well, you should...  I'm sure you could... go see, um...  Taladan!  Yes, see Taladan over in the Craftsmen's Terrace!", d=16.877, v="nightelf-female-sentinel" },
		{ f="4262-1f2fd981", h="1f2fd981", t="Sildinair has trained many of the Sentinels who guard our beloved city.  I am certain she can make a warrior out of the likes of you.  Seek her out at the Warrior's Terrace near the entrance to our city.", d=13.930, v="nightelf-female-sentinel" },
		{ f="4262-1f6ea775", h="1f6ea775", t="A mailbox?  You have a letter to send, or perhaps have received one?  I hope it's something good!  There's a mailbox right outside of the Bank in the center of Darnassus.", d=11.924, v="nightelf-female-sentinel" },
		{ f="4262-20933114", h="20933114", t="Through the milennia, Ilyenia Moonfire has mastered numerous weapons and now offers to train others in their use.  You can find her at the Warrior's Terrace if you desire training.", d=12.614, v="nightelf-female-sentinel" },
		{ f="4262-21ab523d", h="21ab523d", t="Here in Darnassus you will find skilled trainers who have perfected the skills of their chosen class through ages of training and dedication.  I will guide you to one who can become your mentor, you have but to name your chosen path.", d=15.025, v="nightelf-female-sentinel" },
		{ f="4262-23fa63a4", h="23fa63a4", t="The Stormpike Guard is in need of your assistance in the fight against the Frostwolf Clan, $n. Speak to Brogun Stoneshield on the Warrior's Terrace and he will help you find your way to Alterac Valley. Elune be praised!", d=15.431, v="nightelf-female-sentinel" },
		{ f="4262-2c901e7c", h="2c901e7c", t="Elune be praised!  You seek out our Warsong Gulch Battlemaster?  Her name is Aethalas, and she stands ready to greet you near the warrior trainers.", d=11.053, v="nightelf-female-sentinel" },
		{ f="4262-35caf48a", h="35caf48a", t="You will find Sildinair at the Warrior's Terrace among the guards, her keen eyes scanning the forest for enemies that might dare to enter our fair city.  ", d=10.290, v="nightelf-female-sentinel" },
		{ f="4262-3674addc", h="3674addc", t="When you have not a healer to tend to your wounds, the knowledge of First Aid can be a lifesaver.  I would consult Dannelor over at the Craftsmen's Terrace for instruction on this skill.", d=10.581, v="nightelf-female-sentinel" },
		{ f="4262-36763980", h="36763980", t="There is a mailbox outside of the Bank which you'll find in the center of Darnassus.", d=6.767, v="nightelf-female-sentinel" },
		{ f="4262-3f90489a", h="3f90489a", t="Another material $gboy : girl; are we?  Well, if you are obsessed with your precious items then you will probably want to store them at the Darnassus Bank in the center of our city.", d=10.732, v="nightelf-female-sentinel", g=true },
		{ f="4262-42b9a196", h="42b9a196", t="The gathering and knowledge of herbs is a specialty of Firodren Mooncaller.  Seek him out in the Temple Gardens in the southwestern area of Darnassus.", d=9.932, v="nightelf-female-sentinel" },
		{ f="4262-447ae6f2", h="447ae6f2", t="There are several battlegrounds from which to choose.  To which battlemaster shall I send you?", d=6.762, v="nightelf-female-sentinel" },
		{ f="4262-4531a9a2", h="4531a9a2", t="Has the sun risen already?  There are just never enough hours in the night!  Well, Saelienne will take good care of you.  You can find her tending to her guests over in the Craftsmen's Terrace in northeastern Darnassus.", d=14.549, v="nightelf-female-sentinel" },
		{ f="4262-4a8ea05c", h="4a8ea05c", t="The power of Elune compels you!  The power of Elune compels you!    Go now!  Seek out Jandria in the central hall of the Temple of the Moon in the southern section of Darnassus!", d=12.407, v="nightelf-female-sentinel" },
		{ f="4262-4fce9f9c", h="4fce9f9c", t="The Temple of the Moon is home to the priests of Elune.  There you will find Jandria and Lariia, who will provide you with further guidance in the path of priesthood.", d=12.692, v="nightelf-female-sentinel" },
		{ f="4262-5979b0ab", h="5979b0ab", t="As a culture we believe in letting nothing go to waste.  When we are forced to slay a creature we take what we can to make sure its sacrifice was not in vain.    If you wish to learn the proper way to take the skin of a slain beast, then seek out Eladriel in the Craftsmen's Terrace.", d=17.506, v="nightelf-female-sentinel" },
		{ f="4262-5a295268", h="5a295268", t="Another material girl are we?  Well, if you are obsessed with your precious items then you will probably want to store them at the Darnassus Bank in the center of our city.", d=11.781, v="nightelf-female-sentinel" },
		{ f="4262-5d75d4cf", h="5d75d4cf", t="An alchemist?  No trouble at all $c.  Ainethil, in all her labor and toil, has become the most accomplished alchemist in the Craftsmen's Terrace.  I would head over there on the double if I were you. On the double!  Now off with you!", d=14.437, v="nightelf-female-sentinel" },
		{ f="4262-60c9b8b6", h="60c9b8b6", t="Though I find the cool grass which covers Teldrassil as good a bed as any, the beds which Saelienne keeps at the Inn in Craftsman's Terrace are quite suitable for those with a taste for luxury.", d=12.114, v="nightelf-female-sentinel" },
		{ f="4262-6269ccf1", h="6269ccf1", t="The dishes that Alegorn whips up are to die for.  He's always busy preparing new delicacies over in the Craftsman's Terrace.  Be sure to try his Cenarion Green recipe if he has any left.    Now, if you don't mind, I must investigate this rash of missing deer. ", d=18.740, v="nightelf-female-sentinel" },
		{ f="4262-84b403e6", h="84b403e6", t="Astaia has fished up some curious treasures over the ages she has spent fishing.  Why don't you go see her over in the Tradesman's terrace and have her show you some of them.", d=10.938, v="nightelf-female-sentinel" },
		{ f="4262-882efe61", h="882efe61", t="It is Syurna that you seek if you are to follow the rogue's path.  She dwells in the Cenarion Enclave down the spiraling path within the western most tree.", d=10.985, v="nightelf-female-sentinel" },
		{ f="4262-8ab3f246", h="8ab3f246", t="In death, the animals of the world bestow both life and protection unto us.  If you feel that you can offer the appropriate respect for their sacrifice, then the skinner's profession may suit you.  Speak with Eladriel in the Craftsman's Terrace in northern Darnassus to learn more.", d=20.000, v="nightelf-female-sentinel" },
		{ f="4262-8fd28cf1", h="8fd28cf1", t="The humans definitely need all of our help in Arathi Basin.  The one that you wish to speak to is named Keras Wolfheart.  He stands ready to assist you on the Warrior's Terrace.", d=12.996, v="nightelf-female-sentinel" },
		{ f="4262-90df76a3", h="90df76a3", t="Ah, are you looking perhaps to change your markings, or prepare for a hunt? There is no better place.    You will find the barber in the Tradesman's Terrace, near the auction house.", d=11.972, v="nightelf-female-sentinel" },
		{ f="4262-96761fec", h="96761fec", t="In grizzly times a druid can be a dear friend to those around them.  Ask any of the druids in the Cenarion Enclave and they will tell you the same.", d=8.768, v="nightelf-female-sentinel" },
		{ f="4262-9bd51f3f", h="9bd51f3f", t="Oh, the ever-present obsession with material wealth.  Well, fortune smiles on you, as you can find the auction house in the Tradesman's Terrace.", d=11.938, v="nightelf-female-sentinel" },
		{ f="4262-a0857e64", h="a0857e64", t="In grizzly times a druid can be a dear friend to those around them.  Ask any of the druids in the Cenarion Enclave and they will tell you the same.", d=9.236, v="nightelf-female-sentinel" },
		{ f="4262-a0975d94", h="a0975d94", t="I received the majority of my weapons training from Ilyenia Moonfire in the Warrior's Terrace.  You would do well to seek her out if you desire to learn the use of a new weapon.  ", d=13.454, v="nightelf-female-sentinel" },
		{ f="4262-aa00d340", h="aa00d340", t="There are those that attempt to follow the path of the Rogue, but only the night elves are truly embraced by the night.  If you seek to walk the shaded path then find Syurna in the Cenarion Enclave.", d=14.619, v="nightelf-female-sentinel" },
		{ f="4262-b05df6ee", h="b05df6ee", t="For many hundreds of years Alassin has cared for the animals that our hunters befriend.  His care of animals is highly sought for by the hunters around here.  If you seek him as well, then look for him in the Cenarion Enclave.", d=15.865, v="nightelf-female-sentinel" },
		{ f="4262-c17abfb6", h="c17abfb6", t="Because the blade can never be too sharp nor the armor too tough a talented enchanter will always be needed.  Such an enchanter is Taladan, who can show you how to properly weave enchantments to improve your weapons and armor.  Seek him out in the Craftsmen's Terrace.", d=17.899, v="nightelf-female-sentinel" },
		{ f="4262-cb2c7676", h="cb2c7676", t="Jocaste was the greatest of Hunters of her time.  These days you can find her over in the Cenarion Enclave where she teaches those who are just starting down the Hunter's path.", d=12.947, v="nightelf-female-sentinel" },
		{ f="4262-ce424d00", h="ce424d00", t="Of all the wondrous places within Darnassus, which would you have me direct you to?", d=6.951, v="nightelf-female-sentinel" },
		{ f="4262-d3a25a4e", h="d3a25a4e", t="Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen's Terrace.", d=16.184, v="nightelf-female-sentinel" },
		{ f="4262-d7aed8f7", h="d7aed8f7", t="Vesprystus' hippogryphs will bear you swiftly to your destination.  Seek him out in Rut'theran Village, through the portal which lies in the western section of Darnassus.", d=12.000, v="nightelf-female-sentinel" },
		{ f="4262-ddb85611", h="ddb85611", t="If you desire to form a fellowship then it is the guild master, Lysheana, that you must see.  You will find her in the Craftsmen's Terrace in the northeastern section of Darnassus.", d=13.457, v="nightelf-female-sentinel" },
		{ f="4262-e07232c6", h="e07232c6", t="Here among the craftsmen of Darnassus, there is a millenium of knowledge for the benefit of your chosen craft.  Now tell me, which craft do you find the most intriguing?", d=11.603, v="nightelf-female-sentinel" },
		{ f="4262-e1679d7e", h="e1679d7e", t="It is no light endeavor upon which you embark $n.  To get to Warsong Gulch you will want to speak to Aethalas, the Battlemaster of the Silverwing Sentinels.  She will guide your way.  Blessings of the Goddess be with you!", d=15.424, v="nightelf-female-sentinel" },
		{ f="4262-e45b7add", h="e45b7add", t="If you truly have the desire to learn this profession, then I would point you in the direction of Ainethil, a skilled alchemist at the Craftsmen's Terrace in northern Darnassus.", d=12.621, v="nightelf-female-sentinel" },
		{ f="4262-e46068cf", h="e46068cf", t="We plant the vegetables.  Our vegetables are eaten by the rabbit.  The rabbit is devoured by the wolf.  The wolf is slain by us.  We take the meat and hide from the wolf's corpse.  It's that Magic Circle of life, or whatever you call it.    Now go see Telonis in the Cenarion Enclave to get started and let me return to my duties.", d=25.849, v="nightelf-female-sentinel" },
		{ f="4262-e66389a6", h="e66389a6", t="One has opened up on the Tradesman's Terrace.  If you take the path leading Southeast from the bank, it should be easy to find.", d=8.691, v="nightelf-female-sentinel" },
		{ f="4262-e74436e4", h="e74436e4", t="With the garments that Me'Lynn tailors, one might think that her needle was blessed by Elune herself.  Unless your needle is so blessed, you best pay her a visit and listen to her teachings.  You can find her in The Craftsmen's Terrace in northeastern Darnassus.", d=16.596, v="nightelf-female-sentinel" },
		{ f="4262-f45860d6", h="f45860d6", t="You are fortunate to have come to Darnassus where you can find such an accomplished Hunter as Jocaste among our trainers.  I encourage you to visit her over in the Cenarion Enclave and seek her tutelage.", d=13.675, v="nightelf-female-sentinel" },
		{ f="4262-f71d5637", h="f71d5637", t="The skill with which Telonis crafts armor is beyond compare.  You should be grateful that he does not charge more for the knowledge he passes to others.  Go now and seek him out in the Craftsmen's Terrace in the northeast section of Darnassus.", d=14.845, v="nightelf-female-sentinel" },
		{ f="4262-ffcad06a", h="ffcad06a", t="A budding herbalist are we?  Then you should visit with Firodren Mooncaller over in the Temple Gardens.  He may have some tricks of the trade to impart with you.", d=10.764, v="nightelf-female-sentinel" },
	},
	[4267] = {
		{ f="4267-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.303, v="nightelf-female-standard", s={ ["m"]=2.160 } },
	},
	[4312] = {
		{ f="4312-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=1.781, v="tauren-male-warrior" },
	},
	[4314] = {
		{ f="4314-4744a647", h="4744a647", t="I'm going to stay here until I catch a 68 Pound Grouper!  You on the other hand want to fly off somewhere, am I right?", d=9.249, v="orc-male-standard" },
		{ f="4314-b8b73987", h="b8b73987", t="Can't you see I'm fishing here!", d=2.510, v="orc-male-standard" },
		{ f="4314-c043f14f", h="c043f14f", t="You scared the fish away!  What do you want?", d=4.261, v="orc-male-standard" },
		{ f="4314-c3fc398b", h="c3fc398b", t="What can I do for you $c?", d=2.345, v="orc-male-standard" },
	},
	[4317] = {
		{ f="4317-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.224, v="tauren-female-official" },
	},
	[4319] = {
		{ f="4319-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.707, v="nightelf-female-standard" },
	},
	[4320] = {
		{ f="4320-0e051c59", h="0e051c59", t="You've come for training in order to pass it on to your pets?", d=3.760, v="nightelf-male-standard" },
		{ f="4320-4ef1d72e", h="4ef1d72e", t="Ah friend, I only help hunters and their pets.", d=4.520, v="nightelf-male-standard" },
	},
	[4321] = {
		{ f="4321-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.320, v="dwarf-male-guard" },
	},
	[4407] = {
		{ f="4407-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=1.920, v="nightelf-male-standard" },
	},
	[4419] = {
		{ f="4419-361d3b3a", h="361d3b3a", t="Hello, $c!  Welcome to the races at the Shimmering Flats!", d=5.320, v="dwarf-male-standard" },
		{ f="4419-56a29b40", h="56a29b40", t="Who has the fastest car?  Who knows?!?", d=3.240, v="dwarf-male-standard" },
		{ f="4419-c58d3fa3", h="c58d3fa3", t="Plucky doesn't want Tirth to know he's still in the Shimmering Flats, so he turned himself into a chicken!$B$BIf you find Plucky, beckon him to you.  Maybe he'll come out of hiding.", d=9.680, v="dwarf-male-standard" },
		{ f="4419-f727dc49", h="f727dc49", t="Welcome to the races!  Enjoy your stay, and don't bet all your money in one place!", d=7.280, v="dwarf-male-standard" },
		{ f="4419-fd2a174f", h="fd2a174f", t="The goblin racer packs a lot of punch, but the gnomes hid a trick or two in their car...", d=5.520, v="dwarf-male-standard" },
	},
	[4429] = {
		{ f="4429-143f8a9a", h="143f8a9a", t="My money's on the goblins!  And if you have any sense then yours is too!", d=5.120, v="goblin-male-guard" },
		{ f="4429-3785ab5a", h="3785ab5a", t="I heard they were going to try to blow up the gnome's car in the next race!  True or not, I'd stand clear of their pit area.", d=7.320, v="goblin-male-guard" },
		{ f="4429-37f147d0", h="37f147d0", t="Oh, you mean Johnson?  I heard he's in hiding.", d=3.840, v="goblin-male-guard" },
		{ f="4429-89022ad5", h="89022ad5", t="If I were you, I'd buy a goblin race voucher.  Rooting for the other team is a waste of time.", d=7.400, v="goblin-male-guard" },
		{ f="4429-b4b02a58", h="b4b02a58", t="Hah!  Tirth's been looking for him for days, but he doesn't want to be found.  He's chicken!", d=8.120, v="goblin-male-guard" },
		{ f="4429-b513622f", h="b513622f", t="You looking for plucky?  Well, you didn't hear me say this, but... maybe if you ask Kronkrider up in the tower, he'll tell you...", d=8.480, v="goblin-male-guard" },
		{ f="4429-d81eed45", h="d81eed45", t="If you ask me, I think the goblins are a shoe in.  We have the tools, and we have the talent!", d=7.040, v="goblin-male-guard" },
		{ f="4429-dae00750", h="dae00750", t="If it weren't for that cursed, gnomish luck, they'd never win a race!", d=5.440, v="goblin-male-guard" },
	},
	[4430] = {
		{ f="4430-1eae49d1", h="1eae49d1", t="I installed a new device in our car's matrix regulometer.  That should increase its velocity quotient by a factor of no less than fifteen!", d=5.816, v="gnome-female-nerdy", s={ ["m"]=10.760 } },
		{ f="4430-2bb8230b", h="2bb8230b", t="These races are a great opportunity to show our ingenuity!", d=3.244, v="gnome-female-nerdy", s={ ["m"]=4.000 } },
		{ f="4430-38e78862", h="38e78862", t="Tirth's not himself these days, and neither is his assistant.", d=2.621, v="gnome-female-nerdy", s={ ["m"]=4.080 } },
		{ f="4430-4ecb00d7", h="4ecb00d7", t="Plucky?  I heard race master Kronkrider up on the the tower knows where he is.", d=3.678, v="gnome-female-nerdy", s={ ["m"]=5.880 } },
		{ f="4430-612c4cf5", h="612c4cf5", t="If it weren't for the goblins' inconceivable, dumb luck, they'd crash their car during every race!", d=4.591, v="gnome-female-nerdy", s={ ["m"]=6.240 } },
		{ f="4430-7689341a", h="7689341a", t="My Gizmotic Almanacotron says that we should beat the goblins by twenty seconds more than we did last time!", d=4.509, v="gnome-female-nerdy", s={ ["m"]=7.160 } },
		{ f="4430-b23e7a47", h="b23e7a47", t="Johnson?  I think he's around here somewhere...", d=2.045, v="gnome-female-nerdy", s={ ["m"]=2.920 } },
		{ f="4430-da38516b", h="da38516b", t="My son could design a faster car than that clunky goblin junk heap!", d=4.110, v="gnome-female-nerdy", s={ ["m"]=5.360 } },
	},
	[4452] = {
		{ f="4452-a84fd61d", h="a84fd61d", t="Come a little closer.  We have important matters to discuss, you and I.  And some of them we don't want everyone to hear...", d=6.240, v="dwarf-male-grim" },
	},
	[4456] = {
		{ f="4456-0be64368", h="0be64368", t="No, Longears isn't my real name.  And I'm not going to tell you what it is, so don't ask.", d=6.680, v="bloodelf-female" },
	},
	[4488] = {
		{ f="4488-541d5ec8", h="541d5ec8", t="Now, answer me this, $n:$BWhich creature became the Lich King before spreading the plague across Lordaeron?", d=9.920, v="scourge-male-standard" },
		{ f="4488-642d4f58", h="642d4f58", t="It's always nice when someone wishes to speak to me. How are things with you, $c?", d=7.760, v="scourge-male-standard" },
	},
	[4489] = {
		{ f="4489-d4f863ac", h="d4f863ac", t="Greetings, $c. Is there something I can help you with?", d=5.320, v="tauren-male-shaman" },
		{ f="4489-d9f65c9b", h="d9f65c9b", t="My question to you is this, $c: Which of the Aspects created by the titans became the nefarious creature known as Deathwing?", d=10.200, v="tauren-male-shaman" },
	},
	[4542] = {
		{ f="4542-09c3bc91", h="09c3bc91", t="The Highlord was the lynchpin of the Crusade. Aye, Mograine was called the Ashbringer because of his exploits versus the armies of the Lich King. With only blade and faith, Mograine would walk into whole battalions of undead and emerge unscathed - the ashes of his foes being the only indication that he had been there at all. Do you not understand? The very face of death feared him! It trembled in his presence!", d=31.470, v="scourge-male" },
		{ f="4542-12c0f2a2", h="12c0f2a2", t="I'm afraid that the blade which you hold in your hands is beyond saving. The hatred runs too deep. But do not lose hope, $c. Where one chapter has ended, a new one begins.$B$BFind his son - a more devout and pious man you may never meet. It is rumored that he is able to build the Ashbringer anew, without requiring the old, tainted blade.", d=30.470, v="scourge-male" },
		{ f="4542-220ab747", h="220ab747", t="The boy had picked up the Ashbringer and driven it through his father's heart as his back was turned. His last words will haunt me forever: \"What have you done, Renault? Why would you do this?\"", d=13.600, v="scourge-male" },
		{ f="4542-3f03d50c", h="3f03d50c", t="This was the Ashbringer, fool! As the Scourge began to materialize around us, Mograine's blade began to glow... to hum... the younger Mograine would take that as a sign to make his escape. They descended upon us with a hunger the likes of which I had never seen. Yet...", d=19.680, v="scourge-male" },
		{ f="4542-46733107", h="46733107", t="It was not enough.$B$B<Fairbanks smirks briefly, lost in a memory.>$B$BA thousand came and a thousand died. By the Light! By the might of Mograine! He would smite them down as fast as they could come. Through the chaos, I noticed that the lesser Mograine was still there, off in the distance. I called to him, \"Help us, Renault! Help your father, boy!\"", d=23.320, v="scourge-male", P={ { d=1.520 }, { d=3.320, n=true }, { d=22.600 } }, nP={ [1]={ [2]=3.760 } } },
		{ f="4542-48ea9cb7", h="48ea9cb7", t="The blade and Mograine were a singular entity. Do you understand? This act corrupted the blade and lead to Mograine's own corruption as a death knight of Kel'Thuzad. I swore that if I lived, I would expose the perpetrators of this heinous crime. For two days I remained under the rot and contagion of Scourge - gathering as much strength as possible to escape the razed city. ", d=28.470, v="scourge-male" },
		{ f="4542-52fc4c1f", h="52fc4c1f", t="The only way a hero can die, $r: Through tragedy. The Grand Crusader struck a deal with Kel'Thuzad himself! An ambush would be staged that would result in the death of Mograine. The type of betrayal that could only be a result of the actions of one's most trusted and loved companions.", d=22.680, v="scourge-male" },
		{ f="4542-67948ab9", h="67948ab9", t="<High Inquisitor Fairbanks shakes his head.>$B$BNo... He stood in the background, watching as the legion of undead descended upon us. Soon after, my powers were exhausted. I was the first to fall... Surely they would tear me limb from limb as I lay there unconscious; but they ignored me completely, focusing all of their attention on the Highlord. ", d=22.440, v="scourge-male", P={ { d=3.000, n=true }, { d=20.920 } }, nP={ [1]={ [1]=3.680 } } },
		{ f="4542-c0426aeb", h="c0426aeb", t="<High Inquisitor Fairbanks nods.>$B$BAye, the lesser Mograine, the one known as the Scarlet Commander, through - what I suspect - the dealings of the Grand Crusader. He led his father to the ambush like a lamb to the slaughter.", d=12.600, v="scourge-male", P={ { d=3.120, n=true }, { d=14.880 } }, nP={ [1]={ [1]=3.640 } } },
		{ f="4542-ceb8631e", h="ceb8631e", t="<High Inquisitor Fairbanks shakes his head.>$B$BNo, $r; only one of his sons is dead. The other lives...$B$B<High Inquisitor Fairbanks points to the sky.>$B$BThe Outland... Find him there... ", d=9.760, v="scourge-male", P={ { d=2.920, n=true }, { d=6.240 }, { d=3.600, n=true }, { d=2.920 } }, nP={ [1]={ [1]=3.680, [3]=4.080 } } },
		{ f="4542-dcfbef76", h="dcfbef76", t="You mean, you don't know? The sword that you carry on your back - it is known as Ashbringer; named after its original owner.", d=9.080, v="scourge-male" },
		{ f="4542-df4d7871", h="df4d7871", t="<High Inquisitor Fairbanks lifts up his tabard revealing several gruesome scars.>$B$BBecause I was there... I was the Highlord's most trusted advisor. I should have known... I felt that something was amiss yet I allowed it to happen. Would you believe that there were a thousand or more Scourge?", d=16.120, v="scourge-male", P={ { d=6.240, n=true }, { d=16.840 } }, nP={ [1]={ [1]=6.800 } } },
		{ f="4542-e1ce7ed4", h="e1ce7ed4", t="It was High General Abbendis, High Inquisitor Isillien, and Highlord Mograine that formed the Crusade. In its infancy, the Crusade was a noble order. The madness and insane zealotry that you see now did not exist. It was not until the one known as the Grand Crusader appeared that the wheels of corruption were set in motion.", d=25.270, v="scourge-male" },
		{ f="4542-e5b77f39", h="e5b77f39", t="It was all I could do to feign death as the corpses of the Scourge piled upon me. There was darkness and only the muffled sounds of the battle above me. The clashing of iron, the gnashing and grinding... gruesome, terrible sounds. And then there was silence. He called to me! \"Fairbanks! Fairbanks where are you? Talk to me Fairbanks!\" And then came the sound of incredulousness. The bite of betrayal, $r...", d=30.790, v="scourge-male" },
		{ f="4542-ef1af7f8", h="ef1af7f8", t="Aye, I did. Much to the dismay of the lesser Mograine, I made my way back to the Scarlet Monastery. I shouted and screamed. I told the tale to any that would listen. And I would be murdered in cold blood for my actions, dragged to this chamber - the dark secret of the order. But some did listen... some heard my words. Thus was born the Argent Dawn...", d=30.350, v="scourge-male" },
		{ f="4542-fec833a6", h="fec833a6", t="At last, the curse is lifted. Thank you, hero.", d=4.640, v="scourge-male" },
		{ f="4542-ffec1390", h="ffec1390", t="Aye, the Highlord Mograine: A founder of the original order of the Scarlet Crusade. A knight of unwavering faith and purity; Mograine would be betrayed by his own son and slain by Kel'Thuzad's forces inside Stratholme. It is how I ended up here...", d=19.120, v="scourge-male" },
	},
	[4551] = {
		{ f="4551-d37b59d0", h="d37b59d0", t="How may I be of service?", d=2.240, v="scourge-male-warrior" },
	},
	[4552] = {
		{ f="4552-0c543544", h="0c543544", t="Cooking is a life long pursuit and I see we share the same passion!", d=6.360, v="scourge-female-standard" },
		{ f="4552-3b48d638", h="3b48d638", t="Dirge Quikcleave of Gadgetzan is a master of the culinary arts.  To better yourself you will need to seek him out.", d=11.400, v="scourge-female-standard" },
		{ f="4552-48c1c064", h="48c1c064", t="Wulan in Shadowprey Village can sell you the \"Expert Cookbook\".  You will need that if you are to better yourself.", d=10.280, v="scourge-female-standard" },
		{ f="4552-b48f927f", h="b48f927f", t="I can teach you how to cook!", d=3.080, v="scourge-female-standard" },
	},
	[4556] = {
		{ f="4556-3dfe0528", h="3dfe0528", t="Greetings, and welcome.  I am not very good at smiling, but trust me; I am happy to serve you.", d=11.960, v="scourge-male-standard" },
	},
	[4563] = {
		{ f="4563-031480cd", h="031480cd", t="You know enough to be dangerous, but you still look like you need training to me $N.", d=7.840, v="orc-male-shady" },
		{ f="4563-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=26.990, v="orc-male-shady" },
		{ f="4563-8fca8484", h="8fca8484", t="If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes.", d=19.120, v="orc-male-shady" },
		{ f="4563-d70ae6af", h="d70ae6af", t="Your will is not strong enough to manipulate the forces we control $c.", d=7.200, v="orc-male-shady" },
	},
	[4564] = {
		{ f="4564-031480cd", h="031480cd", t="You know enough to be dangerous, but you still look like you need training to me $n.", d=5.280, v="scourge-male-dark" },
		{ f="4564-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=21.590, v="scourge-male-dark" },
		{ f="4564-7c6cb2cd", h="7c6cb2cd", t="I have no time to waste on the likes of you $c.", d=4.040, v="scourge-male-dark" },
		{ f="4564-8fca8484", h="8fca8484", t="If you desire, in addition to training, I have it within my power to erase the knowledge of your talents from your mind.  Be warned that every time you undergo this procedure the more difficult it is to perform, and therefore the more expensive it becomes.", d=19.160, v="scourge-male-dark" },
		{ f="4564-db7f8bbb", h="db7f8bbb", t="It is wise that you humble yourself before me $N in your desire for more $c knowledge.", d=7.240, v="scourge-male-dark" },
	},
