	[4566] = {
		{ f="4566-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=20.439, v="banshee-female" },
		{ f="4566-4670f054", h="4670f054", t="Greetings.  I'm an undead mage trainer, and you're a mage.", d=5.796, v="banshee-female" },
		{ f="4566-544e5c2b", h="544e5c2b", t="Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.", d=11.143, v="banshee-female" },
		{ f="4566-7d510daf", h="7d510daf", t="Greetings.  I'm an $r $c trainer, and you're a $c.", d=6.449, v="banshee-female" },
	},
