	[4573] = {
		{ f="4573-279d82d3", h="279d82d3", t="Your skill exceeds mine, though  I've heard that Old Man Heming in Booty Bay has copies of \"The Bass and You\".  That is sure to help you increase your skill.", d=11.920, v="scourge-male-standard" },
		{ f="4573-837eac47", h="837eac47", t="You will need to find Nat Pagle in Dustwallow Marsh to get any better than you are currently.", d=7.120, v="scourge-male-standard" },
		{ f="4573-c2467ddc", h="c2467ddc", t="I can teach you fishing skills.", d=3.280, v="scourge-male-standard" },
	},
	[4576] = {
		{ f="4576-4eaf08fa", h="4eaf08fa", t="I will instruct you when the time is right... that time is not now. You have much more to learn first!", d=9.200, v="scourge-male-dark" },
		{ f="4576-9e829bd1", h="9e829bd1", t="You require the instruction of a true master! Go to Daryl Stack in Tarren Mill and embrace your destiny!", d=9.400, v="scourge-male-dark" },
		{ f="4576-9f6a1af5", h="9f6a1af5", t="Cloth is okay. Personally I prefer to work with human skin.", d=7.320, v="scourge-male-dark" },
		{ f="4576-ddcdeb42", h="ddcdeb42", t="Good! I can tell that my efforts will not be wasted!", d=3.560, v="scourge-male-dark" },
	},
	[4578] = {
		{ f="4578-fd111c9e", h="fd111c9e", t="Between the light and the dark, there is shadow... and those shadows have powers you have yet to see.", d=7.920, v="scourge-female-warrior" },
	},
	[4582] = {
		{ f="4582-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=25.430, v="scourge-female-warrior" },
		{ f="4582-0deb5cc3", h="0deb5cc3", t="With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it.", d=10.960, v="scourge-female-warrior" },
		{ f="4582-0e675a71", h="0e675a71", t="I can not train you. You need to talk to your class trainer.", d=4.800, v="scourge-female-warrior" },
		{ f="4582-b0da17d0", h="b0da17d0", t="I got something for you, $n. Looks important.", d=5.920, v="scourge-female-warrior" },
	},
	[4583] = {
		{ f="4583-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.750, v="scourge-male-dark" },
		{ f="4583-0deb5cc3", h="0deb5cc3", t="With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it.", d=8.040, v="scourge-male-dark" },
		{ f="4583-0e675a71", h="0e675a71", t="I can not train you. You need to talk to your class trainer.", d=5.920, v="scourge-male-dark" },
		{ f="4583-88dc2d97", h="88dc2d97", t="Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $n.", d=7.040, v="scourge-male-dark" },
	},
	[4584] = {
		{ f="4584-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.910, v="scourge-male-warrior" },
		{ f="4584-0deb5cc3", h="0deb5cc3", t="With the sanction of Lord Varimathras, the Deathstalkers' numbers grow. More blades to strike at our enemies when they least expect it.", d=9.920, v="scourge-male-warrior" },
		{ f="4584-0e675a71", h="0e675a71", t="I can not train you. You need to talk to your class trainer.", d=4.200, v="scourge-male-warrior" },
		{ f="4584-88dc2d97", h="88dc2d97", t="Messengers from Ravenholdt delivered this letter to me this morning. It is addressed to you, $n.", d=8.240, v="scourge-male-warrior" },
	},
	[4586] = {
		{ f="4586-44242a57", h="44242a57", t="The Dark Lady has said that knowledge will be our greatest weapon in this war.", d=6.240, v="scourge-male-standard" },
		{ f="4586-522afbdc", h="522afbdc", t="Engineering will provide you with the skills and knowledge to dismantle your opponents! Let me show you how...", d=11.520, v="scourge-male-standard" },
		{ f="4586-98e8b89f", h="98e8b89f", t="You are ready for greater things! See Franklin Lloyd, to my right. He will guide you from now on.", d=8.680, v="scourge-male-standard" },
	},
	[4588] = {
		{ f="4588-407a9e4e", h="407a9e4e", t="Before my death, I was a librarian; I had nothing to do with wars and plagues. I never asked to become this. On the other hand, now that my mind is my own again, I'm not about to surrender without a fight.", d=17.920, v="scourge-male-dark" },
		{ f="4588-4d29b093", h="4d29b093", t="I first set up shop in the Magic Quarter, but it was pretty noisy there. This is a definite improvement, barring a few persistent students who still track me down, despite the fact that I've relocated.", d=12.560, v="scourge-male-dark" },
	},
	[4591] = {
		{ f="4591-34baaaf3", h="34baaaf3", t="Only the renowned Doctor Gregory Victor can improve your skill now.  He can be found in Arathi Highlands at Hammerfall.", d=11.480, v="scourge-female-standard" },
		{ f="4591-43457c57", h="43457c57", t="Balai Lok'Wein of Brackenwall Village in Dustwallow Marsh sells a manual that you will need to study in order to improve your skills!", d=9.640, v="scourge-female-standard" },
		{ f="4591-a28d29e1", h="a28d29e1", t="I can train you in First Aid techniques.", d=3.520, v="scourge-female-standard" },
	},
	[4593] = {
		{ f="4593-08830bac", h="08830bac", t="Through rigorous retraining I have had to break many students of all they had previously learned so that I might teach them anew.  The service I offer becomes increasingly difficult to perform each time it is done.  It is for that reason that it becomes increasingly expensive with each retraining.  Do you desire that I break you of the talents you have learned?", d=23.990, v="scourge-male-warrior" },
		{ f="4593-a3cf0f26", h="a3cf0f26", t="The warrior's role is one of protection.  Just as we protect our compatriots in battle, we must also protect the interests of the Forsaken.", d=9.840, v="scourge-male-warrior" },
		{ f="4593-aa3ace82", h="aa3ace82", t="Do not waste my time, $c.", d=4.360, v="scourge-male-warrior" },
		{ f="4593-ed01dd60", h="ed01dd60", t="The warrior's role is one of protection.  Just as we protect our compatriots in battle, we must also protect the interests of the Forsaken.", d=9.920, v="scourge-male-warrior" },
	},
