	[13444] = {
		{ f="13444-42ca94d5", h="42ca94d5", t="No... you can't sit on my lap.", d=2.600, v="dwarf-male-standard" },
		{ f="13444-678c46d3", h="678c46d3", t="A wondrous Winter's Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum.", d=10.480, v="dwarf-male-standard", g=true },
		{ f="13444-69198d42", h="69198d42", t="I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it.", d=10.920, v="dwarf-male-standard" },
		{ f="13444-d9f431fb", h="d9f431fb", t="Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter's Veil.$B$BHo ho hurry up.", d=7.600, v="dwarf-male-standard" },
	},
	[13445] = {
		{ f="13445-42ca94d5", h="42ca94d5", t="No... you can't sit on my lap.", d=3.021, v="orc-male-standard" },
		{ f="13445-678c46d3", h="678c46d3", t="A wondrous Winter's Veil to you... uh... little $G boy : girl;.  Good children get special, um, discounts at any local Smokywood Pastures vendor.  Yum.", d=11.566, v="orc-male-standard", g=true },
		{ f="13445-69198d42", h="69198d42", t="I have a pretty good idea what ol' Greatfather Winter's gonna be doing when this shift is over.  I got a bottle of Winter Veil cheer right here in my bag, and I intend to get to the bottom of it.", d=11.425, v="orc-male-standard" },
		{ f="13445-d9f431fb", h="d9f431fb", t="Yeah, sure, go ahead and tell ol' Greatfather Winter what you'd like for this Winter's Veil.$B$BHo ho hurry up.", d=9.209, v="orc-male-standard" },
	},
	[13447] = {
		{ f="13447-97a20e64", h="97a20e64", t="$n, it's good to see veterans like you in the field!  I'm sorry to report that our supplies are currently too low to launch any large ground assaults against the Horde.$B$BSpeak with our quartermaster; he has supply missions available.", d=12.840, v="dwarf-male-grim" },
	},
	[13616] = {
		{ f="13616-9c5052c2", h="9c5052c2", t="Well done, soldier. A few more and our stables will be overflowing with mounts for the cavalry to ride into combat!", d=9.576, v="troll-female-laidback" },
		{ f="13616-bf93f376", h="bf93f376", t="Greetings, soldier. Are you here to help the cause?", d=4.283, v="troll-female-laidback" },
	},
	[13617] = {
		{ f="13617-06ee8cc1", h="06ee8cc1", t="Just a few more and our stables will be overflowing with mounts. Release it into my custody, soldier. I'll take it from here.", d=9.137, v="dwarf-female-guard" },
		{ f="13617-40ca7ea1", h="40ca7ea1", t="The indigenous rams of Alterac are vital to the functionality of our cavalry!", d=5.777, v="dwarf-female-guard" },
	},
	[13697] = {
		{ f="13697-3eac9b72", h="3eac9b72", t="This place... it's cursed.$B$BI barely managed to escape, and I cannot bear to go down through the tunnels again.$B$BMy brother, and sisters though... They were not as fortunate. Trapped inside, they are feverish with the corrupted haze that flows from the evil garden growing there.$B$BPlease, you must help.", d=22.840, v="dryad-female" },
	},
	[13698] = {
		{ f="13698-d4317e51", h="d4317e51", t="May Cenarius guide you, $c.$B$BI am here in this corrupt land with my sisters on a mission of great importance to the Cenarian Circle. But only those who are powerful enough I ask speak to me about such matters--to send a lesser being would be folly.", d=16.600, v="keeperofthegrove-male" },
	},
	[13699] = {
		{ f="13699-f350269b", h="f350269b", t="My sisters and I have come down from the Stonetalon Mountains to put to rest a tragedy from ages past. Unfortunately, we are not powerful enough to accomplish our goals on our own and now seek mortals such as yourself to aid us.$B$BIf you are powerful enough, then we have much to discuss, $c. If you are not, then, for your safety, I will leave the details of my mission out of our conversation.", d=30.270, v="dryad-female" },
	},
	[13716] = {
		{ f="13716-15dbc2c6", h="15dbc2c6", t="As the toxins lurking within Maraudon seeped into my mind, I began to lose my grip on reality. Worried that it would be used for evil, my dryad sisters secretly took the scepter from me, breaking it into two parts and hiding it within the caverns.$B$BSoon they fell victim to the madness as well, and the two parts of the scepter, left unguarded, came to be in the possession of Vyletongue, himself. The satyr entrusted one part to Noxxion, an evil elemental, and the other he still has to this day.", d=32.150, v="keeperofthegrove-male" },
		{ f="13716-27c1373a", h="27c1373a", t="Thank you for what you have done, $n.$B$BKeep the scepter safe; may it aid you in your toil against the evils that have invaded this place...", d=9.280, v="keeperofthegrove-male" },
		{ f="13716-5714f072", h="5714f072", t="Without knowledge of the incantations required to unite the two parts, Lord Vyletongue was unable to use the scepter. However, now that I am free of the curse of Vyletongue's corruption, I will be able to assist you, if you'd like to bring me the two parts -- both the head and the rod of the scepter.", d=19.270, v="keeperofthegrove-male" },
		{ f="13716-6de5c753", h="6de5c753", t="You ask of the Sons of Cenarius, Remulos and Zaetar.$B$BMy father, Remulos, was strong and beautiful, and my uncle, Zaetar, very cunning and slight of build. While they were respected quite equally, Zaetar always felt as if he could never quite compare to the glory and attention he thought Remulos had.$B$BAfter my sisters and I were born, Zaetar, blinded by jealousy, set out to outdo his brother... He was the creator of his own end. The sadness it brings me has never lessened, even as time passes...", d=33.310, v="keeperofthegrove-male" },
		{ f="13716-7247491c", h="7247491c", t="Between the orange and the purple passageways near the doors to Maraudon, you will find a third path.$B$BThe scepter you hold in your hands is the key.", d=9.280, v="keeperofthegrove-male" },
		{ f="13716-7724f444", h="7724f444", t="Between the colors, a path.$B$BBlink across in light.$B$BFrom the water, you emerge.", d=6.360, v="keeperofthegrove-male" },
		{ f="13716-779222be", h="779222be", t="My scepter... After so many years... You have recovered it! You shall truly be the savior of this place...$B$BPlease listen to me carefully, $n. The head and the rod of the scepter may only be reunited into one at the Stone of Maraudon.", d=18.080, v="keeperofthegrove-male" },
		{ f="13716-91bf67f8", h="91bf67f8", t="Long ago, my dryad sisters and I entered these caves to free the tortured spirit of my uncle, Zaetar. However, the corruption that had already spread through these caverns soon overcame us, and we too fell.$B$BWe were destined to wander these passages; the toxins poisoning our minds...$B$BAlthough my spirit may now be at rest, I know that I have failed in my mission. It is a great sadness I must bear...", d=27.470, v="keeperofthegrove-male" },
		{ f="13716-b1025889", h="b1025889", t="Ah, Zaetar... <Celebras looks away.>$B$BMy father, Remulos, tried to stop him...$B$BZaetar was headstrong, and when he fell for an earthen elemental princess, my father knew that their union was cursed, but Zaetar refused to listen.$B$BThe centaur are the result of his mistake. They were born misshapen and hateful; my uncle Zaetar was killed by his own kin...$B$BThe evil princess, Theradras, still guards his remains here in the crystal caverns.", d=31.550, v="keeperofthegrove-male", P={ { d=1.600 }, { d=1.800, n=true }, { d=26.750 } }, nP={ [1]={ [2]=1.960 } } },
		{ f="13716-bbb2feb2", h="bbb2feb2", t="At last, I am free of the corruption that once bound me to this place...", d=4.760, v="keeperofthegrove-male" },
		{ f="13716-e94a54d4", h="e94a54d4", t="I grow weary...$B$BFrom here, you can see the waterfalls, $n...The scepter grants you the power to travel to this very place, should you ever desire to enter through the front gates of Maraudon again.$B$BNear the entrance to Maraudon, you will find a passage that goes down beneath the caverns. Use the scepter at the ancient ritual site to create a portal, and you will find yourself here once more.", d=26.070, v="keeperofthegrove-male" },
		{ f="13716-f03423dc", h="f03423dc", t="How has this come to be, $n? Do you think that an item such as the Scepter of Celebras is trivial?$B$BI can help you this time, but do not be careless with this valuable item again...", d=13.080, v="keeperofthegrove-male" },
	},
	[13717] = {
		{ f="13717-7f891721", h="7f891721", t="I need no home to know I still have a place in this world, $c. The tribes will see... all of them. They fight amongst one another, and for what? Scraps left over by vultures... lands infested by the Legion... bah!$B$BThe centaur should be proud of their heritage--it is just as noble as any Night elf's or orc's--it is time we started acting like it!", d=23.852, v="human-male" },
	},
	[13776] = {
		{ f="13776-7a6a9245", h="7a6a9245", t="Come to learn, eh? Well I just might have some work for you, scrub.", d=3.531, v="orc-female-warrior" },
	},
	[13777] = {
		{ f="13777-995f8ccd", h="995f8ccd", t="<Sergeant Stormpike salutes.>$B$BName, rank, and serial number, soldier! That's the only bit of information you'll ever give those dirty Frostwolf dogs!", d=7.240, v="dwarf-male-grim", P={ { d=2.000, n=true }, { d=6.520 } }, nP={ [1]={ [1]=2.360 } } },
	},
	[13840] = {
		{ f="13840-2036caea", h="2036caea", t="I am in charge of recruitment for the Frostwolf Clan. As a soldier of Frostwolf, it is your responsibility to check in with me as your rank among the clan rises.$B$BHonor and respect are earned on this frigid field.", d=17.200, v="orc-male-guard" },
	},
	[13841] = {
		{ f="13841-b6d8202b", h="b6d8202b", t="Hail, $r! I am Lieutenant Haggerdin, officer in charge of recruitment for the Stormpike Guard.$B$BAs you gain prestige and notoriety among the Stormpike, return to me and I shall see about upgrading your insignia. Also, should you ever lose your insignia, I am able to supply a replacement.", d=21.240, v="dwarf-male-guard" },
	},
	[14241] = {
		{ f="14241-4faf9d1f", h="4faf9d1f", t="Thank you, mortal. There is but one service that I may offer to you before I return to the Dream.$B$BThe door to Zevrim's master, Alzzin, blocks your path. I shall act as your instrument of destruction. The door will be opened, I merely await your command.", d=15.560, v="narrator", n={ [1]=16.120 } },
		{ f="14241-d482a3a3", h="d482a3a3", t="Helpless... powerless... restore... must restore... Zevrim controls... end this torment...", d=8.000, v="narrator", n={ [1]=8.760 } },
	},
	[14305] = {
		{ f="14305-2529810b", h="2529810b", t="Do fish ever get thirsty?", d=2.240, v="humanmalekid-male" },
		{ f="14305-31092bb9", h="31092bb9", t="If you try to fail and succeed, what did you just do?", d=4.520, v="humanmalekid-male" },
		{ f="14305-33e38023", h="33e38023", t="Mushrooms always grow in damp places and so they look like umbrellas.", d=5.240, v="humanmalekid-male" },
		{ f="14305-37fd876f", h="37fd876f", t="When I grow up, I wanna be the king of Stormwind!", d=3.760, v="humanmalekid-male" },
		{ f="14305-4a710eec", h="4a710eec", t="If overalls are held up by the snaps at the top, then why do they have belt loops?", d=5.000, v="humanmalekid-male" },
		{ f="14305-5e0c3db9", h="5e0c3db9", t="I've been to Ironforge before.  It smells funny there.", d=3.880, v="humanmalekid-male" },
		{ f="14305-8e2b3239", h="8e2b3239", t="What happens if your snot freezes in your nose?", d=3.840, v="humanmalekid-male" },
		{ f="14305-ff810e5d", h="ff810e5d", t="Did you just come out of a dungeon?  Did you get me anything?", d=4.040, v="humanmalekid-male" },
	},
	[14321] = {
		{ f="14321-b18ebdf1", h="b18ebdf1", t="You da man now, dog!", d=2.480, v="ogre-male" },
		{ f="14321-d2365bb4", h="d2365bb4", t="Fengus make you fierce!  Crazed!  RAR!", d=4.920, v="ogre-male" },
	},
	[14322] = {
		{ f="14322-0712ff17", h="0712ff17", t="You da boss now, yeah?  Long live da new king!$B$BKreeg let you look at Gordok hooch.  Ogre hooch best of all hooch, and Gordok hooch best of all ogre hooch!  Maybe you buy some from me, ya boss?!", d=17.920, v="ogre-male" },
	},
	[14323] = {
		{ f="14323-59d69199", h="59d69199", t="I show you how smart I am, boss!  You be extra smart with mighty magic mojo now!$B$BUm... maybe Slip'kik use magic on self. Dat would be good idea...", d=13.200, v="ogre-male" },
		{ f="14323-7caa4ca1", h="7caa4ca1", t="You got me good boss!  How you get by Slip'kik??  I smart though, I watch next time!  Har har!$B$BNobody get by Slip'kik no more. Slip'kik promise!", d=15.040, v="ogre-male" },
	},
	[14324] = {
		{ f="14324-2d261401", h="2d261401", t="Uh... I sorry I attack you boss.  You no kill me, please OK!?  You da king now, and I help make your tribute better!", d=13.120, v="ogre-male" },
		{ f="14324-f3b83c04", h="f3b83c04", t="If you not talk to Mizzle, you not become da king!  Take to Mizzle da Crafty!", d=7.800, v="ogre-male" },
	},
	[14325] = {
		{ f="14325-18add9b8", h="18add9b8", t="What you doin' wanderin' around here?  Why them small fries not in da shackles?!", d=6.200, v="ogre-male" },
		{ f="14325-9131a94c", h="9131a94c", t="You da strong one now!  All hail to da new king of da Gordok!", d=6.000, v="ogre-male" },
		{ f="14325-c7404e13", h="c7404e13", t="Do I see them with weapons still?  Why you let them keep their weapons?!", d=6.160, v="ogre-male" },
	},
	[14326] = {
		{ f="14326-15c784f3", h="15c784f3", t="I heard you was dead... well, you won't be easy to make dead after this!", d=6.720, v="ogre-male" },
		{ f="14326-e9792304", h="e9792304", t="You are da king of the Gordok!  You're A-number-one!", d=5.720, v="ogre-male" },
	},
	[14347] = {
		{ f="14347-13d56743", h="13d56743", t="In the time before time, what the usurpers would later call the First Age of Creation, my master and his siblings ruled over this world. It was they, the Old Gods, who created all.$B$BAnd it was they who would ultimately be cast down by those that would call themselves Shapers. ", d=18.709, v="human-male-standard" },
		{ f="14347-3a802ed8", h="3a802ed8", t="<Demitrian falls to his knees.>$B$BYou have recovered my Master's eternal prison!$B$BOh long have I waited for this day and finally, it is realized.$B$BHe must be released!", d=10.003, v="human-male-standard", P={ { d=2.640, n=true }, { d=9.579 } }, nP={ [1]={ [1]=3.720 } } },
		{ f="14347-433262ec", h="433262ec", t="<Demitrian laughs.>$B$BYour reward is a quick and painful death, fool!", d=3.253, v="human-male-standard", P={ { d=1.360, n=true }, { d=3.292 } }, nP={ [1]={ [1]=2.400 } } },
		{ f="14347-5fc8d4a8", h="5fc8d4a8", t="It was the Lieutenants of Ragnaros, Geddon and Garr, who would perpetrate the betrayal against my Lord. Thunderaan was caught unaware.", d=10.862, v="human-male-standard" },
		{ f="14347-64c79dd9", h="64c79dd9", t="Their manifest forms weak from eons of battle, imprisoned beneath the world - the world that they themselves created - the corruption of the Titan Shapers would permeate through the surface and befoul the Old Gods.$B$BIt was then and there that the brothers did turn. For five millennia a battle was fought at the core of this world. ", d=23.957, v="human-male-standard" },
		{ f="14347-69890909", h="69890909", t="Look to this ravaged field and know the power that the elements hold, $r.", d=5.172, v="human-male-standard" },
		{ f="14347-a0623a9e", h="a0623a9e", t="The vessel of rebirth must be fortified with elementium. I know of only one source of the mineral: the elemental planes, at the core of our world.$B$BThere is one, an Earthshaper, who may know more than I about the acquisition of such things. You must find this Earthshaper!", d=17.720, v="human-male-standard" },
		{ f="14347-a86a527f", h="a86a527f", t="The Firelord's advances were wholly unknown to Thunderaan. Before my Lord could react, Sulfuras, legendary hammer of Ragnaros, would strike an unmerciful blow. Thunderaan fell, utterly defeated.$B$BThe Firelord feasted upon the essence of my Lord, but was unable to consume him entirely.", d=17.616, v="human-male-standard" },
		{ f="14347-ad1f7b45", h="ad1f7b45", t="The corporeal form of Ragnaros must be destroyed. From the remnants, his essence shall emerge. In this weakened state, Ragnaros' grip on the prison of Thunderaan is loosed. The essence itself acting as a key...", d=16.023, v="human-male-standard" },
		{ f="14347-ae1064d7", h="ae1064d7", t="It was during the Elemental Sundering that the Firelord, Ragnaros, would seek to consume my Lord, Thunderaan, Prince of Air.$B$B<Demitrian bows his head, his face contorted in rage.>$B$BSpeak his name and I shall decorate this ravaged camp with your entrails. Be silent and listen. ", d=15.473, v="human-male-standard", P={ { d=9.515 }, { d=3.840, n=true }, { d=7.303 } }, nP={ [1]={ [2]=4.440 } } },
		{ f="14347-b479afc1", h="b479afc1", t="I hold the vessel of his rebirth. Should you be prepared to take on this task, you will be required to fortify the vessel and ultimately, break the hold of Ragnaros himself!", d=11.545, v="human-male-standard" },
		{ f="14347-cced0424", h="cced0424", t="What little remained of Thunderaan's essence was stored within a talisman of elemental binding. Ragnaros then shattered the talisman in two flawless pieces. The pieces assigned to his Lieutenants... ", d=13.585, v="human-male-standard" },
		{ f="14347-e4b1c6a2", h="e4b1c6a2", t="I know much, listen and be educated, $r.", d=3.730, v="human-male-standard" },
	},
	[14348] = {
		{ f="14348-0ca8b46f", h="0ca8b46f", t="The fissure closed and Krixix was gone! Swallowed whole!$B$BBe warned, $r, what you wish for could very well become that which you do not want. You play with beings and arcana that are older than time itself!$B$BShould Krixix be alive and should he have the information which you seek, you can be certain that he will not give up said information. He has faced terrors far worse than you could ever dream to perpetrate.", d=26.350, v="bloodelf-male" },
		{ f="14348-3e560d2d", h="3e560d2d", t="Elementium? I have not heard that word uttered from the mouth of a mortal in decades.", d=5.560, v="bloodelf-male" },
		{ f="14348-4735a4ad", h="4735a4ad", t="A former student of mine by the name of Krixix spent a lifetime attempting to make contact with the chained Gods of the underworld. He pursued that which would spring up from the ravaged earth... That which would form only as a result of the elements clashing in titanic conflict.$B$BElementium as it would be known to mortals.$B$BOne day, nearly a decade ago, Krixix's pursuit lead to a fissure forming in this very gorge.", d=24.990, v="bloodelf-male" },
		{ f="14348-64228587", h="64228587", t="Aye, he had done what was thought to be impossible. Out from the fissure sprung an agent of Therazane!$B$BFrom my vantage point, I could see the goblin holding conversation with the agent of the Old God. What happened after that was terrible...", d=14.840, v="bloodelf-male" },
		{ f="14348-b3e12c28", h="b3e12c28", t="I study the known and unknown elements of our world.", d=4.040, v="bloodelf-male" },
	},
	[14353] = {
		{ f="14353-0468ced0", h="0468ced0", t="You big boss now!  You king!  All hail King $n, King of Gordok!$B$BNow that you da boss, all henchmen will give you tribute!  You left some alive, yeah boss?", d=16.200, v="ogre-male" },
		{ f="14353-6134d833", h="6134d833", t="All henchmen of da boss - Stomper Kreeg, all three of da Guards, Captain Kromcrush, and da Observer - give tribute to da new boss.  If you kill a henchman, then that henchman can't give tribute!  Each one you keep alive will give you more tribute.  Keep all of them alive and you get da BIG tribute!$B$BYeah!", d=34.350, v="ogre-male" },
		{ f="14353-d77d43cd", h="d77d43cd", t="OK boss, when you ready for da tribue from your henchmen, you let me know!", d=6.240, v="ogre-male" },
		{ f="14353-e987c211", h="e987c211", t="Um, you kill king, yeah?  That means you take his place.  That make you da new boss!  Hail to da king!", d=11.160, v="ogre-male" },
	},
	[14354] = {
		{ f="14354-159882e5", h="159882e5", t="Do you want to play a game, stinky?", d=2.595, v="human-male" },
	},
	[14358] = {
		{ f="14358-23218805", h="23218805", t="Do you know of the Highborne? The Shen'dralar?", d=3.360, v="nightelf-female-priestess" },
		{ f="14358-7566ebc5", h="7566ebc5", t="The Highborne ghosts that you see wandering through the courtyard and halls of Eldre'Thalas were slain, not by invading Gordok ogres or satyrs, but by the Prince himself!", d=14.640, v="nightelf-female-priestess" },
		{ f="14358-854b0b27", h="854b0b27", t="The people were destroyed in order to preserve the Prince's immortal life and near limitless powers. The power once divided among thousands now funnels into the Prince and the Shen'dralar zealots. Those few remaining survivors are directly feeding power into the pylons in order to keep Immol'thar imprisoned.$B$BShould the demon break free of its bonds, it would surely destroy what little is left of this once great bastion of arcana.", d=30.790, v="nightelf-female-priestess" },
		{ f="14358-8955c35d", h="8955c35d", t="Leave this place, stranger, lest it consume you as it has all that it has touched.", d=6.560, v="nightelf-female-priestess" },
		{ f="14358-b9de3815", h="b9de3815", t="The Shen'dralar were Queen Azshara's most revered arcanists. It was within these very walls that the Queen's most important demands were processed - often in secret.$B$BAfter the destruction of the Well and the subsequent lethargy that overcame the Highborne and lesser night elf sects, the Prince of Eldre'Thalas, Tortheldrin, began construction of the pylons that you see littering the halls of the west wing. ", d=31.630, v="nightelf-female-priestess" },
		{ f="14358-dc5ccc81", h="dc5ccc81", t="The Prince plotted to imprison a demon of immense power behind a grand force field. The pylons would channel latent energies into the field, keeping it operational.$B$BWhile imprisoned, Immol'thar would serve as a battery to the populace of Eldre'Thalas.", d=20.720, v="nightelf-female-priestess" },
		{ f="14358-e8c0a387", h="e8c0a387", t="The siphoned energies would sustain the Highborne's magic, allowing those within the walls of Eldre'Thalas to feed their endless and growing magical pangs.$B$BThousands of years passed and the power required to keep Immol'thar imprisoned while sustaining life within Eldre'Thalas, began to shift. The cost to keep Immol'thar bound grew to overshadow the rate at which energy could be siphoned and distributed. The once net gain turned to loss.", d=34.150, v="nightelf-female-priestess" },
	},
	[14368] = {
		{ f="14368-2f69df94", h="2f69df94", t="What you must understand is that being able to index 10,000 years of existence has given me a rather unique perspective on life. Your present day trials and tribulations are meaningless.", d=15.440, v="nightelf-male-official" },
		{ f="14368-aea17c64", h="aea17c64", t="Oh the drama and fuss the young Master exerted. You would think the fate of the world rested squarely on his shoulders. Only mortals could have such a skewed perspective on our world.$B$BAlas, he left me with his meager magical secrets... Librams or some such nonsense. I have no use for these paultry magics but perhaps you might be interested in their enchantments.", d=24.990, v="nightelf-male-official" },
	},
	[14369] = {
		{ f="14369-4e62eb57", h="4e62eb57", t="Keep your voice down, stranger. You do not want to disrupt the Master's meditations.", d=7.313, v="nightelf-male-warrior", s={ ["f"]=6.640 } },
		{ f="14369-63818d0f", h="63818d0f", t="I suspect that the imps are stealing knowledge.", d=3.717, v="nightelf-male-warrior", s={ ["f"]=4.640 } },
		{ f="14369-98b20688", h="98b20688", t="Many have come to this sanctuary, few have left. ", d=4.364, v="nightelf-male-warrior", s={ ["f"]=4.880 } },
		{ f="14369-9e618248", h="9e618248", t="We mustn't anger the Master. His is a wrath that is cruel beyond measure.", d=6.141, v="nightelf-male-warrior", s={ ["f"]=7.120 } },
		{ f="14369-cc5ac26e", h="cc5ac26e", t="Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him.", d=17.212, v="nightelf-male-warrior", s={ ["f"]=13.320 } },
		{ f="14369-d4c65b75", h="d4c65b75", t="The Master holds great interest in the lair of Nefarian. If only someone would defeat the dragon and his minions and retell the tale to the Prince. I bet that would loosen the Prince's lips. The Ashbringer could be found!", d=15.879, v="nightelf-male-warrior", s={ ["f"]=16.240 } },
		{ f="14369-d658f159", h="d658f159", t="The Lorekeeper is an ancient. He has served under our glorious Queen!", d=5.616, v="nightelf-male-warrior", s={ ["f"]=5.880 } },
		{ f="14369-ef6db431", h="ef6db431", t="Books have been disappearing as of late. The Lorekeeper and his assistants are in a frenzy. They suspect foul play within Eldre'Thalas.", d=12.242, v="nightelf-male-warrior", s={ ["f"]=10.520 } },
	},
	[14374] = {
		{ f="14374-1fe3187c", h="1fe3187c", t="Oh the horror! The tragedy! We are on the verge of a breakthrough, yet all could be lost.", d=8.162, v="nightelf-female-standard" },
	},
	[14381] = {
		{ f="14381-7bc7520f", h="7bc7520f", t="10,000 years of recorded knowledge tends to draw the wrong element to the Athenaeum. Books are stolen, recovered and stolen again on a daily basis.", d=12.520, v="nightelf-male-official" },
	},
	[14382] = {
		{ f="14382-17e160b4", h="17e160b4", t="Kildrath tends to overdramatize the situation. For example, \"Garona: A Study on Stealth and Treachery,\" has been stolen over 400 times.$B$BThe mark of the Athenaeum protects the tomes, preventing any unauthorized viewings.", d=16.283, v="nightelf-female-standard" },
	},
	[14383] = {
		{ f="14383-e27ebb12", h="e27ebb12", t="They've been stolen, $r! Three of our most prized volumes. Should you return the tomes, a reward will most certainly be yours.", d=10.960, v="nightelf-male-official" },
	},
	[14387] = {
		{ f="14387-1ad6fb28", h="1ad6fb28", t="The fabric of which our world is woven is most delicate. It merely takes some knowledge and the application of said knowledge to tear the fabric. It is thusly that rifts are born. ", d=10.560, v="bloodelf-male" },
	},
	[14392] = {
		{ f="14392-8413dfd0", h="8413dfd0", t="Gaze upon the enemy, $r. See what the might of the Horde reduces even the most powerful of dragons to! All that oppose us shall meet a similar fate!", d=12.520, v="orc-male-guard" },
		{ f="14392-9edd139f", h="9edd139f", t="I am he that carries out the Warchief's commands without question. I am Horde.", d=7.240, v="orc-male-guard" },
	},
	[14394] = {
		{ f="14394-82e74d27", h="82e74d27", t="I live only to serve our King.", d=3.058, v="human-male-official" },
		{ f="14394-d8b4716e", h="d8b4716e", t="Perhaps one day, your contributions to the Alliance will be as great as the heroes you have seen this day. Honor them, $n.", d=7.972, v="human-male-official" },
	},
	[14436] = {
		{ f="14436-add89143", h="add89143", t="There comes a time when the life we know falls short.  We are trapped and look for answers, and we find hope burning in dark places.$B$BOnly then, $n, do we take our first steps to freedom.", d=12.468, v="human-male-official" },
	},
	[14437] = {
		{ f="14437-eb7c59ff", h="eb7c59ff", t="Do you have any spiders or beetles, $c?  They scurry fast, but if you're faster then you'll find them quite a treat!", d=8.258, v="goblin-male-gruff" },
	},
	[14444] = {
		{ f="14444-18025411", h="18025411", t="What does \"zug zug\" mean?", d=2.440, v="humanmalekid-male" },
		{ f="14444-4d61a1ea", h="4d61a1ea", t="When lightning strikes the ocean why don't all the fish die?", d=5.280, v="humanmalekid-male" },
		{ f="14444-75638ff6", h="75638ff6", t="If your glove is too big, does it still fit like a glove?", d=3.440, v="humanmalekid-male" },
		{ f="14444-d9da2bac", h="d9da2bac", t="If a turtle doesn't have a shell, is he homeless or naked?", d=5.120, v="humanmalekid-male" },
		{ f="14444-dd014d5f", h="dd014d5f", t="If you're a real hero of the Horde, then I wanna see you fight a dragon!  Yeah!", d=6.840, v="humanmalekid-male" },
		{ f="14444-e5e87934", h="e5e87934", t="I have a rock in my nose.", d=2.600, v="humanmalekid-male" },
		{ f="14444-eab7e728", h="eab7e728", t="Your armor looks scary.  Are you scary too?", d=3.920, v="humanmalekid-male" },
		{ f="14444-f930df14", h="f930df14", t="Would a fly without wings be called a walk?", d=3.120, v="humanmalekid-male" },
	},
	[14450] = {
		{ f="14450-d3e1a5a0", h="d3e1a5a0", t="There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.  One week out of the year during the Spring, the Alliance takes time to give something back to these innocents.  This time is called Children's Week.  ", d=27.950, v="human-female-standard" },
	},
	[14451] = {
		{ f="14451-486288d9", h="486288d9", t="There are costs with war, $c... ones often overlooked.  Those costs are the orphans - children who have lost their parents to the far-too-numerous conflicts that rage across Azeroth.  Those children who have no one else to turn to often come here to live until they are old enough to fend for themselves.$B$BOne week out of the year during the Spring, the Horde takes time to give something back to these innocents.  This time is called Children's Week. ", d=35.670, v="orc-female-standard" },
	},
	[14463] = {
		{ f="14463-612d20a4", h="612d20a4", t="You are certainly a long way from home, $r.", d=3.206, v="human-male-official" },
	},
	[14469] = {
		{ f="14469-1cffedd5", h="1cffedd5", t="If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.$B$BMy imp, Impsy, shall set you on your way.", d=19.959, v="gnome-male-zany" },
		{ f="14469-678e2a2b", h="678e2a2b", t="Bow in my presence, insect! Surely you can feel the power I hold over you.", d=3.575, v="gnome-male-zany" },
		{ f="14469-73164ce5", h="73164ce5", t="So you have come to Niby to learn the secrets of calling down an infernal servant from the Nether.$B$BSilence! Niby knows all!$B$BNiby is not so quick to part with such knowledge. First, you must assist Niby with a very important task.", d=11.572, v="gnome-male-zany" },
		{ f="14469-7dfaeaed", h="7dfaeaed", t="Do not interrupt Niby, fool! I shall rend the flesh from your bones and use your skeletal remains as a coat rack. Now where was I? Oh yes, so, Kroshius lasted nearly ten times longer than any ordinary infernal. I am not sure why but I am confident that with enough study, I could find out.$B$BI need you to recover Kroshius' Infernal Core.", d=17.891, v="gnome-male-zany" },
		{ f="14469-f47a9443", h="f47a9443", t="There is a powerful infernal named Kroshius northeast of this camp. It is why Niby is here. Kroshius is a greater infernal - an infernal that has lasted longer than expected. You see, nub, an infernal crashes down into the earth with great intensity to serve its master but this intensity fades fast. Once the blazing flames have died down, the infernal crumbles.", d=18.861, v="gnome-male-zany" },
	},
	[14470] = {
		{ f="14470-637e94b9", h="637e94b9", t="Some call me... Impsy?", d=1.890, v="human-male" },
	},
	[14494] = {
		{ f="14494-14a438f1", h="14a438f1", t="I know you will, $n.$B$BI myself am a priestess, though, unlike you I am long since gone from this world. My spirit, however, remains here, as do the spirits of the thousands who were brutally slain by the mad Prince, Arthas Menethil and his legion of undeath.", d=15.617, v="human-female" },
		{ f="14494-1719742b", h="1719742b", t="You were. The Eye is never wrong.$B$BYou are a $g priest:priestess;, after all. A powerful $g priest:priestess;, if the Eye showed you this horrible memory.$B$BYou have come for redemption, yet you yourself do not even realize this... Do you?", d=12.270, v="human-female", g=true },
		{ f="14494-37e56e23", h="37e56e23", t="Praise the Light, one has finally answered the calling.", d=3.173, v="human-female" },
		{ f="14494-83d3afc9", h="83d3afc9", t="<Eris nods.>$B$BThe Eye has seen so many horrors and so many wonders.$B$BIt displays what it feels the one looking into it is most suited to see.", d=7.870, v="human-female", P={ { d=2.000, n=true }, { d=7.793 } }, nP={ [1]={ [1]=1.920 } } },
		{ f="14494-d741dd34", h="d741dd34", t="You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, $n.", d=20.910, v="human-female" },
		{ f="14494-e53e856e", h="e53e856e", t="I never stated that you were here to redeem yourself, $g priest:priestess;. You are here to redeem me and the innocents murdered while trying to escape Stratholme.$B$BMy spirit and the spirit of those lost are bound here, cursed to endlessly relive our own tragic deaths.", d=14.668, v="human-female", g=true },
	},
	[14504] = {
		{ f="14504-0aa37b03", h="0aa37b03", t="The spirit of the Dreadsteed pulses with rage.", d=3.520, v="narrator", n={ [1]=3.320 } },
	},
	[14508] = {
		{ f="14508-280d99cc", h="280d99cc", t="Arr!   There be nothin I like to see better than folks fightin to the death in the arena.   If you be here at the right time maybe you can be one of them!", d=10.433, v="goblin-male-gruff" },
	},
	[14522] = {
		{ f="14522-470638ce", h="470638ce", t="The ways of Jaedenar are dark and treacherous.  Watch your moves in this place, $C, or you will find your soul entralled by your rivals...", d=10.689, v="orc-male-standard" },
	},
	[14523] = {
		{ f="14523-10a2234c", h="10a2234c", t="Be gone!  I hold counsel with Dreadlords, and the matters we discuss are not your concern!", d=7.840, v="orc-male-shady" },
		{ f="14523-2370a580", h="2370a580", t="... A message from Banehollow?  What message is that?  Does he have need of his great advisor and servant, Ulathek?  Does he require my presence?", d=13.880, v="orc-male-shady" },
		{ f="14523-ebb245f4", h="ebb245f4", t="What?  But how?  No!  This is not possible!  I have been so careful... he could not know!$B$BYou lie!  You lie, and now you'll die for your deceit!", d=12.320, v="orc-male-shady" },
	},
	[14524] = {
		{ f="14524-58405dcd", h="58405dcd", t="Greetings, $n.", d=1.840, v="narrator", n={ [1]=1.960 } },
	},
	[14528] = {
		{ f="14528-91126dba", h="91126dba", t="*GRRRR* *RUFF* *RUFF*", d=5.320, v="narrator", n={ [1]=5.200 } },
	},
	[14531] = {
		{ f="14531-f10de02f", h="f10de02f", t="How wonderful to see another person in this remote region of the world. Come, walk with me. Let our bodies keep each other warm.", d=11.840, v="tauren-male-elder" },
	},
	[14536] = {
		{ f="14536-4c87ecfd", h="4c87ecfd", t="I come to Silithus every year around this time. The weather is phenomenal for my bunions.$B$BYou should take a stroll with me, friend. Enjoy the sights and what not.", d=6.763, v="gnome-male-young" },
	},
	[14542] = {
		{ f="14542-525ec464", h="525ec464", t="<Nearing this kodo it swivels its powerful neck to regard you, staring you down with keen eyes from under its helmet. It would seem the passage of time has done little to temper its brave and challenging nature.      Long thick scars run the length of its hide, and horn. It is clear in your time apart it has become victorious in every battle it has entered against both friend and foe.     As it sizes you up, it relaxes when you don't back down. It seems impressed by your bravery and foes and feats you have overcome in your long journey. It would be proud to bear you as its companion and rider.>", d=41.260, v="narrator", n={ [1]=44.860 } },
	},
	[14549] = {
		{ f="14549-d4de9b28", h="d4de9b28", t="<Upon walking up to this kodo it stands tall and proud next to its kin. Its strong legs cause the earth to shake slightly as it stamps them into the ground. The kodo grunts happily when you near.     It would seem this once timid kodo has found its confidence and is proud of both its strength and fearlessness.      It is clear your presence here excites it, and it would be proud to bear you into the grand world as its rider and companion.>", d=29.230, v="narrator", n={ [1]=30.430 } },
	},
	[14550] = {
		{ f="14550-8f3b9bf2", h="8f3b9bf2", t="<As you approach the kodo it looks up from its grass with interest. The heavy armor along its body clearly does not impair its deft movements in the slightest.     It tilts its head watching you, and after a moment recognition seems to cross its face. It lets out a happy low, and nudges its powerful head toward your hands, perhaps looking for affection. Though it has grown stronger and fiercer, perhaps it hasn't changed that much after all.     It is clear this kodo is fond of you and would happily bear you as its rider and companion.>", d=33.550, v="narrator", n={ [1]=35.550 } },
	},
	[14624] = {
		{ f="14624-9815802e", h="9815802e", t="Burninate's the name, smithin's my game... and, erm... I sell a little food and water on the side. Care for some meat?", d=7.040, v="dwarf-male-grim" },
		{ f="14624-c2db5669", h="c2db5669", t="You've done all that I've asked you to do, $n. There's really nothing more here for you. If you are interested in continuing your career as an agent of the Thorium Brotherhood, speak with Lokhtos Darkbargainer at the Grim Guzzler in Blackrock Depths.$B$BFarewell!", d=16.200, v="dwarf-male-grim" },
	},
	[14626] = {
		{ f="14626-88cc1a3a", h="88cc1a3a", t="As acting Taskmaster of this here compound, it is my duty to make sure that there is a certain level of tedium involved with all forms of business, work, rest, and relaxation that may take place here.$B$BIf you find anything that you are asked to do to be too easy and hassle free, report to me immediately.", d=20.230, v="dwarf-male-grim" },
	},
	[14627] = {
		{ f="14627-81bd06d3", h="81bd06d3", t="When Lolo doesn't wanna spill any o' his precious ale or get his lil' dress dirty, I'm called in. Yep. Ol' Hansel is the dwarf they use to mete out a lil' bit o' justice an' a whole lotta pain.", d=11.520, v="dwarf-male-grim" },
	},
	[14628] = {
		{ f="14628-a9361401", h="a9361401", t="We chose to leave the protection and comfort of the Depths to exploit... er, I mean... hrm, yes that's right, EXPLORE the world.", d=10.160, v="npc-14656" },
	},
	[14634] = {
		{ f="14634-f92dfa19", h="f92dfa19", t="Yesh, it'sh true, I'm blind as a bat! An' drunk as a ... err, drunk as shomething that getsh drunk.$B$BI'll tell you what, $r. It'sh the drink that keeps me shenses sharp. It'sh common knowledge that when you lose a shense, yer other shenses become more alert. My drunk shense is incredible these days.", d=18.830, v="dwarf-male-grim" },
	},
	[14637] = {
		{ f="14637-2415eff9", h="2415eff9", t="Maybe this wasn't the best place for a shop after all...", d=4.600, v="goblin-male-guard" },
		{ f="14637-367d583d", h="367d583d", t="Well hello again, $n!  I don't know how much longer I'm going to keep on trying to set up a shop out in the middle of nowhere.  Still, since you've helped me out in the past, I'll show you some stuff you may find interesting!", d=12.320, v="goblin-male-guard" },
	},
	[14720] = {
		{ f="14720-a61382af", h="a61382af", t="I am he that watches they. I am the fist of retribution. That which does quell the recalcitrant. Dare you defy the Warchief? Dare you face my merciless judgement?", d=15.720, v="orc-male-guard" },
		{ f="14720-f123470f", h="f123470f", t="Look to this fallen dragon, $r. The might of the Horde is unquestionable!", d=6.920, v="orc-male-guard" },
	},
	[14721] = {
		{ f="14721-4c717394", h="4c717394", t="The Lord of Blackrock hangs from the arches!", d=3.960, v="human-female-official" },
		{ f="14721-7d7a0d92", h="7d7a0d92", t="Move along, citizen. There is nothing to see here.", d=3.400, v="human-female-official" },
	},
	[14722] = {
		{ f="14722-00e95851", h="00e95851", t="Friend - Stormwind needs your assistance and your generosity!  Our once large stockpile of textiles has run critically low.  Stormwind is now engaged in a multi-pronged effort to rebuild those stocks for the manufacture of textiles and bandages!  Your donation of cloth would help Stormwind immensely, as well as earn the respect of the citizenry!", d=23.738, v="human-male-standard" },
	},
	[14723] = {
		{ f="14723-240f95e3", h="240f95e3", t="Aye, you there!  If you want to earn the respect of the dwarves of Ironforge, then you can start by donating valuable resources!  Ironforge finds itself running low on cloth piece; textiles and bandages don't grow on trees, ya know!  Rather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the dwarven people of Ironforge!", d=25.664, v="dwarf-female-guard" },
	},
	[14724] = {
		{ f="14724-92b80d28", h="92b80d28", t="The exiles of Gnomeregan find ourselves in even more dire straits by running low on cloth reserves!  Perhaps you can help us, eh?!  Bring me extra cloth pieces you might have to help us replenish our stocks.  By donating them, you'll be earning the respect and trust of gnomes everywhere.  That's something that money can't buy!  Well, I guess cloth does, but that's beside the point...", d=16.535, v="gnome-male-zany" },
	},
	[14725] = {
		{ f="14725-372d0086", h="372d0086", t="Hail friend - a moment of your time, if I may...$B$BWe have endured much in our trials and tribulations in establishing Teldrassil.  Were the constant strife of the times not enough, we now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of night elves everywhere in helping us out!", d=29.970, v="nightelf-male-warrior" },
	},
	[14726] = {
		{ f="14726-65d66388", h="65d66388", t="In these trying times, a simple donation of cloth can go a long way to help those less fortunate than ourselves.  Cloth goes a long way to making garments and bandages - both important for the war effort!  If you are interested in donating cloth pieces to the orcs of Orgrimmar, I will gladly accept them and make sure you receive the proper recognition for doing so.  For the Horde!", d=26.829, v="orc-female-warrior" },
	},
	[14727] = {
		{ f="14727-5457bc8c", h="5457bc8c", t="Aye, you there!  If you want to earn the respect of the Darkspear, then you can start by donating valuable resources for those in need!  Textiles and bandages don't grow on trees, ya know.  Rather than cash in various cloth pieces you find adventuring, donate them!  Doing so will earn you the recognition of the Darkspear!", d=24.758, v="troll-female-laidback" },
	},
	[14728] = {
		{ f="14728-614f66b2", h="614f66b2", t="Hail $g brother : sister;... I'd like a moment of your time, if I may.$B$BWe tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!", d=22.528, v="tauren-male-warrior", g=true },
		{ f="14728-9cac81e8", h="9cac81e8", t="Hail brother... I'd like a moment of your time, if I may.  We tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!", d=19.657, v="tauren-male-warrior" },
		{ f="14728-9fb0176c", h="9fb0176c", t="Hail sister... I'd like a moment of your time, if I may.  We tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!", d=21.086, v="tauren-male-warrior" },
	},
	[14729] = {
		{ f="14729-9e055276", h="9e055276", t="You there... it is in your best interest to aid the Forsaken during these dire times.  Listen closely, as I dislike repeating myself.  We currently find ourselves in a dire shortage of cloth.  Bandages and simple textiles are running low, and donations are being accepted to bolster sagging inventories.  While you'll not receive financial compensation - hence what donation means - your aid will not go unnoticed.", d=33.590, v="scourge-male-dark" },
	},
	[14731] = {
		{ f="14731-03ca5480", h="03ca5480", t="Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory.   ", d=36.310, v="ogre-male" },
		{ f="14731-174473b0", h="174473b0", t="Recently, a night elf druid named Naralex discovered a network of underground caverns within the heart of the Barrens. Believing he could use the caverns' springs to restore lushness to the Barrens, the druid began siphoning the energies of the fabled Emerald Dream. His vision somehow became a nightmare, however, and soon the Wailing Caverns changed into a den of vicious, deadly predators. It is said that Naralex still resides somewhere inside the labyrinth, trapped beyond the edges of the Emerald Dream.  ", d=46.030, v="ogre-male" },
		{ f="14731-17e9d243", h="17e9d243", t="Uldaman is an ancient Titan vault that has laid buried within the earth since the world's creation. Dwarven excavations of the city have recently released the Titans' first failed creations: the troggs. Legends say that when the Titans deemed the trogg experiment a failure they tried again, resulting in the creation of the dwarven race. These secrets are recorded on the fabled Discs of Norgannon - massive artifacts that lie at the bottom of the ancient city, protected by giant constructs of living stone.  ", d=39.140, v="ogre-male" },
		{ f="14731-19490f29", h="19490f29", t="Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. ", d=38.950, v="ogre-male" },
		{ f="14731-19cbe7de", h="19cbe7de", t="When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande.", d=20.880, v="ogre-male" },
		{ f="14731-1a6e2552", h="1a6e2552", t="This sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called Sul'thraze the Lasher, a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls. ", d=35.030, v="ogre-male" },
		{ f="14731-22aa3fe4", h="22aa3fe4", t="Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road.", d=7.760, v="ogre-male" },
		{ f="14731-2e88eda5", h="2e88eda5", t="Frustrated by the Dalaran wizards' lack of progress against the undead during the Third War, the Archmage Arugal elected to summon the extra-dimensional worgen to bolster his side's diminishing ranks. The wolf-men slaughtered the Scourge, then quickly turned on the wizards themselves and laid siege to the keep of the noble, Baron Silverlaine. The fort quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'.  ", d=36.660, v="ogre-male" },
		{ f="14731-3141b27b", h="3141b27b", t="Crafted from the same vines as Razorfen Kraul, Razorfen Downs is the traditional capital city of the quilboar race. The sprawling, thorn-ridden labyrinth houses a veritable army of loyal quilboar as well as their high priests - the Death's Head tribe. Recently, however, a looming shadow has fallen over the crude den. Agents of the undead Scourge - led by the lich, Amnennar the Coldbringer - have taken control over the quilboar race and turned the maze of thorns into a bastion of undead might.   ", d=37.630, v="ogre-male" },
		{ f="14731-330cd2db", h="330cd2db", t="The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself.  ", d=35.630, v="ogre-male" },
		{ f="14731-33439fd8", h="33439fd8", t="Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons. ", d=61.070, v="ogre-male" },
		{ f="14731-342c02c0", h="342c02c0", t="The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free.  ", d=31.390, v="ogre-male" },
		{ f="14731-4a0923b3", h="4a0923b3", t="Are you interested in exploring one of these dungeons?", d=5.160, v="ogre-male" },
		{ f="14731-4a6950fb", h="4a6950fb", t="The ruins of Dire Maul stand in central Ferelas.", d=5.240, v="ogre-male" },
		{ f="14731-4f48ef1f", h="4f48ef1f", t="Situated along the Zoram Strand of Ashenvale, Blackfathom Deeps was once a glorious temple dedicated to the night elves' moon-goddess Elune. However, the great Sundering shattered the temple - sinking it beneath the waves of the Veiled Sea. There it remained untouched - until, drawn by its ancient power - the naga and satyr emerged to plumb its secrets. Legends hold that the ancient beast, Aku'mai, has taken up residence within the temple's ruins.  ", d=39.190, v="ogre-male" },
		{ f="14731-581034a1", h="581034a1", t="The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain. ", d=36.950, v="ogre-male" },
		{ f="14731-5dc31760", h="5dc31760", t="During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose. ", d=63.470, v="ogre-male" },
		{ f="14731-5eccd4fa", h="5eccd4fa", t="The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows.", d=7.920, v="ogre-male" },
		{ f="14731-5ff7a251", h="5ff7a251", t="Scarlet Monastery lies in the hills northeast of Tirisfal Glades.", d=6.320, v="ogre-male" },
		{ f="14731-66f64f6e", h="66f64f6e", t="Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road.", d=7.480, v="ogre-male" },
		{ f="14731-69040db4", h="69040db4", t="Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they'll give you a gift of friendship.", d=20.760, v="ogre-male" },
		{ f="14731-6a089d41", h="6a089d41", t="The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood.", d=8.040, v="ogre-male" },
		{ f="14731-70185dce", h="70185dce", t="Uldaman can be found at the very northern end of the Badlands.", d=5.040, v="ogre-male" },
		{ f="14731-7b1bcef4", h="7b1bcef4", t="The Deadmines can be found beneath Moonbrook in the south of Westfall.", d=6.480, v="ogre-male" },
		{ f="14731-7de88db1", h="7de88db1", t="Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city.  ", d=37.550, v="ogre-male" },
		{ f="14731-864c5566", h="864c5566", t="The Wailing Caverns has its entrance at the Lushwater Oasis southwest of Crossroads in the Barrens.   ", d=7.600, v="ogre-male" },
		{ f="14731-9507b89f", h="9507b89f", t="Lard keep peace here. Lard also sell fish. Want fish?", d=7.920, v="ogre-male" },
		{ f="14731-95351c86", h="95351c86", t="Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the plague of undeath. Arthas' surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge - led by the powerful lich, Kel'Thuzad, and a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. The two sides are locked in constant, violent combat.  ", d=42.310, v="ogre-male" },
		{ f="14731-a9df0aa1", h="a9df0aa1", t="Blackfathom Deeps can be found at the north end of Zoram Strand along the coast of Ashenvale.", d=8.680, v="ogre-male" },
		{ f="14731-ab572ddf", h="ab572ddf", t="The monastery was once a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.  ", d=32.270, v="ogre-male" },
		{ f="14731-ad5ec0ca", h="ad5ec0ca", t="No, I'm not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!", d=12.400, v="ogre-male" },
		{ f="14731-adc7501c", h="adc7501c", t="The School for Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands.", d=9.920, v="ogre-male" },
		{ f="14731-b69e98a5", h="b69e98a5", t="If you put on cologne or perfume, then you'll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne.", d=23.960, v="ogre-male" },
		{ f="14731-b852ea17", h="b852ea17", t="Ragefire Chasm consists of a network of volcanic caverns below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief Thrall is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council.  ", d=35.590, v="ogre-male" },
		{ f="14731-b8eefffb", h="b8eefffb", t="Shadowfang Keep is in southern Silverpine just north of Pyrewood Village.", d=6.600, v="ogre-male" },
		{ f="14731-b8ef9c65", h="b8ef9c65", t="The Stormwind Stockades are found near the mage quarter in Stormwind.", d=6.360, v="ogre-male" },
		{ f="14731-c2bfa0cf", h="c2bfa0cf", t="Gnomeregan can be found in western Dun Morogh.", d=4.640, v="ogre-male" },
		{ f="14731-ca5fde90", h="ca5fde90", t="Maraudon is located in the middle of the western coast of Desolace, in the Valley of Spears.", d=6.800, v="ogre-male" },
		{ f="14731-d352a290", h="d352a290", t="Once the greatest gold production center in the human lands, the Dead Mines are now inhabited by the Defias Brotherhood, who have turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook. ", d=29.310, v="ogre-male" },
		{ f="14731-e99614f5", h="e99614f5", t="The ruins of Zul'Farrak are located in the northwestern corner of the Tanaris Desert.", d=7.400, v="ogre-male" },
		{ f="14731-f106f818", h="f106f818", t="Built twelve thousand years ago by a covert sect of night elf sorcerers, the ancient city of Eldre'Thalas was used to protect Queen Azshara's most prized arcane secrets. Though it was ravaged by the Great Sundering of the world, much of the wondrous city still stands as the imposing Dire Maul. The ruins' three distinct districts have been overrun by all manner of creatures - especially the spectral highborne, foul satyr and brutish ogres.  ", d=36.110, v="ogre-male" },
		{ f="14731-f2218c4a", h="f2218c4a", t="Blackrock Mountain lies between Searing Gorge in the north and Burning Steppes in the south.", d=7.440, v="ogre-male" },
		{ f="14731-f88f28f5", h="f88f28f5", t="Ragefire Chasm can be found beneath the Shadow Cleft in the center of Orgrimmar.", d=7.520, v="ogre-male" },
		{ f="14731-f9fa0d11", h="f9fa0d11", t="When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall.", d=21.960, v="ogre-male" },
	},
	[14733] = {
		{ f="14733-562d4090", h="562d4090", t="The battle for Warsong Gulch is a battle that we cannot lose.  We fight for our honor and we fight for our land, and no orc or misguided ally will take them from us!", d=12.960, v="nightelf-female-priestess" },
	},
	[14736] = {
		{ f="14736-135596ad", h="135596ad", t="Welcome to Revantusk Village, stranger. I am Primal Torntusk, leader of the Revantusk trolls.", d=11.120, v="troll-female-standard" },
	},
	[14737] = {
		{ f="14737-d2afe6e4", h="d2afe6e4", t="If it's broke, Slagtree can fix it!", d=2.600, v="orc-male-shady" },
	},
	[14738] = {
		{ f="14738-2730e819", h="2730e819", t="I've got all the cooking supplies you'll ever need, mon!", d=3.640, v="troll-male-shaman" },
	},
	[14739] = {
		{ f="14739-2fc3d96b", h="2fc3d96b", t="Mystical goods and commodities is my business, stranger.", d=4.480, v="npc-14771" },
	},
	[14740] = {
		{ f="14740-c3c47346", h="c3c47346", t="Fishing is just so pleasant, mon. You know? I owe my state of bliss to my mentor, the greatest angler in the whole world - Nat Pagle. Have you heard of him, mon?$B$BIf you be looking for enlightenment, Nat Pagle be the one who gonna show you the way. ", d=21.120, v="troll-male-dark" },
	},
	[14741] = {
		{ f="14741-5baf5b9d", h="5baf5b9d", t="Zul'jin shall return one day, $r. Mark my words. Until then, we all hold our positions and do what we can to keep the forest troll population intact.$B$BWith that said, as master huntsman of Revantusk Village, it is my responsibility to insure that the world around us is safe for habitation.$B$BThe beasts of this area must be kept in check.$B$BAre you looking for work? ", d=24.270, v="troll-male-shaman" },
	},
	[14742] = {
		{ f="14742-39230d1f", h="39230d1f", t="I have just completed a new dimensional imploder that will make me rich beyond my wildest goblin dreams!   All I need to do is get a skilled Goblin Engineer to build a dimensional ripper that connects to it and try it!  ", d=13.069, v="goblin-male-zany" },
		{ f="14742-4f8f8e90", h="4f8f8e90", t="It's good to see an engineer brave enough to make the device.   We goblin engineers laugh at danger!", d=5.884, v="goblin-male-zany" },
		{ f="14742-8985e246", h="8985e246", t="The theory behind it is that we completely destroy you with a massive explosion wherever you are and send those particles through a dimensional rip and then re-implode you at the machine here.   Instant Transport!    It might not work ALL the time, but what kind of goblin engineer are you!   If survival was your first priority you could never be a real Goblin Engineer! Here is the recipe you will need to make the Dimensional Ripper and try it out!  ", d=26.264, v="goblin-male-zany" },
	},
	[14743] = {
		{ f="14743-6576fe10", h="6576fe10", t="If you figure out any way to improve the device let me know!", d=3.065, v="gnome-male-young" },
		{ f="14743-d6c927df", h="d6c927df", t="With some of the technology that was recovered by bold gnomes venturing into Gnomeregan, I have managed to construct my greatest invention:  The Matter Transporter!    All I need now is a skilled Gnomish Engineer to build a powerful beacon attuned to the transporter.", d=11.934, v="gnome-male-young" },
		{ f="14743-edb937f1", h="edb937f1", t="Once you have built the device, you simply activate the device to be whisked away to lovely Gadgetzan!    Nearly everyone who has used the device has arrived on the pad here looking just the way they did when they began!  There have been some reported problems with transportees being replaced by their evil selves from an alternate universe, but I'm sure we will have that worked out soon...", d=16.554, v="gnome-male-young" },
	},
	[14753] = {
		{ f="14753-19172c31", h="19172c31", t="May the blessings of the night be yours, friend!  I am Illiyana Moonblaze, and I am the main supplier for the Silverwing Sentinels here in Ashenvale.  As you improve your standing with the Sentinels, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services.", d=26.818, v="nightelf-female-standard" },
	},
	[14754] = {
		{ f="14754-17e0e2bb", h="17e0e2bb", t="Zug zug, my friend!  I am Kelm Hargunth, the main supplier for the Warsong Outriders.  As you improve your standing with the Outriders, I will make available to you a fine selection of goods that you can use inside Warsong Gulch.  Should you find yourself in need of item repair, I also provide those services.", d=26.670, v="orc-male-shady" },
	},
	[14757] = {
		{ f="14757-bb93dc5e", h="bb93dc5e", t="Get the key and unlock these chains! Hitah'ya the Keeper holds it... back of cave... ", d=6.560, v="troll-male-shaman" },
	},
	[14781] = {
		{ f="14781-ae99f5b7", h="ae99f5b7", t="It is no easy task to protect the Horde's lumber gathering efforts here in Ashenvale, but we have never shied from battle!  The night elves and their allies will fall!", d=13.200, v="orc-male-shady" },
	},
	[14822] = {
		{ f="14822-022d92ce", h="022d92ce", t="Your next choice awaits.$B$BYour brother seeks to join the ranks of the prestigious military order you are already a part of.  While you are sure of his commitment and loyalty, his talent and ability to perform the arduous tasks of the order is what you question.  While you are not certain he will be able to rise to the challenge of the order - putting you and others in danger - you are certain that your word alone would allow him in or keep him out.$B$BMake your choice.  ", d=34.847, v="troll-female-old" },
		{ f="14822-2f6d3122", h="2f6d3122", t="Alas... I am sorry to say I cannot currently give you your fortune, as you have recently received a fortune reading from me.$B$BReturn to me several hours from when you first received your fortune.  The forces of Fate will have properly recalibrated themselves, and I will be able to see into your future.", d=22.398, v="troll-female-old" },
		{ f="14822-3540ad53", h="3540ad53", t="Your next choice awaits.$B$BYou are on a diplomatic mission for your liege to a cruel country that is currently at war with yours.  The war has been costly on both sides.  Your mission is to secure a peace that is honorable to both peoples.$B$BAt a diplomatic dinner, you overhear the ruler of the opposing land viciously insult your benevolent liege.  You are fairly certain the ruler meant to say it out of your earshot, but nonetheless he has besmirched your liege's honor.$B$BMake your choice.   ", d=40.480, v="troll-female-old" },
		{ f="14822-4a58d916", h="4a58d916", t="Your next choice awaits.$B$BYou alone have defeated a terrible beast that has been ravaging the countryside, taking its ear as a trophy.  You later learn that your liege had offered a reward for the beast's death, and that a kind but destitute knight who you know is trying to support a family by meager means claims the beast's kill as his own.  You have no real need for money yourself, but you know that the destitute knight is lying for his own personal gain.$B$BMake your choice.  ", d=40.918, v="troll-female-old" },
		{ f="14822-5d30679d", h="5d30679d", t="Very well then...$B$BYou have been tasked by your liege to guard his fields of corn from poachers and thieves.  One night on patrol, you stumble across a haggard man in thread-bare clothing stealing corn from the field.  You quickly confront him, and he immediately begs for his life.  He claims he is stealing the corn to feed his family since the lord of the land - your liege - demands too much in taxes.  Your liege is indeed known for his harsh taxes throughout the land.$B$BMake your choice. ", d=39.990, v="troll-female-old" },
		{ f="14822-6088b326", h="6088b326", t="Your fortune is cast, $c.  For the next few hours, you will find your spirit in tune with your true nature.  Be careful, as your fortune - and your fate - are never as clear as you might think them to be.$B$BIf you would like a small glimpse of something to ponder in your future, by all means let me know.  I'd be happy to give you a written fortune, provided you have room in your inventory.  It is one drawn from the insight you have shown in answering my questions.", d=36.643, v="troll-female-old" },
		{ f="14822-82c04d6b", h="82c04d6b", t="I have long known you'd seek me out, $N.$B$BEvery sentient being in this world is driven by the choices they make.  Choices begat further choices, and these in turn make someone who they are.  This is where your fortune is drawn from - who you are, and the choices you make.$B$BAre you ready to discover where your fortune lies?", d=29.990, v="troll-female-old" },
		{ f="14822-8f79d751", h="8f79d751", t="Here is your fortune, $N.  May it serve you well. ", d=6.204, v="troll-female-old" },
		{ f="14822-b257b09f", h="b257b09f", t="Your next choice awaits.$B$BYou are the sworn executioner for your liege.  A man has been sent to you for execution as a traitor of the liege and your people.  You know this individual as a close, virtuous friend who mysteriously vanished one day.  You also know that the man's crimes for which he was convicted supposedly caused the deaths of many innocent civilians.  Upon seeing you he begs for his life, claiming he was framed by a higher authority.$B$BMake your choice.  ", d=38.480, v="troll-female-old" },
	},
	[14823] = {
		{ f="14823-68f16691", h="68f16691", t="Greetings my friend, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!", d=15.828, v="gnome-male-zany" },
	},
	[14827] = {
		{ f="14827-1aee1337", h="1aee1337", t="You mess with Silas, you mess with me.  Have a nice day.", d=5.800, v="ogre-male" },
		{ f="14827-478e3593", h="478e3593", t="If you're trying to be friendly, save your breath.  Better yet, just stop breathing all together.", d=9.080, v="ogre-male" },
		{ f="14827-8910ab9e", h="8910ab9e", t="In case it wasn't obvious, I'm not here for customer relations.", d=4.960, v="ogre-male" },
		{ f="14827-aa61a7a9", h="aa61a7a9", t="I need a second head like I need to lose my first one.", d=5.560, v="ogre-male" },
		{ f="14827-ba6b771b", h="ba6b771b", t="Move along, rube.", d=2.080, v="ogre-male" },
		{ f="14827-c7e3bd3b", h="c7e3bd3b", t="Unlike most ogres, I do know what an outhouse is for - giving you a swirlie.  Now beat it.", d=7.760, v="ogre-male" },
		{ f="14827-c9b051af", h="c9b051af", t="I lived in Dire Maul for a little bit.  That was fun.  Really.", d=7.480, v="ogre-male" },
		{ f="14827-e767cf68", h="e767cf68", t="This ain't a ride, clem.  Beat it.", d=3.760, v="ogre-male" },
	},
	[14828] = {
		{ f="14828-e87781f2", h="e87781f2", t="Ticket redemption here!  Get your tickets turned into prizes!  Step right up!", d=6.971, v="goblin-male-gruff" },
	},
	[14829] = {
		{ f="14829-21377806", h="21377806", t="Welcome!  Welcome to Yebb Neblegear's Darkmoon Zoo Bizarre - a Trove of Living Legends and Mythical Oddities!  Enjoy your visit, friend!$B$BBut be mindful of what you touch!  These exhibits hold artifacts and beasts both dire and divine!  They might burn the wayward hand of an over-curious onlooker...", d=14.496, v="gnome-male-standard" },
	},
	[14832] = {
		{ f="14832-02503cf8", h="02503cf8", t="$n, it's good to see you again!  Are you having fun at the Faire?$B$BWant to arm wrestle?  No, of course not... you want to keep your arm!", d=8.280, v="human-female-warrior" },
	},
	[14833] = {
		{ f="14833-01b197e9", h="01b197e9", t="Greetings.  I am Chronos - He Who Never Forgets.  My memory is without flaw, and exact to the most minor detail.$B$BTrust me.", d=11.160, v="scourge-male-standard" },
	},
	[14841] = {
		{ f="14841-1a08c33d", h="1a08c33d", t="Hello!  And welcome!  I'm afraid my booth is not open... many repairs are needed...$B$BBut I am still bound by blood oath to put a smile on your face.  So please, smile, or I must cut off my hand and consume no living flesh until it regenerates...", d=20.120, v="troll-male-dark" },
	},
	[14842] = {
		{ f="14842-4745561f", h="4745561f", t="It's here!  The Darkmoon Faire is now open for business!  Be sure to see the most exciting show on all of Azeroth!", d=8.920, v="dwarf-male-standard" },
		{ f="14842-548eb24b", h="548eb24b", t="When the Darkmoon Faire is open, it will be located in Elwynn Forest.  We'll be pitching our tents just south of Goldshire!", d=8.280, v="dwarf-male-standard" },
		{ f="14842-5f6093f0", h="5f6093f0", t="Step right up and hear about the most amazing spectacle in all of Azeroth - the Darkmoon Faire!  Huzzah!", d=7.920, v="dwarf-male-standard" },
		{ f="14842-66188cff", h="66188cff", t="The Darkmoon Faire is coming!  There is fun for children of ALL ages!  Come one, come all!", d=7.680, v="dwarf-male-standard" },
		{ f="14842-6622b27a", h="6622b27a", t="The Darkmoon Faire is coming to town!  Don't miss it!", d=3.400, v="dwarf-male-standard" },
		{ f="14842-8cf1bf36", h="8cf1bf36", t="The Darkmoon Faire is right now located in Elwynn Forest, just south of Goldshire.  Don't miss it!", d=6.240, v="dwarf-male-standard" },
		{ f="14842-b2bd23f3", h="b2bd23f3", t="Boys and girls - children of all ages - the Darkmoon Faire has arrived!  Huzzah!", d=5.600, v="dwarf-male-standard" },
		{ f="14842-ba5dfa18", h="ba5dfa18", t="When the Darkmoon Faire opens, it will be located in Mulgore.  We'll be pitching our tents just southwest of Thunder Bluff!", d=8.120, v="dwarf-male-standard" },
		{ f="14842-ba7baea2", h="ba7baea2", t="Be sure to catch all the amazing sights and wonders of the Darkmoon Faire when it comes to town!", d=6.720, v="dwarf-male-standard" },
		{ f="14842-cb1187da", h="cb1187da", t="The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see?", d=6.800, v="dwarf-male-standard" },
		{ f="14842-e651bb02", h="e651bb02", t="The Darkmoon Faire is right now located in the golden plains of Mulgore, just southwest of Thunder Bluff.  Don't miss it!", d=8.040, v="dwarf-male-standard" },
		{ f="14842-f55b97e1", h="f55b97e1", t="The Darkmoon Faire will only be live for a short time before the curtains are drawn closed.  Be sure to visit it today!", d=7.160, v="dwarf-male-standard" },
	},
	[14843] = {
		{ f="14843-4745561f", h="4745561f", t="It's here!  The Darkmoon Faire is now open for business!  Be sure to see the most exciting show on all of Azeroth!", d=10.812, v="orc-male-standard" },
		{ f="14843-548eb24b", h="548eb24b", t="When the Darkmoon Faire is open, it will be located in Elwynn Forest.  We'll be pitching our tents just south of Goldshire!", d=9.758, v="orc-male-standard" },
		{ f="14843-5f6093f0", h="5f6093f0", t="Step right up and hear about the most amazing spectacle in all of Azeroth - the Darkmoon Faire!  Huzzah!", d=9.740, v="orc-male-standard" },
		{ f="14843-66188cff", h="66188cff", t="The Darkmoon Faire is coming!  There is fun for children of ALL ages!  Come one, come all!", d=9.101, v="orc-male-standard" },
		{ f="14843-6622b27a", h="6622b27a", t="The Darkmoon Faire is coming to town!  Don't miss it!", d=5.067, v="orc-male-standard" },
		{ f="14843-8cf1bf36", h="8cf1bf36", t="The Darkmoon Faire is right now located in Elwynn Forest, just south of Goldshire.  Don't miss it!", d=8.849, v="orc-male-standard" },
		{ f="14843-b2bd23f3", h="b2bd23f3", t="Boys and girls - children of all ages - the Darkmoon Faire has arrived!  Huzzah!", d=7.789, v="orc-male-standard" },
		{ f="14843-ba5dfa18", h="ba5dfa18", t="When the Darkmoon Faire opens, it will be located in Mulgore.  We'll be pitching our tents just southwest of Thunder Bluff!", d=9.939, v="orc-male-standard" },
		{ f="14843-ba7baea2", h="ba7baea2", t="Be sure to catch all the amazing sights and wonders of the Darkmoon Faire when it comes to town!", d=8.002, v="orc-male-standard" },
		{ f="14843-cb1187da", h="cb1187da", t="The Darkmoon Faire has come to town!  Be sure to experience the most thrilling show you'll ever see!", d=8.369, v="orc-male-standard" },
		{ f="14843-e651bb02", h="e651bb02", t="The Darkmoon Faire is right now located in the golden plains of Mulgore, just southwest of Thunder Bluff.  Don't miss it!", d=10.742, v="orc-male-standard" },
		{ f="14843-f55b97e1", h="f55b97e1", t="The Darkmoon Faire will only be live for a short time before the curtains are drawn closed.  Be sure to visit it today!", d=8.998, v="orc-male-standard" },
	},
	[14844] = {
		{ f="14844-0558da42", h="0558da42", t="Don't be shy, buy a round for everyone!", d=3.596, v="nightelf-female-standard" },
		{ f="14844-b65b6caa", h="b65b6caa", t="Tasty drinks for sale!  Quench your thirst on some of the Darkmoon Faire's finest brews!", d=7.313, v="nightelf-female-standard" },
		{ f="14844-cee4b241", h="cee4b241", t="Tips are always graciously accepted, friend.", d=4.000, v="nightelf-female-standard" },
		{ f="14844-fb2c4c2e", h="fb2c4c2e", t="Just in... another batch of Darkmoon Special Reserve.  Come get yours before they're all gone!", d=6.384, v="nightelf-female-standard" },
	},
	[14845] = {
		{ f="14845-37f1d243", h="37f1d243", t="Step right up!  Get your red hot wings right here!", d=3.480, v="tauren-male-elder" },
		{ f="14845-3c101e0a", h="3c101e0a", t="For a limited time only, crunchy frog available exclusively here at the Darkmoon Faire.", d=8.600, v="tauren-male-elder" },
		{ f="14845-85eea98e", h="85eea98e", t="You've got money and we've got food.  What are you waiting for?!", d=7.040, v="tauren-male-elder" },
		{ f="14845-de918d19", h="de918d19", t="Darkmoon Dogs fresh off the grill.  Come and get em while they're hot!", d=5.200, v="tauren-male-elder" },
	},
	[14846] = {
		{ f="14846-1589ea27", h="1589ea27", t="Every item that I have for sale I acquired myself.  You have my personal guarantee of authenticity.", d=8.619, v="orc-female-warrior" },
		{ f="14846-25acb0e4", h="25acb0e4", t="Darkmoon Faire Cards?  See the Professor here for those.  Come see me if you are a dealer in hard to come by antiquities and artifacts.", d=9.312, v="orc-female-warrior" },
		{ f="14846-409d670a", h="409d670a", t="Have you any idea what I go through to bring these incomparable valuables to sell?  Come see them all for yourself!", d=8.336, v="orc-female-warrior" },
		{ f="14846-cc8d6fba", h="cc8d6fba", t="Come and take a look at my wares while you still can.  We're here all week, and then we're off to some far off land.", d=6.731, v="orc-female-warrior" },
	},
	[14847] = {
		{ f="14847-8b661936", h="8b661936", t="If you manage to complete a deck of portals cards you will be rewarded with a greater darkmoon card of the twisting nether.   This card will occasionally pull your spirit back into your body after death and restore you.", d=11.788, v="human-male-official" },
		{ f="14847-93db9468", h="93db9468", t="If you manage to complete a deck of beasts cards you will be rewarded with a greater darkmoon card of the blue dragon.   This is very useful in restoring of magical energies.", d=9.677, v="human-male-official" },
		{ f="14847-a4ea1408", h="a4ea1408", t="We have seeded Darkmoon Cards around the world to see if any worthy individuals could complete a set of any of the four suits.    If you manage to collect all eight cards of one of the suits we will reward you with one of the Greater Darkmoon cards that functions as a powerful trinket as well as a link to the Darkmoon Faire.", d=19.085, v="human-male-official" },
		{ f="14847-bf10b0c0", h="bf10b0c0", t="If you manage to complete a deck of warlords cards you will be rewarded with a greater darkmoon card of heroism.   This card will occasionally heal you while you are engaged in melee combat.", d=10.824, v="human-male-official" },
		{ f="14847-e2aa3fe0", h="e2aa3fe0", t="Welcome to the Faire young one!   We have collected wonders from all over the world for your perusal.   Oh and please let me know if you manage to collect a set of the lesser darkmoon cards, as the master...I mean I would be keenly interested in them.", d=13.761, v="human-male-official" },
		{ f="14847-eb4cc124", h="eb4cc124", t="If you manage to complete a deck of elementals cards you will be rewarded with a greater darkmoon card of the maelstrom.   This card will occasionally impact an enemy you are fighting with for heavy damage.", d=10.644, v="human-male-official" },
	},
	[14849] = {
		{ f="14849-061f8c33", h="061f8c33", t="Sure are a lot of litter bugs around here.", d=2.782, v="human-male-standard", s={ ["f"]=2.309 } },
		{ f="14849-0d047318", h="0d047318", t="That's right friend!  The Darkmoon Faire is going to be right here.  Just as soon as I unload those huge wagons, put up all the tents, erect the zoo and pour the drinks.  Make sure you come back!", d=13.137, v="human-male-standard", s={ ["f"]=11.717 } },
		{ f="14849-3ea148f2", h="3ea148f2", t="Won't be long now until the Darkmoon Faire opens.  Come back later and check to see if we're done.", d=6.351, v="human-male-standard", s={ ["f"]=4.800 } },
		{ f="14849-494b9cfd", h="494b9cfd", t="Faire's a coming!", d=1.184, v="human-male-standard", s={ ["f"]=1.431 } },
		{ f="14849-49a42070", h="49a42070", t="Can't you see I've got work to do here?", d=2.574, v="human-male-standard", s={ ["f"]=1.715 } },
		{ f="14849-951f53ce", h="951f53ce", t="The Darkmoon Faire is the greatest event on all of Azeroth!", d=4.383, v="human-male-standard", s={ ["f"]=3.653 } },
		{ f="14849-9598fc1b", h="9598fc1b", t="Having a good time?", d=1.407, v="human-male-standard", s={ ["f"]=1.467 } },
		{ f="14849-c3a8726b", h="c3a8726b", t="Don't forget to buy refreshments and souvenirs!", d=3.666, v="human-male-standard", s={ ["f"]=2.954 } },
	},
	[14860] = {
		{ f="14860-7f03671a", h="7f03671a", t="Get back here!", d=2.960, v="humanmalekid-male" },
		{ f="14860-a95f8578", h="a95f8578", t="Frogs and leather balls for sale!", d=2.760, v="humanmalekid-male" },
		{ f="14860-b884c1d1", h="b884c1d1", t="Hey, someone help me catch this thing!", d=3.200, v="humanmalekid-male" },
		{ f="14860-ff8a2b99", h="ff8a2b99", t="It's getting away!", d=1.440, v="humanmalekid-male" },
	},
	[14866] = {
		{ f="14866-09241431", h="09241431", t="Kiss me.", d=1.600, v="narrator", n={ [1]=0.840 } },
		{ f="14866-196e9561", h="196e9561", t="Ribbit.", d=1.360, v="narrator", n={ [1]=1.000 } },
	},
	[14871] = {
		{ f="14871-efd241fd", h="efd241fd", t="I can't find my pet frog, Jubjub.  She loves Dark Iron Ale, it's all she ever drinks, but can be so hard to get!  Now I'm out... and Jubjub must have run away to find more!$B$BI wish she would come back...", d=15.160, v="orc-female-shaman" },
		{ f="14871-f968da02", h="f968da02", t="I'm so happy that Jubjub returned!  I only hope that I don't run out of Dark Iron ale soon, or I fear my pet frog might once again escape!", d=11.120, v="orc-female-shaman" },
	},
	[14875] = {
		{ f="14875-0dff048f", h="0dff048f", t="If you have come to save the world then you have come to the right place. The faceless one - the Blood God, Hakkar - has been brought back into our world!", d=9.240, v="troll-male-shaman" },
	},
	[14902] = {
		{ f="14902-8aa43e13", h="8aa43e13", t="I am Jin'rokh the Breaker, envoy of Mugamba: Fist of Rastakhan!$B$BMy dealings are with warriors and heathens.", d=10.040, v="trolldire-male" },
	},
	[14903] = {
		{ f="14903-e3e1afb7", h="e3e1afb7", t="I am Al'tabim the All-Seeing - an envoy of King Rastakhan.$B$BMy dealings are with priests, mages, and warlocks.", d=10.160, v="troll-male-dark" },
	},
	[14904] = {
		{ f="14904-ba72aecb", h="ba72aecb", t="What you be expectin', mon?$B$BMaywiki only be dealin' with the druids and shaman.", d=5.880, v="troll-female-standard" },
	},
	[14905] = {
		{ f="14905-93a7d238", h="93a7d238", t="Sightless I may be, but vision I have.$B$BMy primary dealings are with hunters and rogues, $r.", d=9.640, v="troll-male-standard" },
		{ f="14905-adc7883f", h="adc7883f", t="The Paragons of Power are remnants from the ancient Gurubashi Empire.  We Zandalar seek them - not only are they of tremendous collectible value to us, but we believe that they also hold latent signatures of magic used by the old Empire.$B$BYou'll more than likely discover three kinds of Paragons in Zul'Gurub: coins, bijous, and primal items.  Bring them to us in the quantities that we seek, and you'll be rewarded with some of the finest items we Zandalar have ever crafted. ", d=42.110, v="troll-male-standard" },
	},
	[14910] = {
		{ f="14910-7b0860e0", h="7b0860e0", t="Greetings, $c.  I am Exzhal, Servitor of Rastakhan.", d=5.200, v="troll-male-shaman" },
	},
	[14921] = {
		{ f="14921-48abfac4", h="48abfac4", t="Hail, adventurer. I am Rin'wosho, trader of Zuldazar. I come from the South Seas and bring many exotic goods and items from my homeland.$B$BPerhaps if you prove your worth to my tribe, I shall barter.  If you have any of my tribe's Honor Tokens, then perhaps we shall barter even more.", d=23.880, v="troll-male-standard" },
	},
	[14942] = {
		{ f="14942-5204716c", h="5204716c", t="Lok'tar $c!  We have need of your services in Alterac Valley.  Shall I add you to the lists?", d=7.933, v="orc-female-warrior" },
		{ f="14942-9fdabcfe", h="9fdabcfe", t="I am sorry $c, but you need to be more experienced before you can survive in Alterac Valley.", d=7.744, v="orc-female-warrior" },
	},
	[14981] = {
		{ f="14981-7e5b36ab", h="7e5b36ab", t="I am sorry $c, but you are not seasoned enough yet to enter Warsong Gulch.", d=7.019, v="nightelf-female-sentinel" },
		{ f="14981-b475c580", h="b475c580", t="Hail to thee $n.  Do you wish me to aid you in your journey to Warsong Gulch?", d=6.771, v="nightelf-female-sentinel" },
	},
	[14982] = {
		{ f="14982-755d8f77", h="755d8f77", t="$C, we need your assistance at Warsong Gulch.  Will you aid us in our fight against the Warsong Outriders?", d=8.073, v="nightelf-female-sentinel" },
	},
	[14983] = {
		{ f="14983-08705d07", h="08705d07", t="The League of Arathor has sworn to retake Arathi for humans of Stromgarde and the Alliance.  It is a battle hard fought, but a battle worth fighting.", d=10.505, v="human-male-warrior" },
	},
	[14984] = {
		{ f="14984-08ede7bb", h="08ede7bb", t="To win this war, we can't sit idle and let the tides sweep us over.  We must strike, hard and fast, or Arathi will never again be ours.", d=7.960, v="human-female-warrior" },
	},
	[14990] = {
		{ f="14990-a6332cc8", h="a6332cc8", t="Our need for assistance in Arathi Basin is greater than one might imagine, $n.  So too is the honor and reputation one might acquire there in this time of need, however.  I implore you to seek out the Arathi Basin battlemaster in this city.", d=19.480, v="scourge-male-dark", s={ ["f"]=19.880 } },
		{ f="14990-e365821f", h="e365821f", t="You are not yet powerful enough, $c.  Move along.", d=6.760, v="scourge-male-dark", s={ ["f"]=5.280 } },
	},
	[14991] = {
		{ f="14991-080dd598", h="080dd598", t="Thank you for the offer, $c.  Unfortunately you are not yet experienced enough to weather the hazards of Arathi Basin.", d=8.584, v="human-male-official", s={ ["f"]=6.297 } },
		{ f="14991-a6f04183", h="a6f04183", t="Will you help us in our time of great need at Arathi Basin, $c?  The chance for increased honor and standing is greater than ever, and your assistance is sure to help to turn the tide against The Defilers.  Can we count on you?", d=13.724, v="human-male-official", s={ ["f"]=12.447 } },
	},
	[15006] = {
		{ f="15006-1f5c2160", h="1f5c2160", t="The humans and their so-called League of Arathor think to push us out of Arathi Basin.  I think not $c!  Are you ready to be sent there and demonstrate that it is they, and not The Defilers, that will be leaving soon?", d=18.080, v="scourge-female-magic" },
		{ f="15006-37d4a3c1", h="37d4a3c1", t="I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin.", d=8.640, v="scourge-female-magic" },
	},
	[15007] = {
		{ f="15007-a69352bd", h="a69352bd", t="Look around you $c.  You are in rare company to be certain, yet still I think you need to prove yourself.  Hmm, perhaps I shall allow you to aid us in our cause at Arathi Basin.  Would you like that?", d=14.880, v="scourge-male-dark" },
	},
	[15008] = {
		{ f="15008-37d4a3c1", h="37d4a3c1", t="I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin.", d=8.040, v="human-female-official" },
		{ f="15008-e2727850", h="e2727850", t="I've been expecting you $N.  Are you ready to assist us in Arathi Basin?", d=5.920, v="human-female-official" },
	},
	[15011] = {
		{ f="15011-c09ac14a", h="c09ac14a", t="Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.$B$BPlease feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year.", d=29.750, v="dwarf-male-standard" },
	},
	[15012] = {
		{ f="15012-c09ac14a", h="c09ac14a", t="Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.  Please feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year.", d=32.192, v="orc-male-standard" },
	},
	[15021] = {
		{ f="15021-ddd52957", h="ddd52957", t="We must not allow the Alliance to expand their power base in Arathi!  Even their miniscule Refuge Pointe may one day grow to threaten us.", d=9.840, v="scourge-female-warrior" },
	},
	[15022] = {
		{ f="15022-83ed336f", h="83ed336f", t="The battle for Arathi Basin is a battle for resources.  Lumber, ore, food... all these are needed in order to wage a good war.$B$BDenying our enemies of their supplies is as good as killing them on the battlefield.", d=13.960, v="scourge-male-warrior" },
	},
	[15042] = {
		{ f="15042-47a9db9f", h="47a9db9f", t="The first is a primal token that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.$B$BThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed Hoodoo piles.$B$BBring me these things and I will create a powerful enchantment for you!", d=28.710, v="troll-male-standard" },
		{ f="15042-adf5df7b", h="adf5df7b", t="Zanza can create the ancient troll enchantments with the right components. This magic will help you in defeating Hakkar and his minions.$B$BI only ask that you bring me two items.", d=14.440, v="troll-male-standard" },
		{ f="15042-f3eacbe9", h="f3eacbe9", t="I am Zanza, a Loa of Zandalar. I have come in this ethereal form from Zandalar to help my people. Hakkar has no dominion over my soul.$B$BI help those that have helped the Zandalarian people.", d=17.760, v="troll-male-standard" },
		{ f="15042-f8084c44", h="f8084c44", t="Have you? Then you know how weak and pathetic the high elf version of troll magic was?$B$BThe high elves could not understand why a people with their magical affinity could not contend with the powers of troll voodoo. This was an inconceivable notion for the pale skins to understand. They were resigned to using the bastardized version of troll enchantments. I believe they called them 'Arcanum.' ", d=31.710, v="troll-male-standard" },
	},
	[15070] = {
		{ f="15070-b19f3450", h="b19f3450", t="Behind me is the Altar of Zanza, a sacred place for us Zandalar.  We pray here to bolster our resolve in preparation for war against the Blood God, Hakkar.$B$BProve yourself to the tribe by using the altar to destroy any of the Hakkari Bijous you might find inside Zul'Gurub.  Also, I will trade you Honor Tokens our tribe uses for sets of coins you may find in Zul'Gurub.  Bring me the coins that I seek, and you will be rewarded!", d=31.030, v="troll-male-shaman" },
	},
	[15076] = {
		{ f="15076-c673f93b", h="c673f93b", t="We, the Zandalarian trolls, traveled here from distant islands, for we cannot ignore the threat that now faces our world.$B$BThe leader of our expedition, Molthor, brought us to the Yojamba Isle, along the northern coasts of Stranglethorn, and even now recruits brave heroes to venture into the ancient troll city... Zul'Gurub.", d=27.830, v="troll-male-dark" },
	},
	[15077] = {
		{ f="15077-75cc951c", h="75cc951c", t="Welcome to the Booty Bay fishing contest where each week we choose the finest fisherman to be the Master Angler!  Between 2pm and 4pm schools of tastyfish will appear up and down the coast of Stranglethorn.  While fishing if your fishing bobber lands in a tastyfish school then you will catch something from the school rather than the normal stranglethorn fishing fare. ", d=20.533, v="goblin-male-zany" },
		{ f="15077-dd14ce12", h="dd14ce12", t="We already have a winner for our contest, but Jang is willing to purchase any Tastyfish that you have fished up!  There is always next Sunday for you to show your Angling skill!", d=9.609, v="goblin-male-zany" },
	},
	[15078] = {
		{ f="15078-07df529b", h="07df529b", t="Fishmaster Bassbait has had the waters here seeded with high quality tastyfish so he can have his weekly tournament.    Me? I'm here to hand out the prizes! Whether you win or simply have a few tastyfish to spare, I'm your gal.", d=17.160, v="goblin-female-s107" },
		{ f="15078-fe4b2bc8", h="fe4b2bc8", t="Fishmaster Bassbait has had the waters here seeded with high quality Tastyfish so he can have his tournament.  Once he gets his winner, I will give you silver for each five Tastyfish you bring me! ", d=13.440, v="goblin-female-s107" },
	},
	[15079] = {
		{ f="15079-457990d2", h="457990d2", t="*Whirr* *CLANK*  I have been instructed to accept high quality rare fish and return valuable Nat Pagle fishing accessories.   Fish Requested.  *THUMP* *Buzz* ", d=12.840, v="narrator", n={ [1]=17.600 } },
	},
	[15080] = {
		{ f="15080-66f6d681", h="66f6d681", t="The Zandalarian trolls have traveled far and suffered much to reach this place, but to do nothing... is to invite our doom...", d=10.640, v="troll-male-dark", s={ ["f"]=8.720 } },
	},
	[15102] = {
		{ f="15102-412c32a4", h="412c32a4", t="The seasons turn for all in due time, but you are still in the springtime of your life.  Please return to us later, $c, when you have experienced more.", d=12.880, v="nightelf-female-priestess" },
		{ f="15102-775be74e", h="775be74e", t="$C, we are not ashamed to say that we are in need of all of the assistance that we can get in our fight at Warsong Gulch.  But there is greater honor to be had now than at any time in the past if you so choose to lend us your skills.  As well, the Silverwing Sentinels are sure to look more favorably upon your efforts on our behalf.  Will you join the battle?", d=25.550, v="nightelf-female-priestess" },
	},
	[15103] = {
		{ f="15103-a0423a66", h="a0423a66", t="I'm afraid ye would not survive long in Alterac Valley, $c.  Come back and see us when you have a few more seasons under your belt.", d=7.840, v="dwarf-male-grim", s={ ["f"]=8.080 } },
		{ f="15103-c401ba80", h="c401ba80", t="$n, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?", d=12.560, v="dwarf-male-grim", s={ ["f"]=14.240 } },
	},
	[15105] = {
		{ f="15105-2210b5da", h="2210b5da", t="$C, we have a great need for your help in Warsong Gulch against the Silverwing Sentinels.  And there is even greater honor and reputation with the Warsong Outriders to be gained as well!  Do you have the courage to enter battle?", d=18.280, v="orc-male-guard", s={ ["f"]=15.560 } },
		{ f="15105-483fe302", h="483fe302", t="Unfortunately you are not yet strong enough to survive in Warsong Gulch, $c.", d=7.800, v="orc-male-guard", s={ ["f"]=5.680 } },
	},
	[15106] = {
		{ f="15106-d9a8318f", h="d9a8318f", t="You need to be stronger, $c before you can help us in Alterac Valley.", d=7.000, v="orc-male-guard", s={ ["f"]=5.360 } },
		{ f="15106-e1c9a6bd", h="e1c9a6bd", t="Hail, $c.  There is a great need and even greater honor and renown to be had in Alterac Valley at this time. Will you join our fight against the Stormpike Guard?", d=14.000, v="orc-male-guard", s={ ["f"]=11.360 } },
	},
	[15116] = {
		{ f="15116-19dfe25a", h="19dfe25a", t="Hey Hey Hey!  I am here to promote a fabulous fishing tournament in Stranglethorn but you need to be tough enough to survive there and have enough skill in fishing to fish those waters.$B$B Come back later when you are more qualified!  ", d=13.032, v="goblin-male-zany" },
		{ f="15116-762adbbc", h="762adbbc", t="Heya Heya Heya!   If you want to test your fishing skills then I have just the place for you!   This Sunday we have a fishing tournament in Stranglethorn!  ", d=9.041, v="goblin-male-zany" },
	},
	[15119] = {
		{ f="15119-14a8498e", h="14a8498e", t="Well met master of Rod and Reel!   If you be willing to test your skills against the best fisher-folk in the lands then listen up!   On this very Sunday there be a contest in Stranglethorn where the master angler will be chosen!  ", d=12.440, v="dwarf-male-standard" },
		{ f="15119-cb343581", h="cb343581", t="Greetings!  I am here to promote a tournament to test your fishing skill in Stranglethorn.  To participate you need enough might to survive there and have enough skill in fishing to coax the fish from the water.$B$B Come back later when you are more qualified!  ", d=15.960, v="dwarf-male-standard" },
	},
	[15126] = {
		{ f="15126-425e11b4", h="425e11b4", t="I am Rutherford Twing, the main supplier for the Defilers posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services.", d=16.840, v="scourge-male-dark" },
	},
	[15127] = {
		{ f="15127-e2791228", h="e2791228", t="I am Samuel Hawke, the main supplier for the League of Arathor posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services.", d=18.182, v="human-male-warrior" },
	},
	[15169] = {
		{ f="15169-12ee88f2", h="12ee88f2", t="They say that I am blessed: A herald to harken in a new age.", d=4.800, v="nightelf-female-priestess" },
		{ f="15169-306fde6d", h="306fde6d", t="Greetings, traveler. It was here, nearly 1,000 years past, that the Qiraji began their march of destruction across Kalimdor.$B$BThousands of lives were lost during the war, most in this cursed desert during the initial invasion.$B$BI am one of only a few that remain, chained to both the past and the present. I know not why I am to remain stationed here but I know that I must.", d=30.710, v="nightelf-female-priestess" },
		{ f="15169-3f375ba6", h="3f375ba6", t="Ancient forces stir - forces that have not been seen or felt for thousands of years. The world weeps, $r. Perhaps a new sundering comes. A sickness born from within...$B$BThe foulness has begun to seep into our lands. From the Dream come nightmares. Nightmares to befoul us in our waking hours... ", d=21.760, v="nightelf-female-priestess" },
		{ f="15169-d8ba938d", h="d8ba938d", t="I have been slain a hundred times. I always wake here, alive. Some say I am cursed and others...", d=8.000, v="nightelf-female-priestess" },
	},
	[15170] = {
		{ f="15170-0bf94464", h="0bf94464", t="Bronzebeard's gone missing again! That dwarf sure didn't get any of his brother's good senses.", d=4.760, v="dwarf-male-grim" },
		{ f="15170-0c8652a9", h="0c8652a9", t="You best have a seat then, this is gonna be a long one.$B$BWhen we initially arrived in Silithus, Mistress Mar'alith was the first of the night elves from Cenarion Hold to join the expedition. Our routine was nothing out of the ordinary: Form a party to venture into the various hives and search for lost artifacts. ", d=18.150, v="dwarf-male-grim" },
		{ f="15170-41186aa4", h="41186aa4", t="It sure is! Those hives were abuzz with various silithid that were none too happy to see us.$B$BEverything was going fine until we came across a glyphed crystal in Hive'Regal. She was drawn to it like a moth to a flame! She put her pretty little cheek up against the crystal and instantly entered a trance-like state. Naturally, this worried my crew. We picked her up and carried her out of there with a quickness!", d=23.270, v="dwarf-male-grim" },
		{ f="15170-41693978", h="41693978", t="We took her to the Commander with hopes that the druids of the Circle could fix her up. Sure enough, they were able to wake her up. We figured our business with the Circle was done and we could get back to work.$B$BA few weeks passed and everything was going fine. Brann was still around back then so we had a bit of order in our work structure. Then one day, out of the blue, she appeared back at our camp. ", d=21.190, v="dwarf-male-grim" },
		{ f="15170-4e04b849", h="4e04b849", t="Are you daft? Who else would I be talking about? Yes, the girl - Mistress Mar'alith. Anyhow, she was back and not in too good of a mood. That's when the demands started flowing. ", d=11.040, v="dwarf-male-grim" },
		{ f="15170-8283a150", h="8283a150", t="Who knows? Anyhow, that was the last I saw of her. Maybe Frankal can give you better information.$B$BNot to steer off topic here as I'm sure the work you're doing for the Commander is important, but we're onto something huge here. HUGE! Our requests to Ironforge for an army have so far fallen on deaf ears. Apparently we're stretched too thin in protecting the realm or some such nonsense. Once you take your report back to the Commander, come back down here with some friends. We need your help!", d=28.670, v="dwarf-male-grim" },
		{ f="15170-8cf31240", h="8cf31240", t="She demanded that we immediately head back to Hive'Regal! Brann would have none of that sass. He told her that there's no way we would go back into those hives without an army backing us up. It had gotten far too dangerous. The number of those stinking insects seemed to have tripled from when we first ventured into 'em.$B$BThat's when Natalia lost it!", d=19.030, v="dwarf-male-grim" },
		{ f="15170-c887afd9", h="c887afd9", t="What do you mean what do I mean? She went nutso! The girl went straight crazy on us. Now ordinarily I don't hit girls but after I recovered from the blackout, I was pretty damned angry. Brann, Rutgar, me and the monkey went positively orc on her! It's a miracle we were able to fend her off. She seemed almost possessed!", d=18.950, v="dwarf-male-grim" },
	},
	[15171] = {
		{ f="15171-0373769c", h="0373769c", t="Listen $g sonny:missy;, I'll have you know that whatever attacked us was no priestess of nothin'! Her eyes were aglow with something evil and she was genuinely frothing at the mouth! She came in, did some kind of crazy scream that sent us all runnin' in separate directions then started flayin' our minds one by one. I'd be hearin' shadowy words in my head, watchin' the other's periodically black out here and there. It was madness! We would have been done for if not for the damned monkey.", d=29.660, v="dwarf-male-standard", g=true },
		{ f="15171-0b88c313", h="0b88c313", t="Yep.", d=2.280, v="dwarf-male-standard" },
		{ f="15171-6382ebb1", h="6382ebb1", t="You're telling me! It's even stranger considering between Brann, Rutgar, me and the monkey, we know 38 different languages including a touch of Titan - both Vanir and Aesir.$B$BSo anyway, whatever she was click clacking about, it definitely wasn't with anyone \"present.\" She then nodded and went on the offensive! Attacked us outright!", d=22.150, v="dwarf-male-standard" },
		{ f="15171-674d1906", h="674d1906", t="I'll tell you 'then what.' She went runnin' straight for the hive. And you know what's crazier? Not a single damned bug got in her way or tried to stop her. She ran through them all as if she'd been best friends with 'em for centuries.", d=12.680, v="dwarf-male-standard" },
		{ f="15171-708c4ed2", h="708c4ed2", t="Oh brother, not this again... Have a seat $g sonny:missy;.$B$BI'm sure Rutgar has told you some of this story already so I'll spare you the boring details and get right down to the nitty gritty.", d=10.440, v="dwarf-male-standard", g=true },
		{ f="15171-9003372a", h="9003372a", t="Look up to the heavens, $c. The Dragonflights have not been seen in this area for a thousand years! Those Qiraji are up to something, I just know it!", d=10.160, v="dwarf-male-standard" },
		{ f="15171-a79c2deb", h="a79c2deb", t="What's there to ask? He's a monkey you crazy fool. Anyhow, so yea, the monkey went into a frenzy after seein' ol' Brann flop into the sand face first. Nothin' the night elf could do was stopping Glibb here from poundin' on her noggin.", d=13.800, v="dwarf-male-standard" },
		{ f="15171-ef179f6c", h="ef179f6c", t="Right then! So the Mistress had come back for a second go at the hives but Brann was having none of that nonsense! Before the melee began, she started talking to something or someone. Crazier still, she started chanting in a language none of us had ever heard.", d=15.880, v="dwarf-male-standard" },
	},
	[15174] = {
		{ f="15174-03ca5480", h="03ca5480", t="Once the capital city of the Dark Iron dwarves, this volcanic labyrinth now serves as the seat of power for Ragnaros the Firelord. Ragnaros has uncovered the secret to creating life from stone and plans to build an army of unstoppable golems to aid him in conquering the whole of Blackrock Mountain. Obsessed with defeating Nefarian and his draconic minions, Ragnaros will go to any extreme to achieve final victory.   ", d=32.152, v="nightelf-female-standard" },
		{ f="15174-174473b0", h="174473b0", t="Recently, a night elf druid named Naralex discovered a network of underground caverns within the heart of the Barrens. Believing he could use the caverns' springs to restore lushness to the Barrens, the druid began siphoning the energies of the fabled Emerald Dream. His vision somehow became a nightmare, however, and soon the Wailing Caverns changed into a den of vicious, deadly predators. It is said that Naralex still resides somewhere inside the labyrinth, trapped beyond the edges of the Emerald Dream.  ", d=37.404, v="nightelf-female-standard" },
		{ f="15174-17e9d243", h="17e9d243", t="Uldaman is an ancient Titan vault that has laid buried within the earth since the world's creation. Dwarven excavations of the city have recently released the Titans' first failed creations: the troggs. Legends say that when the Titans deemed the trogg experiment a failure they tried again, resulting in the creation of the dwarven race. These secrets are recorded on the fabled Discs of Norgannon - massive artifacts that lie at the bottom of the ancient city, protected by giant constructs of living stone.  ", d=36.505, v="nightelf-female-standard" },
		{ f="15174-19490f29", h="19490f29", t="Maraudon is one of the most sacred sites within Desolace. The great temple/cavern is the burial place of Zaetar, one of two immortal sons born to the demigod, Cenarius. Legend holds that Zaetar and the earth elemental princess, Theradras, sired the misbegotten centaur race. It is said that upon their emergence, the barbaric centaur turned on their father and killed him. Some believe that Theradras, in her grief, trapped Zaetar's spirit within the winding cavern - used its energies for some malign purpose. ", d=38.293, v="nightelf-female-standard" },
		{ f="15174-19cbe7de", h="19cbe7de", t="When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande.", d=19.232, v="nightelf-female-standard" },
		{ f="15174-1a6e2552", h="1a6e2552", t="This sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called Sul'thraze the Lasher, a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls. ", d=32.273, v="nightelf-female-standard" },
		{ f="15174-22aa3fe4", h="22aa3fe4", t="Razorfen Downs can be found on the very southern tip of the Barrens on the east side of the road.", d=7.192, v="nightelf-female-standard" },
		{ f="15174-2e88eda5", h="2e88eda5", t="Frustrated by the Dalaran wizards' lack of progress against the undead during the Third War, the Archmage Arugal elected to summon the extra-dimensional worgen to bolster his side's diminishing ranks. The wolf-men slaughtered the Scourge, then quickly turned on the wizards themselves and laid siege to the keep of the noble, Baron Silverlaine. The fort quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'.  ", d=36.546, v="nightelf-female-standard" },
		{ f="15174-3141b27b", h="3141b27b", t="Crafted from the same vines as Razorfen Kraul, Razorfen Downs is the traditional capital city of the quilboar race. The sprawling, thorn-ridden labyrinth houses a veritable army of loyal quilboar as well as their high priests - the Death's Head tribe. Recently, however, a looming shadow has fallen over the crude den. Agents of the undead Scourge - led by the lich, Amnennar the Coldbringer - have taken control over the quilboar race and turned the maze of thorns into a bastion of undead might.   ", d=36.233, v="nightelf-female-standard" },
		{ f="15174-330cd2db", h="330cd2db", t="The mighty fortress carved within the fiery bowels of Blackrock Mountain was held by the sinister Dark Iron dwarves for centuries until Nefarian - the cunning son of the dragon, Deathwing - took control of the upper Spire and made war on the dwarves' holdings in the mountain's volcanic depths. Realizing that the dwarves were led by the mighty fire elemental, Ragnaros - Nefarian vowed to crush his enemies and claim the whole of Blackrock mountain for himself.  ", d=31.141, v="nightelf-female-standard" },
		{ f="15174-33439fd8", h="33439fd8", t="Over a thousand years ago a group of troll priests known as the Atal'ai attempted to bring back an ancient blood god named Hakkar the Soulflayer. After the resulting civil war the priests were defeated and exiled to the Swamp of Sorrows. There they erected a temple to Hakkar to prepare for his arrival into the physical world. The dragon Aspect Ysera soon learned of the Atal'ai's plans and smashed the temple beneath the marshes. To this day, the temple's ruins are guarded by the mighty green dragons. ", d=37.323, v="nightelf-female-standard" },
		{ f="15174-342c02c0", h="342c02c0", t="The Stockades are a high-security prison complex, hidden beneath the canal district of Stormwind city. Presided over by Warden Thelwater, the Stockades are home to petty crooks, political insurgents, murderers and a score of the most dangerous criminals in the land. Recently, a prisoner-led revolt has resulted in a state of pandemonium within the Stockades - where the guards have been driven out and the convicts roam free.  ", d=30.818, v="nightelf-female-standard" },
		{ f="15174-4a0923b3", h="4a0923b3", t="Are you interested in exploring one of these dungeons?", d=4.727, v="nightelf-female-standard" },
		{ f="15174-4a6950fb", h="4a6950fb", t="The ruins of Dire Maul stand in central Ferelas.", d=4.323, v="nightelf-female-standard" },
		{ f="15174-4f48ef1f", h="4f48ef1f", t="Situated along the Zoram Strand of Ashenvale, Blackfathom Deeps was once a glorious temple dedicated to the night elves' moon-goddess Elune. However, the great Sundering shattered the temple - sinking it beneath the waves of the Veiled Sea. There it remained untouched - until, drawn by its ancient power - the naga and satyr emerged to plumb its secrets. Legends hold that the ancient beast, Aku'mai, has taken up residence within the temple's ruins.  ", d=35.707, v="nightelf-female-standard" },
		{ f="15174-581034a1", h="581034a1", t="The Scholomance is housed in crypts beneath the Caer Darrow keep. Once owned by the noble Barov family, the keep fell to ruin after the Second War. As the wizard Kel'Thuzad enlisted followers for his Cult of the Damned, he often promised immortality for those who served his Lich King. The Barovs fell to his influence and donated their keep, but the cultists killed the family and turned the crypts into a school of necromancy. Though Kel'Thuzad no longer resides there, cultists and instructors still remain. ", d=34.899, v="nightelf-female-standard" },
		{ f="15174-5dc31760", h="5dc31760", t="During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose. ", d=37.647, v="nightelf-female-standard" },
		{ f="15174-5eccd4fa", h="5eccd4fa", t="The Sunken Temple can be found in the center of a great lake in eastern Swamp of Sorrows.", d=7.354, v="nightelf-female-standard" },
		{ f="15174-5ff7a251", h="5ff7a251", t="Scarlet Monastery lies in the hills northeast of Tirisfal Glades.", d=6.101, v="nightelf-female-standard" },
		{ f="15174-66f64f6e", h="66f64f6e", t="Razorfen Kraul can be found on the very southern tip of the Barrens on the west side of the road.", d=6.586, v="nightelf-female-standard" },
		{ f="15174-69040db4", h="69040db4", t="Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they'll give you a gift of friendship.", d=18.182, v="nightelf-female-standard" },
		{ f="15174-6a089d41", h="6a089d41", t="The ruined city of Stratholme lies in the Eastern Plaguelands to the north of the Plaguewood.", d=7.192, v="nightelf-female-standard" },
		{ f="15174-6a11bf14", h="6a11bf14", t="You're a leatherworker by trade, aren't you?  It's that faint smell of cured hides, I'd recognize it anywhere.$B$BMy father used to talk about a famous artisan who lived in Southwind Village centuries ago.  It's a shame the place is in ruins now.", d=18.101, v="nightelf-female-standard" },
		{ f="15174-70185dce", h="70185dce", t="Uldaman can be found at the very northern end of the Badlands.", d=4.525, v="nightelf-female-standard" },
		{ f="15174-7b1bcef4", h="7b1bcef4", t="The Deadmines can be found beneath Moonbrook in the south of Westfall.", d=4.485, v="nightelf-female-standard" },
		{ f="15174-7de88db1", h="7de88db1", t="Located in Dun Morogh, Gnomeregan has been the gnomes' capital city for generations, though it was recently infested by mutant troggs. In a desperate attempt to retaliate, High Tinker Mekkatorque ordered the emergency venting of the city's radioactive waste tanks. Though the troggs became irradiated, their siege continued unabated and the gnomes were forced to seek refuge in the dwarven city of Ironforge, where the High Tinker now enlists brave souls to help his people reclaim their beloved city.  ", d=34.455, v="nightelf-female-standard" },
		{ f="15174-864c5566", h="864c5566", t="The Wailing Caverns has its entrance at the Lushwater Oasis southwest of Crossroads in the Barrens.   ", d=7.919, v="nightelf-female-standard" },
		{ f="15174-95351c86", h="95351c86", t="Once the jewel of northern Lordaeron, the city of Stratholme is where Prince Arthas turned against his mentor, Uther Lightbringer, and slaughtered hundreds of his own subjects who were believed to have contracted the plague of undeath. Arthas' surrender to the Lich King soon followed. The broken city is now inhabited by the undead Scourge - led by the powerful lich, Kel'Thuzad, and a contingent of Scarlet Crusaders, led by Grand Crusader Dathrohan. The two sides are locked in constant, violent combat.  ", d=36.111, v="nightelf-female-standard" },
		{ f="15174-a9df0aa1", h="a9df0aa1", t="Blackfathom Deeps can be found at the north end of Zoram Strand along the coast of Ashenvale.", d=7.556, v="nightelf-female-standard" },
		{ f="15174-ab572ddf", h="ab572ddf", t="The monastery was once a center for learning and enlightenment. With the rise of the undead Scourge during the Third War, the peaceful Monastery was converted into a stronghold of the fanatical Scarlet Crusade. The Crusaders are intolerant of all non-human races, regardless of alliance or affiliation. They believe that any and all outsiders are potential carriers of the undead plague - and must be destroyed.  ", d=28.273, v="nightelf-female-standard" },
		{ f="15174-ad5ec0ca", h="ad5ec0ca", t="No, I'm not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!", d=11.030, v="nightelf-female-standard" },
		{ f="15174-adc7501c", h="adc7501c", t="The School for Necromancy known as Scholomance is on the ruined island of Caer Darrow in the Western Plaguelands.", d=8.566, v="nightelf-female-standard" },
		{ f="15174-b69e98a5", h="b69e98a5", t="If you put on cologne or perfume, then you'll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne.", d=22.303, v="nightelf-female-standard" },
		{ f="15174-b852ea17", h="b852ea17", t="Ragefire Chasm consists of a network of volcanic caverns below the orcs' new capital city of Orgrimmar. Recently, rumors have spread that a cult loyal to the demonic Shadow Council has taken up residence within the Chasm's fiery depths. This cult, known as the Burning Blade, threatens the very sovereignty of Durotar. Many believe that the orc Warchief Thrall is aware of the Blade's existence and has chosen not to destroy it in the hopes that its members might lead him straight to the Shadow Council.  ", d=37.444, v="nightelf-female-standard" },
		{ f="15174-b8eefffb", h="b8eefffb", t="Shadowfang Keep is in southern Silverpine just north of Pyrewood Village.", d=6.990, v="nightelf-female-standard" },
		{ f="15174-b8ef9c65", h="b8ef9c65", t="The Stormwind Stockades are found near the mage quarter in Stormwind.", d=4.566, v="nightelf-female-standard" },
		{ f="15174-c2bfa0cf", h="c2bfa0cf", t="Gnomeregan can be found in western Dun Morogh.", d=3.798, v="nightelf-female-standard" },
		{ f="15174-ca5fde90", h="ca5fde90", t="Maraudon is located in the middle of the western coast of Desolace, in the Valley of Spears.", d=7.030, v="nightelf-female-standard" },
		{ f="15174-d352a290", h="d352a290", t="Once the greatest gold production center in the human lands, the Dead Mines are now inhabited by the Defias Brotherhood, who have turned the dark tunnels into their private sanctum. It is rumored that the thieves have conscripted the clever goblins to help them build something terrible at the bottom of the mines - but what that may be is still uncertain. Rumor has it that the way into the Deadmines lies through the quiet, unassuming village of Moonbrook. ", d=29.040, v="nightelf-female-standard" },
		{ f="15174-e99614f5", h="e99614f5", t="The ruins of Zul'Farrak are located in the northwestern corner of the Tanaris Desert.", d=7.273, v="nightelf-female-standard" },
		{ f="15174-f106f818", h="f106f818", t="Built twelve thousand years ago by a covert sect of night elf sorcerers, the ancient city of Eldre'Thalas was used to protect Queen Azshara's most prized arcane secrets. Though it was ravaged by the Great Sundering of the world, much of the wondrous city still stands as the imposing Dire Maul. The ruins' three distinct districts have been overrun by all manner of creatures - especially the spectral highborne, foul satyr and brutish ogres.  ", d=33.404, v="nightelf-female-standard" },
		{ f="15174-f2218c4a", h="f2218c4a", t="Blackrock Mountain lies between Searing Gorge in the north and Burning Steppes in the south.", d=7.677, v="nightelf-female-standard" },
		{ f="15174-f88f28f5", h="f88f28f5", t="Ragefire Chasm can be found beneath the Shadow Cleft in the center of Orgrimmar.", d=6.061, v="nightelf-female-standard" },
		{ f="15174-f9fa0d11", h="f9fa0d11", t="When you give love tokens to townsfolk, you'll receive different gifts in return.  Some of those you'll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall.", d=21.576, v="nightelf-female-standard" },
		{ f="15174-fef738e8", h="fef738e8", t="Greetings, traveler. As long as you remain within the walls of the Cenarion Hold, you will be safe from harm.$B$BBe wary when leaving the protection of the Hold as the silithid have been swarming as of late.", d=15.475, v="nightelf-female-standard" },
	},
	[15175] = {
		{ f="15175-8fe865b5", h="8fe865b5", t="I supply the Hold with various relics required for spellcasting as well as other alchemical reagents.", d=6.477, v="tauren-male-warrior" },
	},
	[15176] = {
		{ f="15176-94936618", h="94936618", t="A great evil stirs, $r. Can you feel it?$B$BBah! Of course you cannot. Hand me your armor and weapons and I shall renew their vigor.", d=10.067, v="tauren-male-warrior" },
	},
	[15177] = {
		{ f="15177-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.680, v="nightelf-male-standard" },
	},
	[15178] = {
		{ f="15178-c5ceacbe", h="c5ceacbe", t="Where would you like to fly to?", d=2.034, v="tauren-male-warrior" },
	},
	[15179] = {
		{ f="15179-fcdc37cc", h="fcdc37cc", t="Oh dear, I am running dangerously low on supplies! What is taking that blasted goblin so long?", d=8.000, v="nightelf-female-standard" },
	},
	[15180] = {
		{ f="15180-324b12b7", h="324b12b7", t="Look behind you, $r. The hive stirs as the land that surrounds us shudders and shakes.$B$BThe time has come for me to fulfill a promise I made a thousand years past. The sands shift once more as the Qiraji plan for war.", d=17.080, v="nightelf-male-standard" },
	},
	[15181] = {
		{ f="15181-1a01471b", h="1a01471b", t="Why now, $r? I just do not understand it. So much work to be done...", d=7.520, v="nightelf-male-official" },
	},
	[15182] = {
		{ f="15182-0cf3f23f", h="0cf3f23f", t="You're hunting Deathclasp, $n?  Color me impressed.  I lost two of my men to her this week alone.  Let's hope your luck is better than theirs.", d=10.720, v="nightelf-male-official" },
		{ f="15182-6b3175e0", h="6b3175e0", t="The Commander has not been himself as of late. His mistress disappeared while on an archaeological dig in the southern desert - vanished without a trace! Very strange, indeed.$B$BI suppose you're looking for work? Do I need to bash you in the head with a clue?", d=18.360, v="nightelf-male-official" },
	},
	[15183] = {
		{ f="15183-6f001d4b", h="6f001d4b", t="Can ye hear it, stranger? The humming is gettin' louder with each passing day. These crystals must be what's driving these bugs crazy.", d=7.201, v="dwarf-female-maternal" },
	},
	[15190] = {
		{ f="15190-991942c9", h="991942c9", t="Who are you?  Where am I?  I feel... so weak...", d=3.160, v="goblin-male" },
		{ f="15190-b8bd42ee", h="b8bd42ee", t="Hey!  Thanks for saving my hide!  I think I'll be lying down for a while until I recover my strength.", d=4.640, v="goblin-male" },
	},
	[15191] = {
		{ f="15191-2bb55da5", h="2bb55da5", t="It's a pleasure to see you again, $n.  Your aid has provided us with a considerable boost in the security of our supply lines.  I hope you understand the importance of the logistics involved in large battle efforts such as this.", d=15.560, v="tauren-female-shaman" },
		{ f="15191-abf74ccb", h="abf74ccb", t="Greetings, $c.  Welcome to Cenarion Hold.  From here we will strike against the silithid where they're at their strongest.  I hope you've come to lend a hand.", d=11.760, v="tauren-female-shaman" },
	},
	[15192] = {
		{ f="15192-4a19da8c", h="4a19da8c", t="It is we who must make the first strike. We cannot be allowed to repeat the mistakes of the past...", d=5.480, v="bloodelf-male" },
	},
	[15194] = {
		{ f="15194-26e6eae6", h="26e6eae6", t="You're back already!  What can I do for you now?", d=3.371, v="human-male-standard" },
		{ f="15194-43652201", h="43652201", t="Leave at once, stranger!  I have no business with you.", d=4.017, v="human-male-standard" },
	},
	[15195] = {
		{ f="15195-18348e53", h="18348e53", t="You like candy?  I like candy.", d=5.278, v="npc-10699" },
		{ f="15195-53e797cf", h="53e797cf", t="Go Forsaken!  Yay us!", d=5.145, v="npc-10699" },
		{ f="15195-86be5218", h="86be5218", t="Happy Hallow's End, $c!", d=6.031, v="npc-10699" },
	},
	[15197] = {
		{ f="15197-c0048786", h="c0048786", t="Welcome to the Wickerman Festival, $c!$B$BOn the observance of Hallow's End, the Forsaken burn a wickerman in honor of this, the most revered of occasions.  It was on this day that the Banshee Queen herself delivered us from the clutches of the Lich King and the Scourge.  We have remained free ever since.  Those who would have seen us fall are repayed in full... with vengeance!$B$BThe burning of the Wickerman begins at 8:00 PM!", d=37.590, v="scourge-female-magic" },
	},
	[15199] = {
		{ f="15199-1bdeee2c", h="1bdeee2c", t="You there!  You look able bodied... we need your aid in defending Southshore!$B$BThe blasted Forsaken are all riled up because it's Hallow's End.  Their \"celebration\" will no doubt be leading them right to our doorstep.  If you've got the time, we really could use your help!", d=17.212, v="human-male-warrior" },
	},
	[15270] = {
		{ f="15270-da410729", h="da410729", t="The spirits of Silithus call out to us, $n.  The land weeps, for it has a woeful story to tell...", d=9.280, v="tauren-male-shaman" },
	},
	[15282] = {
		{ f="15282-b440c659", h="b440c659", t="The Cenarion Circle is wise, and has delved into many of earth's secrets.  Craftsmen would do well to heed the words of these druids.", d=11.232, v="nightelf-female-standard" },
	},
	[15303] = {
		{ f="15303-60c79f0d", h="60c79f0d", t="Oh that's simple! You use it like anything else you might activate. Don't worry, I'll take care of lighting the fuse. Once you're up in the air you'll notice that you'll seem to \"float,\" but that won't last forever. What you're aiming for is a target on the lake way over yonder. Make sure that you begin your descent by detaching your \"wings\" at the right time to land in the water, or, well, I don't sell life insurance.", d=18.391, v="gnome-female-nerdy" },
		{ f="15303-af31a089", h="af31a089", t="Welcome! Step right up, don't be shy. This here is my pride and joy... the Blastenheimer 5000 Ultra Cannon! Ain't she pretty? You look a little big around the mid section, but I think you'll fit. Flying is so much fun, want to learn how?", d=11.643, v="gnome-female-nerdy" },
	},
	[15306] = {
		{ f="15306-51773b08", h="51773b08", t="We have more than one enemy in Silithus, $N.$B$BWhile everyone's attention is focused on the silithid, my big brother and I have been keeping a close eye on the Twilight's Hammer crazies.  ", d=11.861, v="tauren-male-warrior" },
	},
	[15309] = {
		{ f="15309-71078e81", h="71078e81", t="You're the best, $n - thanks for going trick-or-treating for me!", d=4.200, v="humanfemalekid-female" },
		{ f="15309-d11310f6", h="d11310f6", t="I'm sad!  It's Hallow's End, and I'm sick.  I'm going to miss out on trick-or-treating because I can't go out!", d=7.720, v="humanfemalekid-female" },
	},
	[15310] = {
		{ f="15310-71078e81", h="71078e81", t="You're the best, $n - thanks for going trick-or-treating for me!", d=4.480, v="humanmalekid-male" },
		{ f="15310-d11310f6", h="d11310f6", t="I'm sad!  It's Hallow's End, and I'm sick.  I'm going to miss out on trick-or-treating because I can't go out!", d=8.160, v="humanmalekid-male" },
	},
	[15350] = {
		{ f="15350-44b49612", h="44b49612", t="War is upon us, $N.  It's time for every member of the Horde to answer the call and join the fight against the cowardly Alliance.", d=9.750, v="orc-male-standard" },
	},
	[15351] = {
		{ f="15351-f54c92d6", h="f54c92d6", t="The war against the Horde has reached full tilt, $N.  This is a time of great need for the Alliance and it's quite necessary that all of us do our part to help.", d=9.280, v="dwarf-male-grim" },
	},
	[15353] = {
		{ f="15353-2de326ad", h="2de326ad", t="What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, Sergeant Hartman in Southshore needs help against the Forsaken and their Wickerman Festival.$B$BOne more thing - I've heard that a sick little boy at the orphanage in Stormwind is looking for someone to help him gather treats for the holiday.", d=22.550, v="npc-15390" },
		{ f="15353-9426c8a7", h="9426c8a7", t="Happy Hallow's End!  Do you like my mask?  Very scary!", d=5.120, v="npc-15390" },
	},
	[15354] = {
		{ f="15354-658164d5", h="658164d5", t="Happy Hallow's End!  How do you like my mask?  Very scary!", d=7.480, v="scourge-female-standard" },
		{ f="15354-ce69abe3", h="ce69abe3", t="What ISN'T there to do, you mean!$B$BEach of the innkeepers throughout the world are handing out trick-or-treat goodies, and many of the towns are decorated for the season!  Also, there is the Wickerman Festival just outside the Undercity during the evenings.$B$BOne more thing - I've heard that a sick little girl at the orphanage here in Orgrimmar is looking for someone to help her gather treats for the holiday... maybe you could help her out?", d=32.430, v="scourge-female-standard" },
	},
	[15378] = {
		{ f="15378-1452b0ef", h="1452b0ef", t="All will know of what has transpired here in this accursed temple, hero. It will be written about in history books - the tales told as legend from Azeroth to the far reaches of the Nether itself!", d=14.000, v="nightelf-female" },
		{ f="15378-bb91fa98", h="bb91fa98", t="Heroes of the Brood? C'Thun must be banished! We can assist you, mortal!", d=7.240, v="nightelf-female" },
	},
	[15379] = {
		{ f="15379-a0dfe062", h="a0dfe062", t="Even if you somehow managed to free us without defeating C'Thun, we would focus all of our powers to see the beast banished back to the hell from whence it came - AT ANY COST.", d=11.520, v="nightelf-male" },
		{ f="15379-f4658d72", h="f4658d72", t="Our freedom would have meant nothing if C'Thun had survived. You are truly a champion of prophecy.", d=8.200, v="nightelf-male" },
	},
	[15380] = {
		{ f="15380-eed43ea6", h="eed43ea6", t="I bear witness to a miracle that stands before me! In one thousand years of captivity, I have not seen a single LIVING specimen - other than those foul Qiraji and silithid - enter these chambers.", d=14.880, v="gnome-male" },
		{ f="15380-fea4b625", h="fea4b625", t="The world is indebted to you and your allies, $n.", d=5.520, v="gnome-male" },
	},
	[15395] = {
		{ f="15395-5ccd6ef4", h="5ccd6ef4", t="Only those who have proven themselves to not be hostile toward the Timbermaw may pass through the Hold without fear of being attacked.  Have you made an effort to earn our trust, outsider?", d=11.600, v="narrator", n={ [1]=11.080 } },
	},
	[15443] = {
		{ f="15443-59ade16b", h="59ade16b", t="Hail, $c.  The Ironforge Brigade is stationed here to keep an eye on Hive'Zora.  The Cenarion Circle druids have been monitoring silithid movement and they're anticipating something major in this area.", d=13.310, v="dwarf-female-guard" },
	},
	[15458] = {
		{ f="15458-6553a39c", h="6553a39c", t="We are united in cause, $r. An ancient evil threatens to extinguish all life on Kalimdor and consume the world with its depravity... Its hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are the first and the last lines of defense against the armies of C'Thun. If we do not rise up and strike at our enemy, our enemy will surely destroy us.$B$BThe war effort needs you!", d=23.350, v="dwarf-male-grim" },
		{ f="15458-f7b79f92", h="f7b79f92", t="Greetings, $r $c. I am Commander Stronghammer, the ambassador representing the Alliance here. If you have any questions concerning the status of Alliance collections for the Ahn'Qiraj war effort, $g lad : lass;, don't hesitate to ask.", d=14.640, v="dwarf-male-grim", g=true },
	},
	[15471] = {
		{ f="15471-8c763d9e", h="8c763d9e", t="<Andorov looks at you grimly.>$B$BIf it bleeds, we can kill it.", d=2.624, v="human-male", P={ { d=2.160, n=true }, { d=2.146 } }, nP={ [1]={ [1]=2.240 } } },
	},
	[15481] = {
		{ f="15481-1044c4b2", h="1044c4b2", t="If I did not know better I would think that you were mocking me, mortal; but yes, that is mostly correct. You may remain fully clothed.", d=8.369, v="human-male" },
		{ f="15481-2de945a0", h="2de945a0", t="Genius is often misunderstood, $r. Now, about the scepter shard... If you want that shard and do not wish to spend the next ten thousand years searching for it, you are going to have to listen very carefully.", d=12.585, v="human-male" },
		{ f="15481-3dd572f3", h="3dd572f3", t="As I was saying, I held onto that scepter shard for a good five-hundred years and it was nothing but trouble. It attracted all kinds of attention - the wrong kind of attention. I want to be left alone to my studies not babysit some would be hero's ticket to glory. So... I gave it to the fish.", d=19.538, v="human-male" },
		{ f="15481-47b09998", h="47b09998", t="Right then... You have to build an arcanite buoy and place it in the ocean. My minnow will be attracted to the magical emanations. When he gets near the buoy - BLAMO! It will explode in a glorious pulse of arcane energy, revealing the minnow's true form. Also, you may or may not incur the wrath of Neptulon. A 50/50 chance I would say.", d=24.608, v="human-male" },
		{ f="15481-4f953024", h="4f953024", t="You are going to love this story, $r. See, here is the thing. As soon as Malygos charged me with protecting the scepter shard, I knew I was in for an eternity of headache and pain.$B$BAll I want to do is study these magic rich shorelines and take in what artifacts might remain from the Sundering. You know, there was once a thriving Highborne civilization here! You don't have to tell me that there is going to be some solid magical items around here, $r. I can smell it!", d=32.183, v="human-male" },
		{ f="15481-63280ba1", h="63280ba1", t="You seek the scepter shard charged to the protection of the Blue Flight?$B$B<Azuregos appears to be smiling.>", d=4.482, v="human-male", P={ { d=4.696 }, { d=3.040, n=true } }, nP={ [1]={ [2]=2.960 } } },
		{ f="15481-64a796c9", h="64a796c9", t="Correct. You've been listening! This minnow is really quite a terrible creature of my own creation. When I am relaxing I like to think of the unlucky fishermen who have run into this minnow and been devoured whole. I bet they were quite surprised!$B$B<Azuregos laughs.>", d=16.124, v="human-male", P={ { d=16.262 }, { d=1.960, n=true } }, nP={ [1]={ [2]=1.520 } } },
		{ f="15481-72fa3b3d", h="72fa3b3d", t="Genius, I know... It will never be found; but, in case it is found, I gave the minnow some special powers.", d=8.946, v="human-male" },
		{ f="15481-76301f43", h="76301f43", t="Not just any fish, mortal. This fish was a minnow. A very special minnow.", d=5.394, v="human-male" },
		{ f="15481-793133f4", h="793133f4", t="Two words: Arcanite buoy.", d=2.738, v="human-male" },
		{ f="15481-81782f3f", h="81782f3f", t="Exactly!", d=0.796, v="human-male" },
		{ f="15481-8df30898", h="8df30898", t="My watch is eternal, mortal.", d=2.559, v="human-male" },
		{ f="15481-adefaa9c", h="adefaa9c", t="Of course I do not have the shard. That would be asinine. I walk amongst savages in this cursed land! I cannot take five steps without some crazed orc or human trying to thrust a sharp stick into my hide. At any given time you could very well be speaking to my ghostly spirit.$B$BAnyhow... I hid it.$B$BGo on... ask me where.", d=22.109, v="human-male" },
		{ f="15481-d1ddff8e", h="d1ddff8e", t="Take this ledger to an old acquaintance of mine in Tanaris. His name is Narain Soothfancy - terrible, terrible, psychic but an amazing engineer! He should be able to make sense of it all.$B$BNo need to thank me, $n. It's the least I could do.$B$BGood day!", d=17.561, v="human-male" },
		{ f="15481-e355908b", h="e355908b", t="Shouldn't you be saving the world?", d=2.219, v="human-male" },
		{ f="15481-f18837f6", h="f18837f6", t="I SAID GOOD DAY!", d=1.562, v="human-male" },
	},
	[15498] = {
		{ f="15498-6245db45", h="6245db45", t="Our steady progress in our fight against the Qiraji can be attributed to the diverse help we received from nearly every corner of Kalimdor.$B$BYou need more than just soldiers to fight a war, $n.  Many of the war's unsung heroes are the traders and craftsmen that keep our forces supplied with the resources they need.", d=25.110, v="nightelf-female-priestess" },
	},
	[15499] = {
		{ f="15499-acff8663", h="acff8663", t="I, like many others, came to aid my fellow druids when the war started.$B$BNow that the Gates of Ahn'Qiraj are open, I've realized that much work still remains to be done.  I've decided to stay in Silithus and do my best to help the cause, $n.  ", d=15.410, v="tauren-male-warrior" },
	},
	[15500] = {
		{ f="15500-c2196ead", h="c2196ead", t="This war's not over, it's only just begun!  We have brave men and women fighting our enemy inside Ahn'Qiraj day and night, $n.  It won't be long before the Qiraji city falls.", d=15.111, v="nightelf-male-warrior" },
	},
	[15502] = {
		{ f="15502-344f9b16", h="344f9b16", t="Step carefully mortal.  You tread where mightier beings have met their fate.", d=4.352, v="gnome-female-standard" },
		{ f="15502-7b6ea9c8", h="7b6ea9c8", t="With the Emperors slain, the magical protection blocking teleportation within the temple has been greatly weakened. If you desire, I am able to translocate you to the Emperors' lair.", d=9.020, v="gnome-female-standard" },
		{ f="15502-a049ea6a", h="a049ea6a", t="With Ouro slain the way is clear to the final chamber. I am able to transport you there, if you desire.", d=6.351, v="gnome-female-standard" },
	},
	[15503] = {
		{ f="15503-be190483", h="be190483", t="A thousand years ago, when the War of the Shifting Sands ended, three of our kin sacrificed themselves and held the Qiraji inside these halls while Anachronos and Staghelm sealed Ahn'Qiraj shut.$B$BEach of us vowed to look for Merithra, Arygos and Caelestrasz should the Scarab Wall ever fall.$B$BAnd fall it did... and so we came.", d=20.531, v="human-male-official" },
	},
	[15504] = {
		{ f="15504-5e97a3a3", h="5e97a3a3", t="An unspeakable horror dwells here, mortal.  C'Thun and his worshippers are not just an affront to nature, their existence presages destruction for Azeroth as we know it.$B$BMerithra sacrificed herself a thousand years ago along with Caelestrasz and Arygos because they knew this as well.  We're here because of our oath to return for them, but we're also here because C'Thun must be stopped!", d=29.190, v="nightelf-female" },
	},
	[15526] = {
		{ f="15526-990e45ad", h="990e45ad", t="I find the ocean floor to be very peaceful.", d=4.320, v="naga-female" },
		{ f="15526-d8b171e5", h="d8b171e5", t="It's so lovely to see you again, $n! I really can't thank you enough for delivering that message to my dear little gnome.$B$BWould you like to hear a song? It will make traveling in the rough seas much easier!", d=15.360, v="naga-female" },
	},
	[15539] = {
		{ f="15539-e215b04d", h="e215b04d", t="We stand together with the Alliance, $r. An evil, so old that the world has forgotten it, seeks to engulf us all; first on Kalimdor and then the rest of Azeroth. It is driven by a hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are all that stand in the way of C'Thun's armies. We will strike first and bring down the forces of Ahn'Qiraj. Let all of Azeroth quake at the combined might of the Horde and Alliance.$B$BThe war effort needs you!", d=42.990, v="orc-male-guard" },
		{ f="15539-fd978c35", h="fd978c35", t="Lok'tar, $r. I am General Zog, ambassador of the Horde. I am here to keep you apprised of the progress that the mighty Horde is making in their efforts toward the Ahn'Qiraj War. What is it that you want to know?", d=19.480, v="orc-male-guard" },
	},
	[15540] = {
		{ f="15540-03e4a682", h="03e4a682", t="Now that the war is in full swing, we've had no shortage of able-bodied combatants from the Horde and Alliance.$B$BIf only we could keep them off of each other's throats...", d=11.111, v="nightelf-male-warrior" },
	},
	[15549] = {
		{ f="15549-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=8.000, v="dwarf-male" },
		{ f="15549-9b3759a6", h="9b3759a6", t="Elder Ironband lives in Blackchar Cave in Searing Gorge.", d=4.360, v="dwarf-male" },
	},
	[15556] = {
		{ f="15556-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=7.200, v="dwarf-male" },
		{ f="15556-6a6a943c", h="6a6a943c", t="Elder Mistwalker enjoys watching the struggles at the Maul in Feralas.", d=4.400, v="dwarf-male" },
		{ f="15556-fdb3761a", h="fdb3761a", t="You'll find Elder Grimtotem at the Lariss Pavilion in Feralas.", d=4.960, v="dwarf-male" },
	},
	[15557] = {
		{ f="15557-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=6.800, v="dwarf-male" },
		{ f="15557-7bdbbe9e", h="7bdbbe9e", t="Winterhoof? I hear he's living it up in Booty Bay.", d=3.320, v="dwarf-male" },
		{ f="15557-b45656c0", h="b45656c0", t="Elder Stormbrow is most likely at the village of Goldshire in Elwynn Forest.", d=5.200, v="dwarf-male" },
		{ f="15557-b9715b86", h="b9715b86", t="Elder Hammershout can be found within the walls of Stormwind.", d=4.040, v="dwarf-male" },
		{ f="15557-fe6e909f", h="fe6e909f", t="Elder Dawnstrider can be found at Flame Crest on the Burning Steppes.", d=5.040, v="dwarf-male" },
	},
	[15558] = {
		{ f="15558-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=7.720, v="dwarf-male" },
		{ f="15558-2e59f6dd", h="2e59f6dd", t="Elder Goldwell spends his time in the village of Kharanos in Dun Morogh.", d=5.720, v="dwarf-male" },
		{ f="15558-9b3759a6", h="9b3759a6", t="Elder Ironband lives in Blackchar Cave in Searing Gorge.", d=4.200, v="dwarf-male" },
	},
	[15559] = {
		{ f="15559-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=7.400, v="dwarf-male" },
		{ f="15559-e3aef225", h="e3aef225", t="Elder Moonstrike can be found in the Scholomance in the Western Plaguelands.", d=5.080, v="dwarf-male" },
	},
	[15560] = {
		{ f="15560-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=9.320, v="dwarf-male" },
		{ f="15560-9b3759a6", h="9b3759a6", t="Elder Ironband lives in Blackchar Cave in Searing Gorge.", d=4.560, v="dwarf-male" },
	},
	[15561] = {
		{ f="15561-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=7.720, v="dwarf-male" },
