		{ f="15588-bd1147be", h="bd1147be", t="Last I heard, Elder Runetotem was traveling to Razor Hill in Durotar.", d=5.240, v="tauren-male" },
		{ f="15588-bf771adc", h="bf771adc", t="Elder Morningdew has taken to watching the commotion at the Mirage Raceway in Thousand Needles.", d=6.680, v="tauren-male" },
		{ f="15588-c2871537", h="c2871537", t="In days long past, we lived for the hunt.  We hunted for glory, for honor...$B$BIs it so different now?", d=9.040, v="tauren-male" },
	},
