	[15609] = {
		{ f="15609-73cfa427", h="73cfa427", t="Soon we shall rid Azeroth of the silithids' abominable presence.  Their potential for destruction is much greater than what you've seen firsthand, $n.  Greater, darker powers are behind their activities.", d=15.798, v="nightelf-male-warrior" },
	},
	[15610] = {
		{ f="15610-1ee324c2", h="1ee324c2", t="It takes a bit of practice to be this close to the silithid and go unnoticed.  I don't recommend trying it if you can avoid it.  ", d=7.394, v="nightelf-female-standard" },
	},
	[15611] = {
		{ f="15611-8b6bd0e5", h="8b6bd0e5", t="Don't get me wrong, I'd rather not be in a tunnel filled with silithid day in and day out, but if hiding here and watching these creatures' movements is going to help us win the war then I'll do it for as long as it takes.", d=14.748, v="nightelf-female-standard" },
	},
	[15613] = {
		{ f="15613-48665ca1", h="48665ca1", t="As deadly as the silithid seem, they are but tame creatures compared to their Qiraji overlords.", d=6.270, v="tauren-male-warrior" },
	},
	[15634] = {
		{ f="15634-a8c94e68", h="a8c94e68", t="The High Priestess could not leave Darnassus. Fandral is in a very foul mood.", d=8.040, v="nightelf-female" },
		{ f="15634-b3d4c019", h="b3d4c019", t="Tyrande sends her prayers. The Mother Moon blesses us all.", d=4.960, v="nightelf-female" },
		{ f="15634-c159e43e", h="c159e43e", t="Elune be with you, $c.", d=3.000, v="nightelf-female" },
	},
	[15664] = {
		{ f="15664-62f5babf", h="62f5babf", t="Around this reindeer's neck is a tag with the Smokywood Pastures logo on it and a name - \"Metzen\".$B$BMetzen looks at you with sad, forlorn eyes.  It is almost as if the reindeer has been immobilized by some unseen force.", d=15.091, v="human-male" },
		{ f="15664-e17e388b", h="e17e388b", t="Metzen's eyes light up with reindeer joy as you sprinkle the dust on him.  He shakes his antlers at you and breathes out a heavy sigh of what sounds like relief.$B$BAround you, magical energy begins to swell.  It would seem that something's about to happen!", d=15.467, v="human-male" },
	},
	[15694] = {
		{ f="15694-202eadd0", h="202eadd0", t="Be sure to stick around for the next firework show!  Starting at 6PM, they're every hour on the hour!", d=7.590, v="human-male-standard", s={ ["f"]=5.791 } },
		{ f="15694-404f53f7", h="404f53f7", t="Well met, friend!", d=1.515, v="human-male-standard", s={ ["f"]=1.210 } },
		{ f="15694-64e75af3", h="64e75af3", t="I sure could use a kiss about now.  Know where I can find one?", d=4.530, v="human-male-standard", s={ ["f"]=3.725 } },
		{ f="15694-7c387ea3", h="7c387ea3", t="I don't know what they put in those kegs, but it goes down like honey!", d=5.014, v="human-male-standard", s={ ["f"]=3.245 } },
		{ f="15694-9cde2b85", h="9cde2b85", t="After the firework show, they'll put out goblets so we can raise a toast!", d=4.892, v="human-male-standard", s={ ["f"]=3.867 } },
	},
	[15700] = {
		{ f="15700-b934733d", h="b934733d", t="Throm'ka, Horde $C, stand proud! I am Warlord Gorchuk, commander of the Horde's war effort. There are trying times ahead of us, but we shall prevail, as always.$B$BIf you have questions, you should ask them.", d=17.240, v="orc-male-shady" },
		{ f="15700-e215b04d", h="e215b04d", t="We stand together with the Alliance, $r. An evil, so old that the world has forgotten it, seeks to engulf us all; first on Kalimdor and then the rest of Azeroth. It is driven by a hatred of all things born of the great Shapers: The eternal Titans.$B$BWe are all that stand in the way of C'Thun's armies. We will strike first and bring down the forces of Ahn'Qiraj. Let all of Azeroth quake at the combined might of the Horde and Alliance.$B$BThe war effort needs you!", d=40.350, v="orc-male-shady" },
	},
	[15701] = {
		{ f="15701-8c1d57d6", h="8c1d57d6", t="Greetings, $c. I am Field Marshal Snowfall, commander of the war effort here. We've a hard road to plow ahead of us, $g lad : lass;, so if you can help out, please do so. And feel free to ask questions.", d=13.640, v="dwarf-male-grim", g=true },
	},
	[15702] = {
		{ f="15702-526f4069", h="526f4069", t="Hail, $c. I trust you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Horde and Alliance to prepare for the impending war against the Silithid and their masters in Ahn'Qiraj. In Orgrimmar's Valley of Spirits, we are collecting a vast number of goods to create war materiel, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about helping out?", d=34.969, v="tauren-female-official" },
	},
	[15703] = {
		{ f="15703-526f4069", h="526f4069", t="Hail, $c. I trust you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Horde and Alliance to prepare for the impending war against the Silithid and their masters in Ahn'Qiraj. In Orgrimmar's Valley of Spirits, we are collecting a vast number of goods to create war materiel, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about helping out?", d=34.310, v="scourge-male-warrior" },
	},
	[15704] = {
		{ f="15704-526f4069", h="526f4069", t="Hail, $c. I trust you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Horde and Alliance to prepare for the impending war against the Silithid and their masters in Ahn'Qiraj. In Orgrimmar's Valley of Spirits, we are collecting a vast number of goods to create war materiel, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about helping out?", d=47.870, v="troll-female-standard" },
	},
	[15707] = {
		{ f="15707-02c09d87", h="02c09d87", t="Well met, $c. I hope you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Alliance and Horde to prepare for the upcoming war against the Silithid and their masters in Ahn'Qiraj. In the Military Ward of Ironforge, we are collecting all manner of goods to create our war materiel from, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about pitching in?", d=26.678, v="gnome-male-standard" },
	},
	[15708] = {
		{ f="15708-02c09d87", h="02c09d87", t="Well met, $c. I hope you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Alliance and Horde to prepare for the upcoming war against the Silithid and their masters in Ahn'Qiraj. In the Military Ward of Ironforge, we are collecting all manner of goods to create our war materiel from, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about pitching in?", d=36.830, v="human-female-official" },
	},
	[15709] = {
		{ f="15709-02c09d87", h="02c09d87", t="Well met, $c. I hope you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Alliance and Horde to prepare for the upcoming war against the Silithid and their masters in Ahn'Qiraj. In the Military Ward of Ironforge, we are collecting all manner of goods to create our war materiel from, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about pitching in?", d=37.525, v="nightelf-female-standard" },
	},
	[15719] = {
		{ f="15719-162da20b", h="162da20b", t="The kegs are filled with strong brew!  Drink, friend, and celebrate!", d=5.119, v="tauren-male-warrior", s={ ["f"]=6.080 } },
		{ f="15719-3a83fa5b", h="3a83fa5b", t="Hail, $c!  Welcome to the celebration!", d=3.559, v="tauren-male-warrior", s={ ["f"]=5.520 } },
		{ f="15719-6326d098", h="6326d098", t="Starting at 6PM, they will show fireworks from the highest bluff!", d=4.223, v="tauren-male-warrior", s={ ["f"]=5.640 } },
		{ f="15719-64e75af3", h="64e75af3", t="I sure could use a kiss about now.  Know where I can find one?", d=4.117, v="tauren-male-warrior", s={ ["f"]=4.400 } },
		{ f="15719-e2e69600", h="e2e69600", t="I heard that, after the fireworks show, goblets will be brought to the tables.  Fine toasts we shall raise!", d=7.095, v="tauren-male-warrior", s={ ["f"]=8.320 } },
	},
	[15722] = {
		{ f="15722-0630c65b", h="0630c65b", t="Greetings, $c. I am Leoren, stable master of Cenarion Hold.", d=8.120, v="nightelf-male-standard" },
	},
	[15723] = {
		{ f="15723-291d6c4d", h="291d6c4d", t="They're going to show fireworks all night long.  From 6PM until dawn, the sky will blaze over Booty Bay!", d=6.343, v="goblin-male-zany", s={ ["f"]=7.360 } },
		{ f="15723-3deb0a18", h="3deb0a18", t="Wow!  These kegs are filled with powerful stuff!  They lift me right out of my boots!", d=6.242, v="goblin-male-zany", s={ ["f"]=7.440 } },
		{ f="15723-85e374c4", h="85e374c4", t="Stick around after the firework show is over.  Find a goblet and raise it to toast your hardy friends!", d=6.233, v="goblin-male-zany", s={ ["f"]=6.440 } },
		{ f="15723-a3825ffb", h="a3825ffb", t="All right!  Party time!", d=2.137, v="goblin-male-zany", s={ ["f"]=2.200 } },
	},
	[15731] = {
		{ f="15731-6050800e", h="6050800e", t="Greetings, $c - I'm a Commendation Officer acting on behalf of Darnassus.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Darnassus for your duty and service. ", d=31.110, v="nightelf-male-standard", s={ ["f"]=33.830 } },
	},
	[15732] = {
		{ f="15732-9156c82b", h="9156c82b", t="New this year: the PX-238 Winter Wondervolt.  Step on up and don't be shy!$B$BAnd sign these forms before you try it, we're still working a few bugs out of this thing...", d=11.509, v="goblin-male-zany" },
	},
