	[15797] = {
		{ f="15797-46fe482a", h="46fe482a", t="The secrets behind the power of the Colossus could lead to all sorts of innovations in science!", d=5.024, v="human-female" },
	},
	[15798] = {
		{ f="15798-251db01a", h="251db01a", t="Studying and understanding the Colossus will give us a needed advantage over the Qiraji.", d=6.200, v="gnome-male" },
	},
	[15799] = {
		{ f="15799-cea6815e", h="cea6815e", t="We've gotta find out what the Qiraji are feeding those monsters! Look at the size of 'em!", d=5.440, v="dwarf-male" },
	},
	[15864] = {
		{ f="15864-71fc9757", h="71fc9757", t="Omen sleeps in the depths of Lake Elune'ara, but may be summoned at the southeast banks near the Stormrage Barrow Dens.  There, you will find special cluster launchers...$B$BUse your rockets in the launchers and Omen's minions will come.  Fire more rockets, nearly three dozen, or fire Elune's candles at his minions, and soon he will awaken.", d=25.190, v="nightelf-male-official" },
		{ f="15864-f4529c81", h="f4529c81", t="To honor your elders is to honor your culture and your people, $c.  For this, the Coins of Ancestry serve as a tangible means to recognize those who choose to follow a venerable path of respect.$B$BDuring this Lunar Festival, you may have the opportunity to honor many elders.  As you do so, you will acquire the Coins of Ancestry.  Bring me these coins, and I will reward your diligence with a selection of unique items. ", d=39.350, v="nightelf-male-official" },
	},
	[15871] = {
		{ f="15871-0f08bcf5", h="0f08bcf5", t="Now is the time when the year is new and the moon shines bright.$B$BIt is our time... when the ancients awake.", d=6.920, v="dwarf-male" },
		{ f="15871-2e59f6dd", h="2e59f6dd", t="Elder Goldwell spends his time in the village of Kharanos in Dun Morogh.", d=4.880, v="dwarf-male" },
		{ f="15871-9b3759a6", h="9b3759a6", t="Elder Ironband lives in Blackchar Cave in Searing Gorge.", d=4.800, v="dwarf-male" },
		{ f="15871-b9715b86", h="b9715b86", t="Elder Hammershout can be found within the walls of Stormwind.", d=3.480, v="dwarf-male" },
		{ f="15871-fedfff5f", h="fedfff5f", t="Elder Bladeswift wanders the paths of Darnassus atop Teldrassil.", d=4.680, v="dwarf-male" },
	},
	[15895] = {
		{ f="15895-69fd6f0c", h="69fd6f0c", t="Greetings, $n.  We've travelled from Moonglade to spread the spirit of the Lunar Festival far and wide.$B$BWon't you join us in our celebration?", d=12.280, v="tauren-female-standard" },
	},
	[15900] = {
		{ f="15900-69fd6f0c", h="69fd6f0c", t="Greetings, $n.  We've travelled from Moonglade to spread the spirit of the Lunar Festival far and wide.$B$BWon't you join us in our celebration?", d=11.071, v="nightelf-female-standard" },
	},
	[15903] = {
		{ f="15903-6dc39b90", h="6dc39b90", t="\"Great job collecting resources for the war,\" they said, \"Have a promotion,\" they said.  What they really meant is \"You're stationed outside a bughive in Silithus with a bunch of sweaty dwarves, Carnes!\"$B$BThanks for the promotion, Captain!", d=16.808, v="human-male-warrior" },
	},
	[15905] = {
		{ f="15905-202eadd0", h="202eadd0", t="Be sure to stick around for the next firework show!  Starting at 6PM, they're every hour on the hour!", d=8.000, v="nightelf-male-standard", s={ ["f"]=9.520 } },
		{ f="15905-404f53f7", h="404f53f7", t="Well met, friend!", d=2.800, v="nightelf-male-standard", s={ ["f"]=2.240 } },
		{ f="15905-64e75af3", h="64e75af3", t="I sure could use a kiss about now.  Know where I can find one?", d=5.800, v="nightelf-male-standard", s={ ["f"]=5.000 } },
		{ f="15905-7c387ea3", h="7c387ea3", t="I don't know what they put in those kegs, but it goes down like honey!", d=5.920, v="nightelf-male-standard", s={ ["f"]=6.040 } },
		{ f="15905-9cde2b85", h="9cde2b85", t="After the firework show, they'll put out goblets so we can raise a toast!", d=5.040, v="nightelf-male-standard", s={ ["f"]=5.560 } },
	},
	[15906] = {
		{ f="15906-202eadd0", h="202eadd0", t="Be sure to stick around for the next firework show!  Starting at 6PM, they're every hour on the hour!", d=6.440, v="dwarf-male-standard", s={ ["f"]=7.800 } },
