	},
	[15907] = {
		{ f="15907-162da20b", h="162da20b", t="The kegs are filled with strong brew!  Drink, friend, and celebrate!", d=7.120, v="scourge-male-standard", s={ ["f"]=6.600 } },
		{ f="15907-3a83fa5b", h="3a83fa5b", t="Hail, $c!  Welcome to the celebration!", d=4.520, v="scourge-male-standard", s={ ["f"]=4.560 } },
		{ f="15907-6326d098", h="6326d098", t="Starting at 6PM, they will show fireworks from the highest bluff!", d=5.640, v="scourge-male-standard", s={ ["f"]=6.920 } },
		{ f="15907-64e75af3", h="64e75af3", t="I sure could use a kiss about now.  Know where I can find one?", d=6.120, v="scourge-male-standard", s={ ["f"]=6.200 } },
		{ f="15907-e2e69600", h="e2e69600", t="I heard that, after the fireworks show, goblets will be brought to the tables.  Fine toasts we shall raise!", d=9.600, v="scourge-male-standard", s={ ["f"]=10.600 } },
	},
	[15908] = {
		{ f="15908-162da20b", h="162da20b", t="The kegs are filled with strong brew!  Drink, friend, and celebrate!", d=5.500, v="orc-male-standard", s={ ["f"]=5.400 } },
