	[267677] = {
		{ f="267677-d741064d", h="d741064d", t="<The horse watches you calmly and swishes its long tail to shoo away some flies.>", d=5.000, v="narrator", n={ [1]=6.720 } },
	},
	[267683] = {
		{ f="267683-b4b21be5", h="b4b21be5", t="<The tag on the mechanostrider reads:    Crimson-Blastdasher XL 300. Now with extra terrain grips and a sleek new color!>", d=9.120, v="narrator" },
	},
	[267687] = {
		{ f="267687-14707f63", h="14707f63", t="<The tag on the mechanostrider reads:    Electric Blue Mecha-turbo Runner 5000, now with extra movement tracking and terrain damping for a smooth ride!>", d=9.840, v="narrator", n={ [1]=13.080 } },
	},
	[267688] = {
		{ f="267688-ad18a6ee", h="ad18a6ee", t="<The tag on the mechanostrider reads:    The Chromo-Classic Mechanostrider! Now with hydraulic equilibrium enhancers, and mithril tailpipe dampers.>", d=10.560, v="narrator", n={ [1]=10.440 } },
	},
	[267806] = {
		{ f="267806-6f7f9937", h="6f7f9937", t="Psst! Hey, you! Yeah, you! You caught one of those rare tournament fish, didn't you? Don't be shy, I can smell it from here!    Listen, I know what it's like to reel in your last line, thinking you're about to claim your prize... only to catch the most amazing, gorgeous, WORTHLESS lunker known to goblin kind! Yeah, been there, lost my shot at the title three weeks in a row to that! Learned pretty darn quick they taste better than the tastyfish, though.    Now, I just participate for fun. That means I've got a few tastyfish on hand... and I am willing to trade for the vastly superior rare fish.    Seems like a win-win for you, huh?", d=27.100, v="goblin-male" },
	},
	[268047] = {
		{ f="268047-53fff4bc", h="53fff4bc", t="I am sorry, $c, but you are not experienced enough yet to enter Darkspear Islands.", d=5.901, v="human-female" },
		{ f="268047-c401ba80", h="c401ba80", t="$N, the Stormpike Guard is in need of your aid in the battle against the Frostwolf Clan in Alterac Valley, now more than ever.  The opportunities for honor and repute are greater than ever as well! Will you join the battle?", d=12.844, v="human-female" },
	},
	[268048] = {
		{ f="268048-53fff4bc", h="53fff4bc", t="I am sorry, $c, but you are not experienced enough yet to enter Darkspear Islands.", d=7.560, v="troll-female", s={ ["m"]=8.800 } },
		{ f="268048-e1c9a6bd", h="e1c9a6bd", t="Hail, $c.  There is a great need and even greater honor and renown to be had in Alterac Valley at this time. Will you join our fight against the Stormpike Guard?", d=12.360, v="troll-female" },
		{ f="268048-fb906211", h="fb906211", t="$C, we could use more help out at Darkspear Islands against the Theramore Expeditionary Force. Are you willing to join in?", d=8.760, v="troll-female" },
	},
	[268511] = {
		{ f="268511-ee845bad", h="ee845bad", t="Harbor work is open to everyone, but your personal safety is your own responsibility.", d=6.300, v="human-male" },
	},
	[268568] = {
		{ f="268568-f87f742d", h="f87f742d", t="Literacy should be celebrated and shared.", d=3.323, v="human-male" },
	},
	[268679] = {
		{ f="268679-72aa6da2", h="72aa6da2", t="<The Braizer of Eternal Flame awaits your offering.>", d=3.960, v="narrator", n={ [1]=4.200 } },
	},
	[268925] = {
		{ f="268925-17da1992", h="17da1992", t="The night elf is motionless, with multiple wounds and discoloration emblematic of suffering from poison.", d=8.120, v="nightelf-female" },
	},
	[269152] = {
		{ f="269152-3bad330d", h="3bad330d", t="Greetings, $c. I am happy Anshe has guided you to me today. I would be proud to sell you one of our finest kodos once you have trained with Kar.    The kodo is a noble beast, but is prone to its own behaviors that make it different than most steeds. Once you learn from Kar you will have no issues traversing the world with one at your side.", d=26.310, v="tauren-female" },
		{ f="269152-644ccfaa", h="644ccfaa", t="You are not known to my people.  A kodo is a mighty steed, and it is the product of love and care by my people; such is not given onto strangers.  Until the elders of Thunder Bluff consider you to be exalted, I cannot offer you the sale of a kodo.", d=19.320, v="tauren-female" },
	},
	[269153] = {
		{ f="269153-dab85bcc", h="dab85bcc", t="<The mountaineer clearly fought bravely before meeting her end at the weapons of the troggs.>", P={ { d=5.560, n=true } }, nP={ [1]={ [1]=6.160 } } },
	},
	[270459] = {
		{ f="270459-35e7520b", h="35e7520b", t="I was invited to visit Dalaran on behalf of the Cenarion Circle. I find this place equal parts wondrous... and unsettling.    As for you, young $C--If you have not yet done so, seek out Sheldras Moontree in Stormwind. He will teach you to reach the Cenarion Circle enclave at Moonglade.", d=24.840, v="nightelf-female" },
		{ f="270459-d7d8dd3e", h="d7d8dd3e", t="This city is a wondrous place, but I also find it unsettling. Concentrating as much magic in one place carries many dangers, as my own people well know.", d=13.680, v="nightelf-female" },
	},
	[270513] = {
		{ f="270513-e6b98502", h="e6b98502", t="Greetings, $c.    I can show you how to weave magic about yourself to change the appearance of your equipment, if you so desire. Do you wish to utilize my services?", d=10.280, v="nightelf-male" },
	},
	[270581] = {
		{ f="270581-e6b98502", h="e6b98502", t="Greetings, $c.    I can show you how to weave magic about yourself to change the appearance of your equipment, if you so desire. Do you wish to utilize my services?", d=14.560, v="nightelf-female" },
	},
	[270582] = {
		{ f="270582-e6b98502", h="e6b98502", t="Greetings, $c.    I can show you how to weave magic about yourself to change the appearance of your equipment, if you so desire. Do you wish to utilize my services?", d=13.160, v="troll-female" },
	},
	[270637] = {
		{ f="270637-3e0b4d08", h="3e0b4d08", t="So many Wildhammer lives lost... whole families erased...", d=5.080, v="dwarf-male" },
	},
	[271465] = {
		{ f="271465-92b9fbbb", h="92b9fbbb", t="Greetings, $c. Are you in need of arms?    I was trained by Antarion of Ban'aethal, using secrets handed down from the ancient master magesmiths of Kalimdor.    You'll find no finer weapons on Zephras Isle than mine.", d=13.920, v="skyborne-male" },
	},
	[271481] = {
		{ f="271481-fe153cb9", h="fe153cb9", t="Free me!", d=0.560, v="narrator", n={ [1]=1.360 } },
	},
	[271546] = {
		{ f="271546-7dbe534f", h="7dbe534f", t="Lookin' fer the courier? Just flew off like a wee bird.    Can't say I blame the poor sod. These wendigos are nasty business.", d=8.840, v="dwarf-female" },
	},
	[271613] = {
		{ f="271613-0980e046", h="0980e046", t="<The body looks incomplete and awaiting a head.>", d=3.600, v="narrator", n={ [1]=3.920 } },
		{ f="271613-cd85d6bf", h="cd85d6bf", t="<Othmar's head looks at you from nearby.>    What... You... Want...    Filthy... $r...", d=5.600, v="narrator", n={ [1]=8.000 } },
		{ f="271613-f87677dc", h="f87677dc", t="<The body looks incomplete and appears to be awaiting a head.>", d=3.840, v="narrator", n={ [1]=4.560 } },
	},
	[272045] = {
		{ f="272045-5a3e1b84", h="5a3e1b84", t="Why are you looking at me like that? Do you expect me to shoot bolts of lightning at you, or threaten you with the wrath of the Windlord?    It's fair enough if you do. However, not all of us are quite so... zealous.", d=12.880, v="skyborne-male" },
		{ f="272045-d5d1dc84", h="d5d1dc84", t="Tailor, by trade.     Here, stranger, I'll tell you what. Bring me any spare windstones you come across and I'll share my wares with you. I've got quite the stockpile of Al'Aketh garments here. Say what you will about the insanity of the cult, you've got to admit, they have some sense of style.    Or rather, I do, considering I designed most of their attire.", d=22.950, v="skyborne-male" },
		{ f="272045-fac7c2e1", h="fac7c2e1", t="Not much story to tell. I lived in Falaath Village and when the cult moved in, I saw the winds turning. I shaved my head, donned the grey robes, and said the words they wanted to hear.     Now I'm just trying to survive. Mostly I keep my head down and ply my trade for that crackpot, Lorthuna.", d=19.640, v="skyborne-male" },
	},
	[272101] = {
		{ f="272101-5d6f0b28", h="5d6f0b28", t="What are you looking for?", d=2.360, v="scourge-female" },
		{ f="272101-e7cb64ec", h="e7cb64ec", t="There's a Bat Handler inside the Undercity.  Head south down the road out of Brill, then west at the T-intersection.  The Ruins of Lordaeron will be on your left.  Go into them and then down into the Undercity.  You can ask an Undercity Guardian there for further assistance.", d=21.640, v="scourge-female" },
		{ f="272101-effe3a80", h="effe3a80", t="What could you possibly need a bank for?  Very well, you'll need to go through the Ruins of Lordaeron to the south of Brill.  In the back are a set of elevators leading down into the Undercity.  When you get there stop any of those lumbering Abominations they like to call an Undercity Guardian and ask it for better directions.", d=23.950, v="scourge-female" },
	},
	[272450] = {
		{ f="272450-7118ac39", h="7118ac39", t="My darlings... my darlings...", d=2.308, v="human-female" },
	},
	[272526] = {
		{ f="272526-bf500b92", h="bf500b92", t="Yes, I am the renowned trader who magnanimously fed the uh, starving... children...? ...of the Undercity during the recent war with the Scourge. Yes, I am the visionary businessgob and logistical genius who single-handedly armed the resistance and allowed our Dark Lady to found her nation of smelly corpses... um, I mean, \"Forsaken.\"    Yep, I'm him. Glix Xizzix. I'd be happy to sign an autograph. For a small fee, of course.    What am I doing here running a barbershop, you ask? Well I got one word for you, bub--diversification. You've got to keep your revenue streams diversified!", d=25.380, v="goblin-male" },
	},
	[272633] = {
		{ f="272633-4a619efb", h="4a619efb", t="The ebb and flow of magic has been disrupted, of late. I hear that even the mages of Dalaran are perplexed. Is this disturbance arcane in nature, or are the elements themselves in unrest?", d=12.200, v="tauren-female" },
	},
	[274757] = {
		{ f="274757-21ab523d", h="21ab523d", t="Here in Darnassus you will find skilled trainers who have perfected the skills of their chosen class through ages of training and dedication.  I will guide you to one who can become your mentor, you have but to name your chosen path.", d=17.760, v="nightelf-female" },
		{ f="274757-4979e51a", h="4979e51a", t="Ever vigilant in their protection of the natural world, the druids are guided by Arch $C Fandral Staghelm who resides in the Cenarion Enclave.  You will find him and the other $C trainers in the northern section of Darnassus.", d=16.880, v="nightelf-female" },
		{ f="274757-a0975d94", h="a0975d94", t="I received the majority of my weapons training from Ilyenia Moonfire in the Warrior's Terrace.  You would do well to seek her out if you desire to learn the use of a new weapon.  ", d=14.880, v="nightelf-female" },
		{ f="274757-ce424d00", h="ce424d00", t="Of all the wondrous places within Darnassus, which would you have me direct you to?", d=7.160, v="nightelf-female" },
		{ f="274757-d3a25a4e", h="d3a25a4e", t="Alegorn is a masterful chef who has had centuries with which to perfect his cooking.  You should consider yourself blessed should he decide to teach you.  If you believe you are worthy, you can find him in the Craftsmen's Terrace.", d=17.280, v="nightelf-female" },
		{ f="274757-e07232c6", h="e07232c6", t="Here among the craftsmen of Darnassus, there is a millenium of knowledge for the benefit of your chosen craft.  Now tell me, which craft do you find the most intriguing?", d=13.440, v="nightelf-female" },
	},
	[274781] = {
		{ f="274781-034389cd", h="034389cd", t="Brandur Ironhammer would be the one ye'd want to see.  Ye can find him in the Hall of Mysteries north of the gates of Ironforge.", d=7.160, v="dwarf-male", s={ ["f"]=8.360 } },
		{ f="274781-1c500d9f", h="1c500d9f", t="Skinning?  The only thing ye look like ye could skin is yer own knee!  Ha!  Now why don't you go see Balthus Stoneflayer so he can teach you how to properly skin some animals.  You'll find him in Finespindle's Leather Goods on the northern side of The Great Forge.", d=15.280, v="dwarf-male", s={ ["f"]=16.360 } },
		{ f="274781-3804779b", h="3804779b", t="Which class trainer might ye be looking for?", d=2.640, v="dwarf-male", s={ ["f"]=3.160 } },
		{ f="274781-46dd318e", h="46dd318e", t="Do we have Mining trainers here?  Where do ye think ye are!?      Why you'll find one o' the best miners in all Dun Morogh at the Deepmountain Mining Guild on the northern side of The Great Forge.  There, Geofram Bouldertoe will show ye the true art of mining.", d=14.320, v="dwarf-male", s={ ["f"]=16.240 } },
		{ f="274781-6e49a2d4", h="6e49a2d4", t="The Inn?  Ah, ye looking to toss back some of the best ales Ironforge has to offer?  The Stonefire Tavern is where ye'll want to go.    Ye'll find it just to the left of the entrance to Ironforge if ye be coming, or to the right if ye be going.", d=14.440, v="dwarf-male", s={ ["f"]=16.040 } },
		{ f="274781-8f560eff", h="8f560eff", t="Which profession trainer would ye be looking for?", d=2.280, v="dwarf-male", s={ ["f"]=4.000 } },
		{ f="274781-ab5dd850", h="ab5dd850", t="Between Bixi and Buliwyf, there ain't many weapons they haven't had the pleasure of slashing or smashing an orc with.  You can find them hanging out at the Timberline Arms weapon shop if ye need some training.", d=9.960, v="dwarf-male", s={ ["f"]=11.200 } },
		{ f="274781-ac68ec99", h="ac68ec99", t="Yer looking to learn how to use a new weapon are ye?  Well, ye should be talking to Bixi or Buliwyf over at the Timberline Arms weapon shop then lad.  They know their weapons from axes to... uh... zweihanders.", d=12.160, v="dwarf-male", s={ ["f"]=15.680 } },
		{ f="274781-ce6a7b9d", h="ce6a7b9d", t="What do ye need directions to?", d=2.560, v="dwarf-male", s={ ["f"]=2.640 } },
		{ f="274781-f3452b83", h="f3452b83", t="Where better to look for a dark and brooding lot, than the dark section of Ironforge, aptly named The Forlorn Cavern.  Thistleheart is sure to be found there, likely summoning some manner of vile creature to do his bidding.", d=13.600, v="dwarf-male", s={ ["f"]=14.440 } },
	},
	[274942] = {
		{ f="274942-7db6413a", h="7db6413a", t="Used to have a shop in Strahnbrad. Good little place. Had customers. Had walls. Had a roof.", d=6.375, v="human-male" },
	},
	[275210] = {
		{ f="275210-9e7a54e0", h="9e7a54e0", t="I dreamed of joining the Kirin Tor ever since I was a little boy. But this is not what I had in mind!", d=6.773, v="human-male" },
	},
	[275212] = {
		{ f="275212-8443298b", h="8443298b", t="I'm afraid we're not up and running just yet. Please do check back later!", d=3.972, v="human-female" },
	},
	[275243] = {
		{ f="275243-a3886d45", h="a3886d45", t="Apologies, sir. The bank isn't open yet. Please come back later, if you don't mind.", d=5.675, v="human-male" },
		{ f="275243-c50a1c3f", h="c50a1c3f", t="No matter how many times I tell them the bank isn't open yet, they continue to wait and complain. It's almost like that's what they came here to do.", d=10.803, v="human-male" },
	},
	[275269] = {
		{ f="275269-8059976c", h="8059976c", t="The skycutter that arrives here will take you right to Dalaran City.", d=4.960, v="skyborne-male" },
		{ f="275269-d9943d35", h="d9943d35", t="Board here for transport to Dalaran City, nestled in the Alterac Mountains.", d=5.440, v="skyborne-male" },
	},
	[275270] = {
		{ f="275270-56f11671", h="56f11671", t="This skycutter will take you right to the wondrous open plains of Mulgore.", d=4.920, v="skyborne-male" },
		{ f="275270-fb00a823", h="fb00a823", t="All travelers bound for Mulgore should depart here.", d=3.520, v="skyborne-male" },
	},
	[275350] = {
		{ f="275350-f33c9b0b", h="f33c9b0b", t="Sorry, $c. I have nothing to teach you. I'm still learning myself!", d=5.163, v="human-male" },
	},
	[275491] = {
		{ f="275491-0edd6da8", h="0edd6da8", t="Greetings, citizen. How may I help you today?", d=3.926, v="human-male" },
		{ f="275491-9fd8120c", h="9fd8120c", t="Ah yes, he mentioned that an agent of the High Order would be arriving in Stormwind soon. He asked me to draft instructions for you.    <Randal hands you a neatly sealed note.>    This should give you all the information you need. You are in for quite the journey, $N. I wish you luck on behalf of Stormwind and the Alliance.", d=18.400, v="human-male", P={ { d=9.208 }, { d=3.360, n=true }, { d=10.078 } }, nP={ [1]={ [2]=3.080 } } },
	},
	[276067] = {
		{ f="276067-2af62916", h="2af62916", t="It's my job to get the Paladins of Bandarion Keep set up with proper arms and armor. It's not much, but it's honest work.    I've got a thing or two for sale as well, should you need gear.", d=10.920, v="scourge-male" },
	},
	[276110] = {
		{ f="276110-2fc3ff64", h="2fc3ff64", t="My oath binds me to this place. What brings you here, to this light-forsaken place?", d=5.674, v="human-male" },
	},
	[276170] = {
		{ f="276170-e50e47b5", h="e50e47b5", t="I am Belanaa Windveil and I am an agent of the High Order here on Azeroth. If you'd like to make a donation of cloth to our organization, we would be most grateful.", d=10.840, v="skyborne-female" },
	},
	[276171] = {
		{ f="276171-1e85fa3a", h="1e85fa3a", t="We shen'dorei have need of additional cloth to replenish our supplies. Any donations you make would be put to good use, and surely raise your esteem with the Windshapers.", d=10.920, v="skyborne-female" },
	},
	[276316] = {
		{ f="276316-1b05d5c3", h="1b05d5c3", t="If ye want to see the elven port of Auberdine and all its mysterious mist, you've come to the right dock. If ye also want to see the beauty and glory of Menethil Harbor, even better--same ship'll take ye there, too!    It ain't a journey for the weak, but if you've got the spirit of adventure in yer gullet then yer in luck!", d=20.798, v="human-male" },
		{ f="276316-2d041d67", h="2d041d67", t="Looking for adventure, are ye? Well, look no further!    This here dock serves the one an' only boat that'll take ye to the distant elven lands of Darkshore, and Menethil Harbor without even leaving yer stateroom! How's that for adventure?!", d=15.060, v="human-male" },
	},
	[276318] = {
		{ f="276318-6ecded70", h="6ecded70", t="This dock connects Stormwind to the lands of the kaldorei via Auberdine, the port town of Darkshore. If you wish to travel there, the boat arrives frequently.", d=10.320, v="nightelf-male" },
		{ f="276318-71f5c09f", h="71f5c09f", t="If you seek travel to Auberdine in Darkshore, you have come to the right place. Our people welcome any Alliance members who wish to trade, travel, or aid others in our lands.", d=10.240, v="nightelf-male" },
	},
	[276731] = {
		{ f="276731-7627e1d7", h="7627e1d7", t="<The great cat stretches its long nimble legs as you approach, making no sound with the motion.>", P={ { d=6.360, n=true } }, nP={ [1]={ [1]=6.640 } } },
	},
	[276732] = {
		{ f="276732-f26348b8", h="f26348b8", t="<The great cat lets out a small huff as you near it.>", P={ { d=3.600, n=true } }, nP={ [1]={ [1]=3.680 } } },
	},
	[276737] = {
		{ f="276737-939f012f", h="939f012f", t="<This ram watches you with interest before lowering its head.>", P={ { d=3.960, n=true } }, nP={ [1]={ [1]=4.720 } } },
	},
	[276779] = {
		{ f="276779-e5b03b3b", h="e5b03b3b", t="<The ram lets out a snort, its frosty breath visible in the chill Dun Morogh air.>", P={ { d=6.320, n=true } }, nP={ [1]={ [1]=6.000 } } },
	},
	[276785] = {
		{ f="276785-f4872a90", h="f4872a90", t="<The horse's ears swivel towards you and it looks alert.>", d=3.840, v="narrator", n={ [1]=4.080 } },
	},
	[276786] = {
		{ f="276786-8db232c3", h="8db232c3", t="<The horse's calm demeanor and even-keeled temperament evident in its stance.>", d=5.720, v="narrator", n={ [1]=5.720 } },
	},
	[276787] = {
		{ f="276787-14e280f5", h="14e280f5", t="<The steed eyes follow your movements from under its heavily armored helm.>", d=4.360, v="narrator", n={ [1]=5.000 } },
	},
	[276793] = {
		{ f="276793-157fd859", h="157fd859", t="<The $r warhorse cocks its head to the side, and chomps at its bridle as it regards you.>", d=6.680, v="narrator", n={ [1]=6.480 } },
	},
	[276796] = {
		{ f="276796-f52e5607", h="f52e5607", t="<The $r warhorse cranes it next in your direction to stare at you with two milky unblinking eyes.>", d=7.760, v="narrator", n={ [1]=8.280 } },
	},
	[276797] = {
		{ f="276797-866d28ab", h="866d28ab", t="<The warhorse paws at the ground, causing the unholy flames around its chipped hoof to flicker with the motion.>", d=6.720, v="narrator", n={ [1]=6.480 } },
	},
	[277024] = {
		{ f="277024-589a8d2d", h="589a8d2d", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, ink night elf tattoos, anything you might need!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=11.800, v="goblin-male" },
		{ f="277024-6f25fb7c", h="6f25fb7c", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, ink $r tattoos, anything you might need!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=12.560, v="goblin-male" },
	},
	[277037] = {
		{ f="277037-589a8d2d", h="589a8d2d", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, ink night elf tattoos, anything you might need!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=18.280, v="goblin-female" },
	},
	[277042] = {
		{ f="277042-589a8d2d", h="589a8d2d", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, ink night elf tattoos, anything you might need!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=17.000, v="goblin-female" },
		{ f="277042-6f25fb7c", h="6f25fb7c", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, ink $r tattoos, anything you might need!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=19.760, v="goblin-female" },
	},
	[277055] = {
		{ f="277055-98eee030", h="98eee030", t="Welcome, friend, to the barbershop! Come for a cut? A coloring? Something else, perhaps?    We can groom facial hair, perform piercings, reshape tusks and horns, and even modify undead features!    Have a seat and we'll get right to work. You're only moments away from a new, more attractive you...", d=12.320, v="goblin-male" },
	},
}
